/* Automatisch erzeugt – KI-übersetzt, nicht von Hand bearbeiten. */
window.MTEC_NEWS_I18N = {"_info": {"sprache": "bg", "hinweis": "KI-übersetzt aus dem Deutschen. _src = Prüfsumme des deutschen Originals; weicht sie ab, zeigt die Website das deutsche Original (scripts/update-news.mjs check warnt)."}, "2026-11-12-amd-26-11-1-ssd-fix": {"titel": "AMD Adrenalin 26.11.1 отстранява постоянния запис върху SSD", "schlagzeile": "Драйвер Radeon 26.11.1: AMD най-сетне спира постоянния запис по SSD", "kurz": "AMD пусна незадължителния драйвер Adrenalin 26.11.1. Той официално отстранява грешката, заради която драйверът постоянно записваше данни на SSD във фонов режим. Списъкът с известни проблеми обаче се удължи.", "zusammenfassung": "Потребители на Radeon откриха, че драйверът Adrenalin постоянно записва данни на диска във фонов режим, дори в покой. heise предупреди, че това може да застраши живота на SSD, а досега помагаше само безплатен инструмент от общността. Сега според Wccftech и Neowin AMD пусна незадължителния драйвер 26.11.1, който трябва официално да реши проблема. Според бележките към версията засегнати са собствениците на Radeon RX 7000 и RX 9000, а грешката се появяваше и при местене или преоразмеряване на прозорци. Списъкът с известни проблеми включва девет нови точки, главно сривове и таймаути на драйвера в отделни игри като Cyberpunk 2077 и War Thunder. При картите RX 9000 AMD посочва и графични дефекти в Phantom Blade Zero. Засегнатите от проблема със SSD трябва да инсталират обновлението, след което могат да премахнат инструмента от общността.", "weitere_links": ["Neowin", "heise online"], "_src": "336a15b3"}, "2026-11-12-gdc-umfrage-entlassungen": {"titel": "Анкета на GDC: всеки трети анкетиран в игровата индустрия е бил съкратен за две години", "schlagzeile": "Анкета на GDC: всеки трети анкетиран от игровата индустрия е съкратен", "kurz": "В новата анкета на GDC сред над 2600 професионалисти 34 процента казват, че са били съкратени през последните две години. Над половината от тях все още нямат работа. Според анкетата настроението в индустрията е лошо.", "zusammenfassung": "15-ото издание на анкетата „State of the Game Industry“ на GDC обхваща над 2600 професионалисти от индустрията по света, съобщава VGC. 34 процента казват, че са били съкратени през последните две години, а в САЩ дори 39 процента. В анкетата от януари стойността е била 28 процента. От съкратените 54 процента все още са без работа, а 27 процента са подали поне 100 кандидатури. 17 процента са били съкратени дори два пъти за две години. Само 45 процента от работещите смятат работата си поне донякъде сигурна за следващите дванадесет месеца. 81 процента се притесняват за бъдещето си в индустрията.", "_src": "f0c14b73"}, "2026-11-12-steam-pruefstau-ki": {"titel": "Задръстване в проверките на Steam заради поток от AI игри: още инди игри се отлагат", "schlagzeile": "Поток от AI игри в Steam: инди игри засядат в опашката на Valve", "kurz": "Проверката на нови игри в Steam в момента отнема до дванадесет дни, според разработчиците заради поток от нискокачествени AI игри. Няколко инди заглавия трябваше да отложат премиерата си. Valve затегна правилата за подаване, но критиците смятат, че това не стига.", "zusammenfassung": "От началото на ноември разработчици се оплакват от дълго чакане за одобрение от Valve на нови игри и билдове в Steam. Според Eurogamer Valve обяснява, че проверките могат да отнемат до дванадесет дни заради броя подадени игри, които трябва да бъдат проверени отново. Като причина се сочи поток от евтини игри, създадени с генеративен AI. Tower defense играта Australia Did It на Рами Исмаил и Aesthetician Labs трябваше да излезе на 10 ноември и все още чака одобрение. Amazing Slot Survivor също трябваше да оттегли датата си 13 ноември, засегнати са и други инди игри. Valve въведе по-строги правила за подаване, за да отсява по-рано игри, изцяло генерирани с AI. Исмаил смята, че Valve не може да остане неутрална към AI, без да навреди на истинските разработчици.", "_src": "5412161f"}, "2026-11-12-windows-signdrop-zero-day": {"titel": "SignDrop: нова zero-day уязвимост в Windows дава SYSTEM права, корекция още няма", "schlagzeile": "Zero-day SignDrop в Windows: SYSTEM права и все още без корекция", "kurz": "Изследовател по сигурността публикува SignDrop, нова непоправена уязвимост в Windows заедно с експлойт. Тя дава на нападателите SYSTEM права и заобикаля самозащитата на антивирусния софтуер. Според изследователя са засегнати около 80 процента от инсталациите на Windows.", "zusammenfassung": "Според BleepingComputer изследователят Абделхамид Насери, известен като Nightmare Eclipse, е публикувал нов zero-day експлойт за Windows. SignDrop използва точно защитна мярка, която Microsoft въведе през октомври 2025 г. за драйвера Common Log File System (CLFS). По заобиколен път привилегировани процеси като Windows Defender могат да бъдат накарани да създават файлове със SYSTEM права. Според Насери така може да се заобиколи и защитата срещу намеса на антивирусен и EDR софтуер. Той е тествал Windows 11 26H2 и Windows Server 2025 и смята, че около 80 процента от инсталациите са уязвими. Уязвими са системите, при които стойността в регистъра за режима на удостоверяване на CLFS е 0 или 1. Според Насери няма заобиколно решение и потребителите трябва да чакат корекция от Microsoft. Статията не споменава позиция на Microsoft.", "_src": "d8efd221"}, "2026-11-12-gta6-karte-leak": {"titel": "GTA 6: отпечатаната карта от Collector's Edition е изтекла чрез мърч събитие", "schlagzeile": "Изтичане: Картата на GTA 6 вече в мрежата седмица преди премиерата?", "kurz": "В мрежата се разпространяват снимки на отпечатана стилизирана карта на Леонида, която уж е от Collector's Edition на GTA 6. Снимките уж идват от мърч акция в Selfridges във Великобритания. Rockstar не е коментирала, а картата вероятно не е точно копие на игровия свят.", "zusammenfassung": "Седмица преди излизането на GTA 6 на 19 ноември се появяват снимки на карта, съобщават VGC и Insider Gaming. Те уж показват отпечатаната карта от Collector's Edition и идват от GTA 6 акция на веригата универсални магазини Selfridges. Според VGC най-ясната снимка е от вече изтрит Instagram профил, а друга снимка показва сгънатата карта във витрина в Манчестър. Според Insider Gaming източникът е служител на Selfridges, но това не е доказано. Картата показва Леонида стилизирано с окръзи и мотиви в стил клипарт, като монстър тракове, НЛО и самолети. Insider Gaming смята, че тя не отразява точно игровия свят. Rockstar не е потвърдила снимките. Който иска да избегне спойлери, трябва да внимава в социалните мрежи.", "weitere_links": ["Insider Gaming", "Polygon"], "_src": "a2e2106c"}, "2026-11-12-xbox-25-sharma-memo": {"titel": "25 години Xbox: Аша Шарма загатва за разработка с AI в меморандум, плюс Halo Firefight и Xbox Playback", "schlagzeile": "25 години Xbox: шефката иска малки екипи да строят огромни светове", "kurz": "За 25-ия рожден ден на Xbox шефката Аша Шарма публикува меморандум, който силно напомня за генеративен AI. Малки екипи ще могат да строят светове, за които днес са нужни стотици разработчици. Xbox обяви и режим Firefight за Halo: Campaign Evolved и годишния преглед Xbox Playback.", "zusammenfassung": "Шефката на Xbox Аша Шарма публикува за 25-годишнината меморандум със заглавие „25 Years of Xbox“. В края пише, че твърде много идеи никога не стават игри и че това трябва да се промени. Скоро един човек ще има възможности, за които някога са били нужни цели нации, а малки екипи ще могат да строят светове, които днес изискват стотици разработчици. Според Eurogamer терминът генеративен AI не се използва, но формулировките силно го подсказват. Шарма идва от AI отдела на Microsoft, но при встъпването си като шеф на Xbox каза, че има „нулева толерантност към лош AI“. За годишнината тя обяви в X и режим Firefight за Halo: Campaign Evolved, който идва като безплатно обновление тази зима; според Insider Gaming това е PvE режим за четирима играчи. Освен това се разпространява Xbox Playback, преглед на собствените игри и постижения в Xbox. Xbox не посочи конкретни AI проекти в меморандума.", "weitere_links": ["IGN", "Insider Gaming", "Asha Sharma auf X (Halo Firefight)"], "_src": "0b7ff29f"}, "2026-11-12-gta6-suedkorea-freigabe": {"titel": "GTA 6 едва не остана без възрастова категория в Южна Корея заради сцени с голота", "schlagzeile": "GTA 6 почти забранена? Южна Корея спори седмици за голотата", "kurz": "Южнокорейският орган за класификация GCRB дълго не можа да се разбере за GTA 6. Спорният момент беше голотата без сексуален контекст. Накрая играта получи категория „само за възрастни“ с осем гласа срещу един.", "zusammenfassung": "Според IGN Германия Rockstar е подала заявка за възрастова категория в Южна Корея на 1 септември. Първото гласуване на GCRB на 10 септември завършило наравно: трима членове искали да откажат категория, трима били за „само за възрастни“. Според протоколите от заседанията, получени от InvenGlobal, някои членове възразили срещу сцени с голота без сексуален контекст. Решението било отложено, докато не бъде налична играема версия, а няколко дати били изместени. На 18 октомври комисията решила с осем гласа срещу един категория „само за възрастни“. Отказ би спрял напълно продажбите в Южна Корея. GTA 6 излиза на 19 ноември за PS5 и Xbox Series X и S.", "weitere_links": ["Polygon"], "_src": "c47f9d24"}, "2026-11-12-nvidia-linux-nvroot-forgeptr": {"titel": "NvRoot и ForgePtr: публикувани са две уязвимости в Linux драйвера на Nvidia, обявени са още 25", "schlagzeile": "Linux драйверът на Nvidia: уязвимост дава root на процеси в контейнер", "kurz": "Фирмата за сигурност Stealthium публикува две уязвимости в отворените модули за ядрото на Nvidia за Linux. Чрез ForgePtr процес в GPU контейнер може да получи root на хоста. Корекции вече има, а предстоят още 25 разкрития.", "zusammenfassung": "Според Phoronix първите две от общо 27 обявени уязвимости в драйверния стек на Nvidia вече са публични. ForgePtr (CVE-2026-47501) позволява на непривилегирован процес в GPU контейнер да получи root права на хоста. С NvRoot (CVE-2026-47591) GPU може да презаписва файлове, които операционната система е маркирала само за четене. И двете уязвимости съществуват от около четири години в отворените модули на Nvidia и са оценени като високи (CVSS 7,8). Особено засегнати са облачните доставчици, които отдават GPU на множество клиенти. NvRoot е поправена в драйверите 610.57.04, 595.91.07 и 580.178.04, а ForgePtr в 615.71.09. Според Phoronix Stealthium е обявила още 25 разкрития, свързани с AI софтуерния стек на Nvidia. Който използва GPU на Nvidia под Linux, особено в контейнери, трябва да обнови драйвера.", "_src": "fa81fb4c"}, "2026-11-12-huang-ruecktritt-kress": {"titel": "Дженсън Хуанг се оттегля като CEO на Nvidia след 33 години, финансовият директор Колет Крес поема временно", "schlagzeile": "Край на една ера: Дженсън Хуанг подава оставка в Nvidia", "kurz": "Nvidia обяви оставката на съоснователя и CEO Дженсън Хуанг, който напуска всички постове с незабавен ефект. Финансовият директор Колет Крес ще ръководи компанията засега като временен CEO. Председател на борда става Харви К. Джоунс.", "zusammenfassung": "След дни на криза вече е официално: Дженсън Хуанг напуска ръководството на Nvidia след 33 години. Според ComputerBase той се отказва от постовете президент, CEO и член на борда, а според PC Gamer с незабавен ефект. Хуанг не е уволнен; според TechPowerUp той е подписал писмо за оставка. Поводът са публикации за две извънбрачни връзки, включително с мениджърка, която му е била пряко подчинена. Преди това бордът е заседавал извънредно, а според Bloomberg вече е наета външна фирма за търсене на наследник. Финансовият директор Колет Крес ръководи бизнеса като временен CEO и едновременно остава CFO. Председател на борда става Харви К. Джоунс. Крес заяви, че ще надгражда основата, която Хуанг е изградил за 33 години. От съобщението не става ясно дали Хуанг ще има роля в компанията в бъдеще. Кой ще бъде постоянен CEO е открит въпрос; засега има само спекулации. Последици за продуктите GeForce, цените или драйверите засега не са известни.", "weitere_links": ["PC Games Hardware", "TechPowerUp", "PC Gamer", "heise online"], "_src": "330d1f5e"}, "2026-11-12-paradox-wester-ruecktritt": {"titel": "Шефът на Paradox Фредрик Вестер се оттегля, Матиас Лиля поема през януари", "schlagzeile": "След провала на Bloodlines 2: Paradox получава нов шеф", "kurz": "CEO на Paradox Interactive Фредрик Вестер напуска поста си и преминава в борда на директорите. Заместникът му Матиас Лиля поема на 4 януари 2027 г. Издателят има зад гърба си няколко трудни години.", "zusammenfassung": "Според Eurogamer Фредрик Вестер се оттегля като CEO на Paradox Interactive и като член на борда ще се занимава с дългосрочното развитие. Наследник ще бъде досегашният заместник-CEO Матиас Лиля от 4 януари 2027 г., като дотогава Вестер остава на поста. Вестер ръководи Paradox от 2009 до 2018 г. и отново от 2021 г. Вторият му мандат включва трудната разработка на Vampire: The Masquerade Bloodlines 2, чийто търговски провал рязко срина оперативната печалба. Към това се добавят спирането на Life by You, отлагането на Prison Architect 2 и тежкият старт на Cities: Skylines 2, чиято конзолна версия все още липсва. Лиля иска да инвестира повече в основния бизнес и да работи по-тясно с играчите и модърите. Следващите игри са Lego Skylines и стратегията Afterworld.", "_src": "b6ea62b9"}, "2026-11-12-siren-halo-gddr7": {"titel": "Слух: Siren Halo на AMD ще използва графична памет GDDR7 вместо само LPDDR5X", "schlagzeile": "Изтичане: Ще получи ли мега-APU-то Siren Halo на AMD истинска GDDR7?", "kurz": "Според информатор бъдещото Halo APU на AMD, Siren Halo, ще работи с памет GDDR7. Сегашните Halo чипове използват обща памет LPDDR5X за CPU и GPU. Нищо не е потвърдено.", "zusammenfassung": "Хардуерният информатор Gotou_kai3 твърди, че Siren Halo на AMD ще получи памет GDDR7, съобщават Wccftech и PCGH. Подобно на Medusa Halo, Siren Halo ще използва Zen 6 и RDNA 5, но ще бъде истински наследник, а не просто обновление. Сегашните Halo чипове като Strix Halo използват LPDDR5X като обща памет за CPU и GPU. GDDR7 би дала много по-голяма пропускателна способност, което може да помогне особено на графиката в игрите. Според Wccftech не е ясно дали CPU и GPU ще могат да ползват и двата пула памет, или GDDR7 ще бъде само за графиката. За AI задачи графично решение само с GDDR7 може да е по-малко гъвкаво от голямата обща памет на сегашните чипове Ryzen AI Max. AMD не е анонсирала Siren Halo, а срокове и спецификации не са известни.", "weitere_links": ["Wccftech"], "_src": "6fee7dbc"}, "2026-11-12-apache-http2-luecke": {"titel": "Критична уязвимост в HTTP/2 модула на Apache: препоръчва се обновяване до 2.4.71", "schlagzeile": "Критична уязвимост в Apache: обновете уеб сървърите с HTTP/2 веднага", "kurz": "Уеб сървърът Apache има критична уязвимост в модула mod_http2, която може да позволи отдалечено изпълнение на код. Засегнати са само сървъри с включен HTTP/2. Версия 2.4.71 отстранява грешката.", "zusammenfassung": "Според heise уязвимостта CVE-2026-119618 се намира във функцията assign_headers() на модула mod_http2. Манипулация на паметта там може да доведе до отдалечено изпълнение на зловреден код. Според Golem Red Hat оценява уязвимостта с 9,8 от 10 точки. Открили са я OSS скенер на Anthropic и двама изследователи от Google Cloud Vulnerability Research. Тъй като mod_http2 не е включен по подразбиране, засегнати са само сървъри, които използват HTTP/2. Експерти като Кевин Бомонт смятат експлойта за труден заради защити като ASLR. Въпреки това администраторите трябва да обновят до Apache 2.4.71, която затваря още две уязвимости. Който не може да обнови веднага, трябва засега да изключи HTTP/2.", "weitere_links": ["Golem.de"], "_src": "8ac52b3f"}, "2026-11-12-rtx5090-96gb-mod": {"titel": "Модифицирана RTX 5090 с 96 GB памет се появи на китайски пазар за употребявани стоки", "schlagzeile": "RTX 5090 с 96 GB: китайски мод за около 900 000 долара", "kurz": "На китайската платформа Xianyu се предлага модифицирана GeForce RTX 5090 с 96 GB видеопамет. Ориентировъчната цена е около 900 000 долара, а реалната се договаря лично. Не е доказано, че картата наистина работи.", "zusammenfassung": "Китайски модъри пренасят настолни GPU на собствени платки и многократно увеличават паметта за AI задачи. Сега според Wccftech и PCGH се е появила обява за RTX 5090 с 96 GB, колкото има RTX Pro 6000. Забелязал я е специалистът по ремонти VIK-on в Xianyu, пазара за употребявани стоки на Alibaba, а първи е съобщил VideoCardz. Чипът GB202 е на собствена платка с чипове памет Samsung от двете страни. Освен картата продавачът предлага схеми на платката и модифициран BIOS, но се насочва само към бизнес клиенти с договор за поверителност. Посочената цена от 6 488 888 юана, около 900 000 долара, е ориентировъчна; реалната цена се договаря лично. Няма бенчмаркове, така че работоспособността на картата не е потвърдена.", "weitere_links": ["Wccftech"], "_src": "4c5d0781"}, "2026-11-12-swtor-directx12-test": {"titel": "Star Wars: The Old Republic започва публичен тест на DirectX 12, графиката първоначално е умишлено опростена", "schlagzeile": "SWTOR получава DirectX 12 – и засега изглежда по-зле", "kurz": "Почти 15 години след излизането си Star Wars: The Old Republic тества клиент с DirectX 12. Публичният тест започва тази седмица директно в обичайния лаунчер. Много графични ефекти в началото липсват умишлено.", "zusammenfassung": "Според PC Games студиото Broadsword модернизира технологията на MMORPG Star Wars: The Old Republic. Тази седмица започва публичен тест на новия DirectX 12 клиент, без регистрация и код за достъп. В обичайния лаунчер малка стрелка позволява избор между старата и новата версия; и двете използват същите сървъри и герои. Много детайли от средата и ефекти все още липсват или са опростени в новия клиент, ограничени са и графичните настройки. Това е умишлено: първо се цели стабилност, производителност и съвместимост с възможно най-много компютри. Играчите трябва да докладват накъсване, графични грешки и сривове заедно с хардуера си. За играчи на Mac тестът засега не е достъпен. Според Broadsword проектът ще продължи до късно през 2027 г., след което графиката постепенно трябва да достигне поне старото ниво.", "_src": "b512307b"}, "2026-11-12-apex-neural-rendering": {"titel": "Apex Neural Rendering: стартъп обещава независима от производителя алтернатива на DLSS, FSR и XeSS", "schlagzeile": "По-добро от DLSS? Apex носи генериране на кадри и за трите GPU лагера", "kurz": "Компанията Apex Compute представи Apex Neural Rendering (ANR) със супер резолюция, реконструкция на лъчи и генериране на кадри за GeForce, Radeon и Arc. Генерирането на кадри вече е достъпно като безплатна бета в GitHub. Обещанията са големи, но според ComputerBase трудно могат да се проверят.", "zusammenfassung": "Apex Compute, досега специализирана в AI ускорители за edge, иска да се конкурира с DLSS, FSR и XeSS чрез Apex Neural Rendering (ANR). ANR трябва да предлага супер резолюция, реконструкция на лъчи и генериране на кадри независимо от производителя на Nvidia, AMD и Intel. Според компанията то е до 2,4 пъти по-бързо и дава по-добро качество на картината от DLSS. Засега е налично само генерирането на кадри като безплатна бета в GitHub; то се вгражда чрез OptiScaler и има режими 2×, 3× и 4×. Според Apex супер резолюцията и реконструкцията на лъчи са още в разработка. Според ComputerBase генерирането на кадри работи от GeForce GTX 16 и RTX 2000 нагоре, от Radeon RX 5000 нагоре включително Steam Deck и на Intel Arc A, под Windows 10, Windows 11 и Linux с Proton. ComputerBase критикува несъответствия в данните на производителя, например уж измервания на FSR с повече от един AI кадър, и неясни фактори в сравнителните видеа. Все още няма независими тестове, така че обещанията за производителност и качество не са потвърдени.", "weitere_links": ["TechPowerUp", "Wccftech", "GamingOnLinux"], "_src": "6efb8d9d"}, "2026-11-12-samsung-hbm-onyang": {"titel": "Недостиг на памет: Samsung строи нова линия за пакетиране на HBM и иска да я завърши година по-рано", "schlagzeile": "RAM кризата: Samsung изтегля новата HBM фабрика с година напред", "kurz": "Samsung започна в Онянг строежа на нова линия за пакетиране на HBM. Тя трябва да заработи през юни 2028 г., година по-рано от планираното. Причината е продължаващият недостиг на памет.", "zusammenfassung": "Според ComputerBase Samsung направи първа копка в кампуса си в Онянг, Асан, на нова производствена линия за пакетиране на HBM памет. Работата трябва да започне през юни 2028 г., година по-рано от първоначалния план. Samsung инвестира в Онянг 46 трилиона вона, около 31 милиарда евро, като по-голямата част е за оборудване. Предвидени са около 31 000 квадратни метра чисти помещения на три етажа и около 700 нови работни места. През октомври Samsung заяви, че вече е договорила доставките на HBM за 2027 г. и далеч не може да покрие търсенето. HBM се използва главно в AI ускорители, но недостигът натоварва целия пазар на памет и така и цените на RAM за потребителите на PC. В краткосрочен план новата линия няма да промени цените.", "_src": "7ecef997"}, "2026-11-12-outlook-mails-blockiert": {"titel": "Outlook.com: дефектно правило за спам отхвърляше истински имейли дни наред – съобщенията са изгубени", "schlagzeile": "Outlook отхвърляше имейли дни наред – и те няма да се върнат", "kurz": "Дефектно правило за спам на Microsoft дни наред отхвърляше легитимни имейли до адреси в Outlook.com, Hotmail и Live. Microsoft отмени ъпдейта и подателите и получателите не трябва да променят нищо. Отхвърлените имейли обаче не могат да бъдат възстановени, затова трябва да помолите подателите да ги изпратят отново.", "zusammenfassung": "Ако пощата ви в Outlook.com напоследък беше подозрително тиха, може да сте засегнати. Според Windows Latest поне от 5 ноември легитимни имейли до адреси в Outlook.com, Hotmail, Live и MSN са били отхвърляни. Подателите получаваха съобщения за грешка, че в имейлите им липсват SPF, DKIM или DMARC записи, макар че това отчасти не беше вярно. Microsoft потвърди пред Windows Latest, че причината е ъпдейт на правилата за спам. Компанията го отмени и според Windows Latest пощата отново работи от 9 ноември. Нито подателите, нито получателите трябва да променят настройки. Проблемът: отхвърлените имейли не са попаднали в папката за спам, а изобщо не са пристигнали. Затова Microsoft не може да ги възстанови. Който е очаквал важни имейли, трябва да помоли подателите да ги изпратят отново. Администраторите намират инцидента в административния център на Microsoft 365 под номер EX1545193. Microsoft не казва колко потребители са засегнати.", "_src": "74d3487f"}, "2026-11-12-powershell-signatur-kb5132061": {"titel": "Ноемврийският ъпдейт KB5132061: по-строга проверка проваля някои подписани PowerShell скриптове", "schlagzeile": "Ъпдейт на Windows спира подписани PowerShell скриптове – ето решението", "kurz": "С ноемврийския ъпдейт за сигурност Windows проверява по-строго кодирането на текста в подписани PowerShell скриптове. Скриптове с дефектен UTF-8 тогава може да се смятат за неподписани и да спрат да работят както досега в управлявани среди. Microsoft препоръчва да се запазят като UTF-8 с BOM и да се подпишат отново.", "zusammenfassung": "С ъпдейта KB5132061 от 10 ноември Microsoft затегна проверката на подписите в PowerShell. Досега Windows все още можеше да обработва скриптове с невалиден UTF-8, като заменяше дефектните знаци. Това вече не става и засегнатите файлове се отхвърлят. Според Microsoft тогава Get-AuthenticodeSignature показва „NotSigned“ за скрипт, който всъщност е подписан. Set-AuthenticodeSignature може да прекъсне с грешка. На устройства с App Control for Business засегнатите скриптове може да работят само в ограничен езиков режим. Засегнати са най-вече скриптове с дефектен UTF-8, UTF-8 без BOM в системи с друга кодова страница и файлове в кодировки като Shift-JIS. Microsoft препоръчва скриптовете да се проверят, да се запазят като валиден UTF-8 с BOM и да се подпишат отново. Примерен скрипт с име Repair-SignedPowerShellUtf8.ps1 открива засегнатите файлове и не презаписва оригинали. Според Neowin промяната важи не само за Windows 11, а и за Windows 10 Enterprise LTSC 2021 и Windows Server 2025. Домашните потребители без подписани скриптове обикновено няма да забележат нищо.", "weitere_links": ["Microsoft Support (KB5132061)", "Microsoft Support (ръководство за кодиране)"], "_src": "22fabd49"}, "2026-11-12-tomb-raider-catalyst-switch2": {"titel": "Amazon посочва Tomb Raider: Catalyst и за Nintendo Switch 2", "schlagzeile": "Tomb Raider: Catalyst вероятно идва и за Switch 2", "kurz": "Публикация на официалния новинарски сайт на Amazon посочва Switch 2 като платформа и за двете предстоящи игри Tomb Raider. За Legacy of Atlantis това беше известно, за Catalyst досега не. Amazon е издател на Catalyst, но потвърждение от Crystal Dynamics или Nintendo все още липсва.", "zusammenfassung": "Според Insider Gaming в публикация на Amazon News, обновена на 9 ноември, пише, че двете нови игри Tomb Raider ще излязат за PS5, Xbox Series X/S, Nintendo Switch 2 и Steam. За Tomb Raider: Legacy of Atlantis (2027) версията за Switch 2 вече беше официална, а играта може да се поръча предварително в eShop. Новото е посочването на Tomb Raider: Catalyst. Играта беше отложена тази година за 2028 г. Catalyst се издава от Amazon Game Studios, което придава тежест на информацията. Insider Gaming все пак допуска грешка в статията, макар че тя е онлайн без промени от два дни. Crystal Dynamics и Nintendo все още не са потвърдили версията за Switch 2. Няма технически подробности, нито дата за версията за Switch 2.", "_src": "de9ab1dc"}, "2026-11-12-steam-erfolge-linux-64bit": {"titel": "Ъпдейт на клиента Steam: Achievement Sets за всички, а Linux клиентът най-сетне работи като 64-битова програма", "schlagzeile": "Ъпдейт на Steam: нови комплекти постижения и 64 бита за Linux", "kurz": "Valve пусна нов ъпдейт на Steam за всички потребители. Игрите вече могат да групират постиженията в комплекти за основната игра и DLC, без да се губи 100-процентовото завършване. В Linux клиентът Steam вече е 64-битова програма и работи в контейнер Steam Runtime.", "zusammenfassung": "На 11 ноември Valve пусна ъпдейт на клиента Steam в стабилния канал. Най-важната новост за всички са Steam Achievement Sets. С тях разработчиците могат да групират постиженията по основна игра и DLC. Така нови постижения или постижения от DLC вече не правят непълна една вече завършена колекция. Сезонни или вече непостижими постижения могат да се архивират. Добавена е и преработена страница с постижения. В Linux клиентът Steam вече е 64-битово приложение и работи в контейнер Steam Runtime. Според Valve това трябва да осигури еднакво поведение в различните дистрибуции; това е същата технология, която използват и игрите. Според TechPowerUp досега Steam в Linux все още беше 32-битова програма. Ъпдейтът поправя и, наред с други неща, срив при събуждане от режим на заспиване. Дали разработчиците ще използват новите комплекти постижения, зависи от тях.", "weitere_links": ["Steam (обявление за Achievement Sets)", "9to5Linux"], "_src": "95507831"}, "2026-11-12-witcher3-ki-stimme-geralt": {"titel": "The Witcher 3: CD Projekt коригира с ИИ полския глас на Гералт в новото разширение – със съгласието на актьора", "schlagzeile": "След инсулт: ИИ връща младежкото звучене на полския глас на Гералт", "kurz": "В предстоящото разширение на The Witcher 3, Songs of the Past, полският глас на Гералт се обработва с ИИ. Актьорът Яцек Розенек записва всички реплики сам, но гласът му се промени забележимо след инсулт през 2019 г. С негово съгласие ИИ компанията Respeecher го доближава до някогашното му звучене.", "zusammenfassung": "CD Projekt Red потвърди, че използва ИИ в полската версия на новото разширение на The Witcher 3, Songs of the Past. Първо за това съобщи Game File, а PC Gamer, VGC и IGN подеха темата. Яцек Розенек винаги е озвучавал Гералт на полски, но през 2019 г. претърпя инсулт и временно не можеше да говори. След дълги тренировки той се върна, но днес гласът му звучи по-ниско и по-грубо. Тъй като разширението се развива в средата на историята на The Witcher 3, разликата можеше да се усети. Затова Розенек продължава сам да записва всички реплики, а Respeecher след това ги доближава до звученето му отпреди около дванайсет години. Моделът е обучен с по-ранните му записи за играта. Розенек изрично подкрепя това и казва, че гласът трябва да е възможно най-близо до някогашния. Продуцентът по локализация Миколай Швед говори за специален случай заради заболяването и вижда в това етична употреба със съгласие. Според CD Projekt нищо подобно не се планира за английския глас на Дъг Кокъл. CD Projekt вече работи с Respeecher по Cyberpunk 2077: Phantom Liberty, тогава със съгласието на семейството на починал актьор. В публикациите няма дата за Songs of the Past.", "weitere_links": ["VGC", "IGN"], "_src": "b5c1fa87"}, "2026-11-12-helldivers2-kosmetik-mods": {"titel": "Helldivers 2: след смяната на анти-чийт системата и вълната от ревюта козметичните модове трябва да се върнат със следващия хотфикс", "schlagzeile": "Helldivers 2: Arrowhead иска отново да разреши безобидните модове", "kurz": "След преминаването към Easy Anti-Cheat много модове в Helldivers 2 вече не работят, а в Steam последваха над 10 000 негативни ревюта. Arrowhead обявява, че някои чисто козметични модове трябва отново да работят със следващия хотфикс. Модовете, които променят геймплея, остават забранени.", "zusammenfassung": "Arrowhead смени в Helldivers 2 анти-чийт системата от GameGuard на Easy Anti-Cheat. Според студиото целта е била да се спрат модове, които дават нечестно предимство или вредят на други. При това обаче спряха да работят и безобидни козметични модове. Реакцията беше остра: според PC Gamer в Steam се появиха над 10 000 нови негативни ревюта, а последните оценки са „предимно негативни“. В новия си блог за разработката Arrowhead признава, че PC играчите са загубили фенски модове. След корекции някои козметични модове трябва отново да работят със следващия хотфикс. Модовете, които променят геймплея, остават забранени, защото технически не могат да се различат от чийтове. Модовете все така нямат официална поддръжка. Arrowhead се извинява и за неточна пътна карта и пропуснати дати за пачове. За началото на декември са планирани, наред с други неща, реактивни раници, които могат да се ползват при носене на двуръчни предмети. Студиото не посочва дата за хотфикса.", "_src": "0f2f4919"}, "2026-11-12-marvel-1943-fast-fertig": {"titel": "Доклад: Marvel 1943: Rise of Hydra е почти готова, но значително по-малка от планираното", "schlagzeile": "Изтичане: Почти готова ли е Marvel 1943 – но силно орязана?", "kurz": "След слухове за спиране Kotaku съобщава, че Marvel 1943: Rise of Hydra е почти завършена. Играта обаче ще предлага значително по-малко съдържание и геймплей дълбочина от планираното. Skydance не е коментирала официално.", "zusammenfassung": "Около Marvel 1943: Rise of Hydra, играта на Ейми Хениг с Капитан Америка и Черната пантера, напоследък имаше слухове за предстоящо спиране. Според Kotaku и репортера на Bloomberg Джейсън Шрайър ръководството на Skydance е съобщило на служителите в Slack, че това не е вярно. Kotaku съобщава също, че играта е „close to done“, тоест почти готова. Разработката обаче е била трудна и значително е надхвърлила бюджета. Затова обхватът и продължителността са били силно съкратени. Според източниците на Kotaku играта е „light on gameplay“, като голяма част се управлява с един бутон. Marvel 1943 е започнала като игра за Netflix. Обявена е през 2024 г. и оттогава е отлагана няколко пъти. Няма дата за излизане. Всички сведения идват от анонимни източници и Skydance не ги е потвърдила.", "ursprungsquelle": "Kotaku (чрез IGN)", "_src": "3cff0819"}, "2026-11-12-nvidia-board-huang-abloesung": {"titel": "Според медии бордът на Nvidia обмисля отстраняването на CEO Дженсън Хуанг и вече търси наследник", "schlagzeile": "Смяна на върха на Nvidia? Бордът обсъжда отстраняване на Хуанг", "kurz": "Според Wall Street Journal бордът на директорите на Nvidia подготвя отстраняването на основателя и CEO Дженсън Хуанг. Поводът е статия на New York Times за втора извънбрачна връзка, този път с мениджърка, пряко подчинена на него. Според Bloomberg външна фирма вече търси наследници. До обяд Nvidia все още не е обявила решение; съобщенията се базират на анонимни източници.", "zusammenfassung": "Кризата около шефа на Nvidia Дженсън Хуанг се задълбочава. Според Wall Street Journal бордът е искал да заседава в сряда вечерта (американско време) за бъдещето на Хуанг, като отстраняване е било на масата. Поводът е нова статия на New York Times: освен вече признатата афера Хуанг е имал връзка и с вицепрезидентка, която докладва пряко на него. Вестникът се позовава на петима бивши служители и заявява, че сам не е виждал предполагаемо видео от инцидент през март. Нито Nvidia, нито засегнатите са потвърдили информацията. Според Bloomberg бордът вече работи с външна фирма за търсене на наследник, обмисля се и временен CEO. На заден план е разследването, започнало в неделя, за аферата на Хуанг с мениджърка на клиента на Nvidia Megaspeed, която американските власти са определили като предполагаем китайски агент; Китай отрича. Хуанг ръководи Nvidia от основаването ѝ през 1993 г., а според PCGH няма посочен наследник. Според PCGH за отстраняването му е достатъчно обикновено мнозинство на директорите. След публикациите акциите поевтиняха с около осем процента в извънборсовата търговия и паднаха до 52-седмично дъно. Nvidia представя тримесечните си резултати на 17 ноември, а на 18 ноември е планиран поверителен брифинг в Конгреса на САЩ. Засега не са известни конкретни последици за картите GeForce, цените или драйверите. Важно: всичко се основава на медийни публикации с анонимни източници от Wall Street Journal, New York Times и Bloomberg; до обяд Nvidia не е обявила решение и ситуацията може да се променя.", "weitere_links": ["PC Games Hardware", "heise online", "Golem.de", "IGN", "PC Gamer"], "_src": "f0402e6d"}, "2026-11-12-golden-joystick-2026": {"titel": "Golden Joystick Awards 2026: Resident Evil Requiem е игра на годината, Crimson Desert печели на PC", "schlagzeile": "Golden Joysticks: Resident Evil Requiem взе „Игра на годината“", "kurz": "На 44-тите Golden Joystick Awards Resident Evil Requiem спечели голямата награда Ultimate Game of the Year. Най-добра игра за PC стана Crimson Desert. Мултиплейър хитът Meccha Chameleon грабна четири награди, а The Witcher 4 е най-очакваната игра.", "zusammenfassung": "Golden Joystick Awards се смятат за най-старото зрителско гласуване в гейминг индустрията и през 2026 г. се проведоха за 44-ти път. Голямата награда Ultimate Game of the Year спечели Resident Evil Requiem на Capcom. Хорър играта спечели и като най-добра конзолна игра, за най-добър трейлър и за най-добра главна роля – Анджела Сант'Албано като Грейс Ашкрофт. Според TheGameVerse Capcom беше избрано и за студио на годината. Най-добра игра за PC стана Crimson Desert, макар че излиза и на конзоли. Играта на криеница Meccha Chameleon спечели четири награди: най-добра мултиплейър игра, най-добра самоиздадена инди игра, Streamer's Choice и Developers' Choice. The Witcher 3: Wild Hunt Remastered стана най-добър ремастър, а The Witcher 4 – най-очаквана игра. Феновете избраха Steam Controller за най-добър гейминг хардуер. Други награди получиха Onimusha: Way of the Sword (звук), Control: Resonant (визуален дизайн), Doom: The Dark Ages – Revelations (разширение) и Subnautica 2 (ранен достъп). Наградите се организират от издателя на PC Gamer.", "weitere_links": ["TheGameVerse в X (списък с победители)"], "_src": "d4e2e75f"}, "2026-11-12-gta6-clip-realistisch": {"titel": "GTA 6: Rockstar споделя клип от играта, който мнозина смятат за истинско видео от телефон в Маями", "schlagzeile": "Реалност или GTA 6? Нов клип на Rockstar заблуди интернет", "kurz": "Около 15-секунден клип от GTA 6 от първо лице предизвиква спорове, защото мнозина го смятат за истинско видео. Той пресъздава реално видео от телефон с колите от GTA по време на маркетинговата акция в Маями. Rockstar сподели клипа в своята история в Instagram, което според IGN говори за истински кадри от играта.", "zusammenfassung": "Седмица преди премиерата на GTA 6 кратък клип предизвиква удивление. Той се появи първо в профила в Instagram „Only in Dade“, който събира странни сцени от Маями-Дейд. В него се вижда шофиране по Ocean Drive покрай редица впечатляващи коли, както и втора гледна точка от тротоара. Според IGN, Polygon и Insider Gaming клипът пресъздава истинско видео, заснето през октомври по време на маркетинговата акция на Rockstar с пресъздадени коли от GTA в Маями. Много зрители първоначално го взеха за реални кадри или за ИИ. Rockstar сподели клипа в историята си в Instagram и го хареса, което IGN смята за силен знак за истински кадри от играта. Според Polygon обаче Rockstar не го е потвърдила изрично. Феновете предполагат, че така може да изглеждат записите с камерата на телефона в играта. Insider Gaming подчертава, че клипът не казва нищо за евентуален режим от първо лице. GTA 6 излиза на 19 ноември за PS5 и Xbox Series X/S и според Rockstar работи с 30 fps на конзолите. Предварителното изтегляне вече тече.", "weitere_links": ["Insider Gaming", "Polygon", "GamePro (преглед на новините)"], "_src": "34198252"}, "2026-11-12-black-forest-games-unabhaengig": {"titel": "Black Forest Games се откупува от Embracer и основава групата студиа Third Signal", "schlagzeile": "Германското студио на Destroy All Humans се откупи от Embracer", "kurz": "Германското студио Black Forest Games се отдели от THQ Nordic и Embracer чрез обратно изкупуване от ръководството. Едновременно с това основава Third Signal – група от независими студиа. Екипът ще продължи да работи с THQ Nordic.", "zusammenfassung": "След девет години под шапката на THQ Nordic и Embracer Black Forest Games отново е независимо. Според Eurogamer и PC Gamer това стана чрез обратно изкупуване от ръководството. Студиото е разработило, наред с други, Giana Sisters: Twisted Dreams и римейковете на първите две игри Destroy All Humans. То е основано от бивши служители на Spellbound Entertainment, известна с Desperados и Arcania: Gothic 4. Заедно с независимостта стартира Third Signal – група от независими студиа, която в бъдеще трябва да помага и на други инди екипи. Шефът на Third Signal Андреас Тоблер казва по същество, че много от най-добрите игри на последното десетилетие са създадени от екипи от 50, а не от 500 души. Според прессъобщението THQ Nordic и Black Forest Games ще продължат да си сътрудничат в разработката. Студиото явно не е поело правата върху Destroy All Humans. Управителят Адриан Гьорш обявява нов проект, без подробности. През 2024 г. студиото беше засегнато от съкращенията в Embracer и загуби тогава около 50 работни места.", "weitere_links": ["PC Gamer"], "_src": "7dfb6efd"}, "2026-11-12-nintendo-dmca-github": {"titel": "Nintendo премахва чрез DMCA 144 хранилища в GitHub с фърмуер за модчипове за Switch и два емулатора", "schlagzeile": "Nintendo чисти GitHub: емулатори за Switch и фърмуер за модчипове изчезват", "kurz": "Nintendo изпрати четири DMCA искания до GitHub срещу емулаторите за Switch Yuzu и Citron Neo, както и срещу фърмуер за модчипове. GitHub премахна 144 хранилища с този фърмуер. Според TorrentFreak обаче той все още може да се намери на други места в платформата.", "zusammenfassung": "Nintendo отново действа срещу инструменти за заобикаляне на защитата срещу копиране на Switch. Според IGN GitHub е получил четири DMCA искания, които е публикувал. На прицел са емулаторите Yuzu и Citron Neo, но най-вече фърмуерът за модчипове като Picofly. Такива чипове се запояват към дънната платка на Switch и заобикалят защитата срещу копиране. GitHub премахна 144 хранилища с фърмуера и ги замени с известие за DMCA. В искането си от 6 ноември Nintendo твърди, че техническите мерки за защита трябва да предотвратяват играенето на пиратски копия и на неоторизирани устройства. Според TorrentFreak обаче фърмуерът все още е наличен на други места в GitHub. Още през 2024 г. Nintendo премахна около 8500 копия на Yuzu. IGN свързва новата вълна с информации, че емулатори малко преди това са пуснали на PC новия римейк на Ocarina of Time; пряка връзка не е доказана. Дали Nintendo планира още стъпки, е неясно.", "_src": "788c053c"}, "2026-11-12-id-veteranen-hidden-horses": {"titel": "Около 20 бивши разработчици от id Software основават студиото Hidden Horses и планират арена шутър", "schlagzeile": "След съкращенията в Xbox: бивши от id основават собствено шутър студио", "kurz": "Около 20 бивши разработчици от id Software основаха Hidden Horses – студио, собственост на самите служители. Първият им проект е самостоятелният арена шутър Danger Pay. Той ще бъде финансиран, наред с другото, чрез Kickstarter.", "zusammenfassung": "При съкращенията в Xbox през юли 2026 г. id Software е загубила според информациите 136 разработчици. Около 20 от тях сега основаха Hidden Horses – студио, собственост на служителите. Според PC Gamer основателите имат общо над 250 години опит. Студиото ще се управлява демократично и ще поставя дългосрочната стабилност пред бързия растеж и съмнителната монетизация. Съоснователят Дъстин Ланд казва, че искат да запазят екипа заедно и да правят класически шутъри. Първата игра се казва Danger Pay – самостоятелен арена шутър за брутално телевизионно шоу. Като вдъхновение студиото посочва филма The Running Man от 1987 г. и аркадната игра Smash TV. За финансирането е планирана кампания в Kickstarter. Платформи, дата и старт на Kickstarter все още не са известни.", "_src": "2eb4f3a4"}, "2026-11-12-tes6-sentinel-pause": {"titel": "Bethesda: няма новини за The Elder Scrolls 6: Sentinel за годишнината на Skyrim – и няма да има „известно време“", "schlagzeile": "15 години Skyrim, но без Elder Scrolls 6: Bethesda охлажда феновете", "kurz": "За 15-ия рожден ден на Skyrim феновете се надяваха на новини за The Elder Scrolls 6: Sentinel. Bethesda Game Studios уточни в Reddit, че няма да има голямо обявяване. Нищо ново за Sentinel няма да има „известно време“.", "zusammenfassung": "The Elder Scrolls V: Skyrim навърши 15 години на 11 ноември. В subreddit-а на The Elder Scrolls 6 феновете гадаеха за изненада за годишнината, подхранена от тийзър на подкаст за „голямо обявяване“. Водещият по-късно уточни, че то няма нищо общо с Bethesda. След това се обади и официалният профил на Bethesda Game Studios в Reddit. Няма да има голямо обявяване и нищо ново за Sentinel няма да бъде показано „известно време“, написа студиото. Bethesda официално обяви заглавието Sentinel едва в началото на ноември. The Elder Scrolls 6 беше анонсирана още през 2018 г. За годишнината Skyrim е с намаление на всички платформи. The Elder Scrolls Online прави главата Greymoor безплатна част от основната игра, а там тече събитие за Skyrim до 2 декември. Кога ще има нова информация за Sentinel, не е ясно.", "weitere_links": ["PC Gamer"], "_src": "85003521"}, "2026-11-11-xbox-cloud-ohne-game-pass": {"titel": "Xbox Cloud Gaming без Game Pass: купете игрово време или играйте безплатно с реклами", "schlagzeile": "Xbox Cloud Gaming се отваря: купете часове или играйте безплатно с реклами", "kurz": "От 11 ноември играчите в поддържаните държави могат да купуват игрово време в облака на Xbox и без абонамент за Game Pass. Xbox рекламира и безплатен стрийминг с реклами, с ограничение на времето за сесия. Могат да се стриймват само собствени игри или избрани free-to-play заглавия.", "zusammenfassung": "Microsoft преустройва Xbox Cloud Gaming. Според Xbox Wire от 11 ноември играчите на поддържаните пазари могат да купуват игрово време в облака в Xbox Store, без да се абонират за Game Pass. По време на теста за Insider пакетите без реклами струваха 3,99 долара за 10, 7,99 долара за 25 и 11,99 долара за 50 часа; това бяха изрично встъпителни цени, а цени в евро източниците не посочват. Купените часове не изтичат и според Xbox предлагат по-кратко чакане и по-добро качество на стрийма. На официалната страница за облачни игри и в X Xbox рекламира и безплатен стрийминг с реклами, където е наличен, с ограничения на времето за сесия. В теста за Insider ограничението беше един час според The Verge. Могат да се стриймват собствени игри, избрани free-to-play заглавия и игри от Game Pass. От ноември абонатите на Game Pass имат месечни лимити: 15 часа при Ultimate, 10 при Premium и 5 при Essential. След като ги изразходват, могат да докупят часове или да преминат към варианта с реклами. Точно навреме GTA 6 излиза на 19 ноември чрез облака и за Xbox One. Кои държави ще бъдат включени от старта, не е ясно.", "weitere_links": ["Xbox Wire (GTA VI в облака, игрово време от 11.11)", "Xbox Cloud Gaming (официална страница)", "Xbox Wire (цени в теста Insider)", "Xbox Wire (месечни лимити)", "The Verge"], "_src": "cfedef5c"}, "2026-11-11-dark-souls-server-zurueck": {"titel": "Dark Souls 2 и 3: онлайн функциите отново работят след почти две седмици прекъсване", "schlagzeile": "Dark Souls 2 и 3 отново са онлайн – причината остава тайна", "kurz": "След почти две седмици пауза онлайн функциите на Dark Souls 2 и 3 отново работят на всички платформи. Според PC Gamer нахлуванията и съобщенията отново функционират. FromSoftware не разкри какъв точно е бил проблемът със сървърите.", "zusammenfassung": "Сървърите на Dark Souls 2 и Dark Souls 3 отново работят. Почти две седмици по-рано мултиплейър функциите на двете игри бяха изключени на всички платформи заради необяснен проблем със сървъра. На официалния сайт на Dark Souls сега кратко пише, че проверката е приключила, корекция е приложена и онлайн функциите са възстановени. Според PC Gamer нахлуванията и съобщенията отново работят както обикновено. FromSoftware все още не посочва причината. За сравнение: през 2022 г. PC сървърите на всички игри Dark Souls бяха офлайн почти година, тогава заради уязвимост, позволяваща изпълнение на зловреден код. Дали и този път зад това стои проблем със сигурността, не е известно. По време на паузата помагаха фенски модове като Seamless Co-op, които работят независимо от официалните сървъри. Който иска да играе класическите нахлувания, вече може отново.", "_src": "76889d66"}, "2026-11-11-kb5132061-installationsfehler": {"titel": "Windows 11: Microsoft потвърди грешки при инсталиране на KB5132061 и разпространява автоматичен ремонт", "schlagzeile": "Microsoft потвърди грешката KB5132061 – поправката идва сама", "kurz": "Microsoft вече официално потвърди проблемите с инсталацията на ноемврийската актуализация за сигурност KB5132061. На засегнатите компютри с Windows 11 инсталацията се прекъсва или се опитва многократно; типичните кодове за грешка са 0x800f0993, 0x800f0989 и 0x80070306. Според Microsoft ремонтът се изпълнява автоматично чрез Windows Update и трябва да достигне засегнатите устройства в рамките на 24 до 48 часа след старта в сряда в 19:00 виенско време; след това актуализацията за сигурност се инсталира сама. Потребителите не трябва да правят нищо, освен да останат онлайн и да получават актуализациите през Настройки.", "zusammenfassung": "Ноемврийската актуализация за сигурност KB5132061 не може да се инсталира на част от компютрите с Windows 11, инсталацията понякога спира едва при 99 процента, а повторните опити често не помагат. Съобщават се кодовете за грешка 0x800f0993, 0x800f0989 и 0x80070306, понякога и 0x800f0922. Microsoft документира проблема в сряда като известен проблем в английските бележки към изданието на KB5132061. Според компанията ремонтът се изпълнява автоматично на засегнатите устройства, които са свързани с интернет и използват Windows Update в Настройки; не са нужни ръчни стъпки, за да го получите. Всички засегнати устройства трябва да получат поправката в рамките на 24 до 48 часа след старта в сряда в 19:00 виенско време (10:00 тихоокеанско време) и след това сами да изтеглят и инсталират актуализацията за сигурност. Служебно съобщение на Microsoft, цитирано от BleepingComputer, уточнява, че е засегната само част от устройствата с незадължителната октомврийска предварителна актуализация KB5127936; устройствата без нея не са засегнати. Microsoft не посочва точната причина. По-рано Windows Latest и порталът DrWindows съобщиха за грешките, но много системи никога не бяха засегнати. По-ранните съвети да се изключи Windows Sandbox или да се пуснат DISM и sfc остават на заден план, защото компанията вече съветва да се изчака автоматичният ремонт. Който след изтичането на 48-те часа все още не може да инсталира актуализацията, според Microsoft трябва да използва помощта на Windows или да се свърже с поддръжката. Това си остава актуализация за сигурност, затова не бива да се спира трайно.", "weitere_links": ["Dr. Windows", "BleepingComputer", "Neowin", "Windows Latest"], "_src": "7755549c"}, "2026-11-11-harada-xbox-series-s": {"titel": "Бившият шеф на Tekken Кацухиро Харада: конзоли като Xbox Series S не би трябвало да излизат", "schlagzeile": "Легендата на Tekken Харада за Series S: „допълнителна работа за по-слабо дете“", "kurz": "Кацухиро Харада разкритикува Xbox Series S на конференция за разработчици в Южна Корея, докато в залата имаше представител на Xbox. Основният проблем според него е, че конзолата много прилича на Series X, но е осезаемо по-слаба. Разработчик от CD Projekt възрази, че оптимизацията помага на всички платформи.", "zusammenfassung": "Кацухиро Харада, дълги години ръководител на поредицата Tekken, а днес шеф на новото VS Studio, говори открито за Xbox Series S на Console Game Developers Conference 2026 в Южна Корея. Според Inven Global, цитиран от Eurogamer, той заяви пред присъстващ висш представител на Xbox, че би искал хардуер като Series S да не излиза. Най-големият проблем не е само ограничената памет, а това, че конзолата много прилича на Series X и въпреки това е неудобно по-слаба. След най-добрата версия усещането е като да вършиш допълнителна работа за малко по-слабо дете. При Switch 2 пък може да се мисли за отделно устройство за феновете на Nintendo. Тъй като например в САЩ има повече потребители на Series S, отколкото на Series X, не може да се пести, а оплакванията за по-лоши текстури после стигат до разработчиците. Павел Саско от CD Projekt Red възрази, че оптимизацията за по-слаб хардуер кара игрите да вървят значително по-добре на всички платформи, а ниската цена разширява пазара. Техническият директор на Shift Up ДонгКи Ли каза, че очаква с нетърпение следващия Xbox с кодово име Helix. Става дума за мнение, изразено на панел, а не за официална позиция на Microsoft или на някое студио.", "weitere_links": ["Video Games Chronicle", "PC Gamer"], "_src": "8dad0743"}, "2026-11-11-rtx5080-24gb-gestrichen": {"titel": "Съобщения: Nvidia е отменила RTX 5080 с 24 GB – моделът с 16 GB остава", "schlagzeile": "Изтичане: Nvidia е отменила RTX 5080 с 24 GB", "kurz": "Според китайския браншов канал Board Channels Nvidia е уведомила партньорите си, че планираната за януари 2027 г. RTX 5080 с 24 GB се отменя. Причината били скъпите чипове GDDR7 по 3 GB. RTX 5080 с 16 GB продължавала да се произвежда. Nvidia не е потвърдила нищо от това.", "zusammenfassung": "Според нови съобщения засега няма да има RTX 5080 с 24 GB видеопамет. TechPowerUp цитира китайския браншов канал Board Channels, според който Nvidia официално е уведомила производителите на карти, че планираното за януари 2027 г. пускане отпада. Като причина се посочват разходите: според публикацията, цитирана от PC Gamer, чиповете GDDR7 по 3 GB струват около три пъти повече от използваните досега чипове по 2 GB. С по-скъпата памет картата би трябвало да излезе на цена, която трудно би се продавала. Затова познатата RTX 5080 с 16 GB продължавала да се произвежда. Според по-ранни слухове моделът с 24 GB щял да има същия брой изчислителни блокове, но повече памет, по-голяма пропускателна способност и малко по-високи честоти. PC Gamer припомня, че преди дори се говореше, че версията с 24 GB може да замени RTX 5090 и варианта с 16 GB; мениджърът на Nvidia Джеф Фишър обаче подчерта, че производството на RTX 5090 не е спряно. Според TechPowerUp не се очертава Super обновление, а следващата голяма стъпка би била серията RTX 60. Важно: самият модел с 24 GB никога не е обявяван официално, така че става дума за слух за края на един слух. Nvidia не е коментирала.", "ursprungsquelle": "Board Channels (via VideoCardz, Gazlog, harukaze5719)", "weitere_links": ["PC Gamer", "PC Games Hardware", "Wccftech"], "_src": "2c9fc45e"}, "2026-11-11-gta6-de-cix-rekord": {"titel": "Предварително изтегляне на GTA 6: интернет възелът DE-CIX отчита нов рекорд", "schlagzeile": "Изтеглянето на GTA 6 счупи рекорд: 22,3 терабита в секунда във Франкфурт", "kurz": "През първата вечер на предварителното изтегляне на GTA 6 интернет възелът DE-CIX във Франкфурт измери нов пик от 22,30 терабита в секунда. Операторът отчита и световен рекорд. GTA 6 ще може да се играе от полунощ на 19 ноември.", "zusammenfassung": "Стартът на предварителното изтегляне на Grand Theft Auto VI остави измерими следи в мрежата. Както операторът на DE-CIX съобщи на Golem, възелът във Франкфурт достигна на 10 ноември в 20:20 ч. нов пик от 22,30 терабита в секунда. Това е с 19,06 процента повече от предишния рекорд от януари 2026 г. Общо за всички локации на DE-CIX по света бяха измерени 33,01 терабита в секунда, също рекорд. Техническият директор на DE-CIX Томас Кинг обясни, че големите премиери на игри са сред събитията, които могат много бързо силно да вдигнат трафика. По обем на данните DE-CIX Франкфурт се смята за най-големия интернет възел в Европа. Предварителното изтегляне за PS5 и Xbox Series X|S започна в нощта срещу 10 ноември, а файлът е около 210 до 212 GB. Според PC Games и германски интернет доставчик е отчел многократно по-голям от обичайния игрови трафик. GTA 6 ще може да се играе от полунощ на 19 ноември. Дали самият ден на премиерата ще донесе нови рекорди, предстои да видим.", "weitere_links": ["PC Games"], "_src": "b0fe5f64"}, "2026-11-11-mh-wilds-ascendance-beta": {"titel": "Промени в Steam подсказват бета за разширението Ascendance на Monster Hunter Wilds", "schlagzeile": "Изтичане: Ще получи ли Monster Hunter Wilds: Ascendance скоро бета?", "kurz": "Capcom тихо преименува в Steam старото бета приложение на Monster Hunter Wilds на „Ascendance Beta test“, както показва SteamDB. Това подсказва предстоящ тест на разширението. Capcom все още не е обявила нищо, дата не е известна.", "zusammenfassung": "Първото голямо разширение за Monster Hunter Wilds се казва Ascendance и трябва да излезе през 2027 г. Според Eurogamer и PC Gamer Capcom вече е преименувала в Steam старото бета приложение на основната игра. Според дневника на промените в SteamDB то вече се казва Monster Hunter Wilds: Ascendance Beta test и е получило ново основно изображение. Това подсказва предстоящ бета тест. Тъй като приложението има същото ID като по-ранната бета на Wilds, то може да се появи отново в библиотеките на бившите тестери; тогава отделна регистрация може да не е нужна. Кога би могла да започне бета, е напълно неясно; Eurogamer предпазливо залага на началото на 2027 г. Capcom последно показа Ascendance на септемврийския State of Play и на Tokyo Game Show, включително завръщащия се Древен дракон Teostra. Разширението трябва да е по-трудно, след като много играчи намериха основната игра за твърде лесна при излизането ѝ. Става дума за индикации от данни в Steam, а не за официално обявяване.", "ursprungsquelle": "SteamDB-Änderungsprotokoll (via PC Gamer)", "weitere_links": ["PC Gamer"], "_src": "2faf2355"}, "2026-11-11-radeon-ssd-fix-tool": {"titel": "Неофициален инструмент с отворен код спира постоянния запис на atieclxx.exe върху SSD", "schlagzeile": "Драйверът на Radeon износва SSD: безплатен инструмент спира записа", "kurz": "Разработчик от общността публикува в GitHub безплатен инструмент срещу бъга на Radeon, при който atieclxx.exe се копира върху SSD всяка секунда. Той проверява дали компютърът е засегнат, оценява износването и блокира записа, без да изключва услугата. Това е неофициално решение, не от AMD.", "zusammenfassung": "На някои компютри с драйвер Radeon или драйвер за чипсет на AMD файлът atieclxx.exe, който принадлежи към услугата AMD External Events Utility, се копира сам всяка секунда. Това създава постоянно натоварване със запис на системния диск и дори без използване бързо се натрупват стотици гигабайти, което ненужно състарява SSD. Член на общността с името Necandi публикува в GitHub инструмента Radeon-atieclxx-SSD-Fix, съобщават ComputerBase и Wccftech. Първо той проверява дали системата е засегната и оценява досегашното износване на SSD. Оценката е груба: приема, че бъгът съществува от поставянето на картата на AMD, а ако SSD не отчита време на работа, смята с осем часа работа на ден. Вместо да изключва услугата, инструментът само забранява на системния акаунт да презаписва копието. Така опитът за копиране се проваля, а FreeSync, frame pacing и бързите клавиши би трябвало да продължат да работят. Предишни решения като спиране на услугата или изключване на Resizable BAR можеха да създават проблеми точно там. Който не иска инструмент, според ComputerBase може сам да отнеме правата с команда icacls и по-късно да ги възстанови. Разработчикът подчертава, че няма връзка с AMD и че използването е на собствена отговорност. AMD обяви официална корекция с драйвер 26.11.1, която още не е излязла.", "weitere_links": ["Wccftech"], "_src": "3c8c1851"}, "2026-11-11-zen6-epyc-tests": {"titel": "AMD Epyc 9006 Venice в продажба: първите тестове показват голям скок за Zen 6", "schlagzeile": "Първи тестове на Zen 6: 256-ядреният чип на AMD е с 58% по-бърз", "kurz": "AMD вече официално продава сървърните процесори Epyc 9006 Venice със Zen 6. В първите независими тестове на Phoronix топ моделът Epyc 9996 е средно 1,58 пъти по-бърз от досегашния флагман Zen 5c. За геймърите това е първи поглед към архитектурата на бъдещите чипове Ryzen.", "zusammenfassung": "AMD обяви старта на продажбите на шестото поколение Epyc с кодово име Venice, представено още през юли. Началото е с девет модела за сокет SP7, а според Golem в началото на 2027 г. следват още 22 за SP8. Phoronix успя да тества двата топ модела. Epyc 9996 има 256 ядра Zen 6c, до 4,1 GHz и TDP 600 вата и според ценовата листа на AMD струва 14 904 долара. В двусокетна система той средно по всички тестове постига 1,58 пъти производителността на предшественика Epyc 9965 със 192 ядра. При HPC приложения е около два пъти по-бърз от Intel Xeon 6980P и въпреки по-високата консумация дава най-добрата производителност на ват. Според Golem компактните ядра печелят от по-големи чиплети с 32 вместо 12 ядра. Вторият тестван чип, Epyc 9686F, има 96 ядра Zen 6 с до 5,3 GHz. За геймърите това са сървърни чипове, но те за първи път независимо показват какво може архитектурата Zen 6, която по-късно се очаква и в процесорите Ryzen. Колко от това ще стигне до игрите, не може да се изведе от сървърни тестове. Phoronix посочва и че пълната производителност изисква бърза памет MRDIMM, която при сегашната криза с RAM вероятно ще е много скъпа.", "weitere_links": ["Phoronix (тест на Epyc 9996)", "PC Games Hardware", "AMD в X"], "_src": "f935df7f"}, "2026-11-11-zelda-oot-5-2-mio": {"titel": "Римейкът на Zelda: Ocarina of Time продаде над 5,2 милиона копия за четири дни", "schlagzeile": "Римейкът на Zelda счупи рекорд на Switch 2: 5,2 милиона за четири дни", "kurz": "Nintendo съобщава за над 5,2 милиона продадени копия на римейка на Ocarina of Time през първите четири дни. Това е най-бързият старт на продажбите на игра на Nintendo за Switch 2. Според Nintendo става дума за реални продажби, а не само за доставки към търговците.", "zusammenfassung": "Римейкът на The Legend of Zelda: Ocarina of Time е голям успех за Nintendo. Според прессъобщение на компанията през първите четири дни след излизането на 5 ноември по света са продадени над 5,2 милиона копия. Така това е най-успешният старт на продажбите на издадена от Nintendo игра за Switch 2, според Golem както в света, така и в Европа. Според Golem Nintendo говори за реално продадени бройки, а не само за доставки към търговците. Няма разбивка по региони или между дигитални и физически копия. Рекордът се отнася изрично до собствените игри на Nintendo, подчертава Eurogamer. Римейкът е приет много добре и от критиката: Golem посочва среден резултат 96 точки в Metacritic. Нови са например графиката, саундтракът, озвучаването и преработените битки. Успехът е забележителен и защото играта излезе само две седмици преди GTA 6. Римейкът е част от честванията за 40-годишнината на поредицата Zelda.", "weitere_links": ["Golem.de", "IGN Deutschland"], "_src": "6dbb5df2"}, "2026-11-11-ps5-100-millionen": {"titel": "Sony потвърди: PlayStation 5 е продадена в над 100 милиона бройки", "schlagzeile": "PS5 надхвърли 100 милиона – точно зад първия PlayStation", "kurz": "Sony потвърди, че към 10 ноември към търговците са доставени над 100 милиона PS5. Така конзолата изпреварва PS3 и PSP и е точно зад първия PlayStation със 102,4 милиона. Напоследък обаче продажбите са осезаемо по-бавни от година по-рано.", "zusammenfassung": "PlayStation 5 достигна кръгла граница: според официалния преглед на продажбите на Sony до 10 ноември 2026 г. са доставени над 100 милиона конзоли. Броят включва доставки към търговците (sell-in), а не продажби на крайни клиенти. Така PS5 изпревари PS3 (87,4 милиона) и PSP (76,4 милиона). Първият PlayStation е все още малко напред със 102,4 милиона, а PS4 със 117 милиона и PS2 с над 160 милиона са далеч напред. Темпото се забави: според Insider Gaming през първото тримесечие на фискалната година са доставени 1,6 милиона броя вместо 2,5 милиона, а през второто 2,6 вместо 4 милиона. Най-силната година беше фискалната 2023 г. с 20,8 милиона конзоли. Sony посочва и 127 милиона активни месечни потребители на PlayStation към 30 септември. При софтуера PS4 и PS5 имат 154,3 милиона продадени бройки след две тримесечия на текущата фискална година. Доколко GTA 6 ще повиши продажбите на конзоли от 19 ноември, ще покажат едва данните за третото тримесечие.", "weitere_links": ["Insider Gaming"], "_src": "0a83a0a1"}, "2026-11-11-nvidia-aktie-china-chips": {"titel": "Акциите на Nvidia на най-ниското си ниво от март: доклад говори за над 240 000 AI системи, стигнали до Китай чрез мрежа от фирми", "schlagzeile": "Акциите на Nvidia падат още: чипове за 7,5 млрд. $ са отишли в Китай?", "kurz": "След два дни на загуби акциите на Nvidia затвориха във вторник на 168,89 долара, най-ниското ниво от края на март. Microsoft за кратко я изпревари по пазарна стойност. Според доклад на The Information жената, с която Дженсън Хуанг призна за връзка, е доставила в Китай системи на Nvidia за поне 7,5 милиарда долара.", "zusammenfassung": "Скандалът около главния изпълнителен директор на Nvidia Дженсън Хуанг продължава да тежи на борсата. След спад от над 4% в понеделник акциите паднаха с още 5,5% във вторник и затвориха на 168,89 долара, най-ниското ниво от 30 март. Пазарната стойност остава малко над 4 трилиона долара; в началото на октомври беше над 5,5 трилиона. Microsoft беше за кратко пред Nvidia във вторник, а Apple я беше изпреварила още преди обвиненията да станат известни. Поводът е нов доклад на The Information, който цитира двама души, познаващи Алис Хуанг, с която шефът на Nvidia призна за връзка. Тя е позволила чрез мрежа от фирми доставки за Китай на над 240 000 системи A100, H100 и H200 на стойност поне 7,5 милиарда долара. За A100 и H100 от октомври 2022 г. важат американски ограничения за износ. Според доклада роля играят китайската компания за центрове за данни Century Litong и сингапурската фирма Megaspeed, която от октомври 2023 г. е сред предпочитаните облачни партньори на Nvidia. Американски власти настоявали Megaspeed да бъде включена в черен списък. Китай отхвърля обвинението в шпионаж. Nvidia започна вътрешно разследване, което според анализатор, цитиран от CNBC, може да продължи четири до шест седмици. Същият анализатор оценява вероятността Хуанг да загуби поста си на около 15%. Данните за доставките идват от анонимни източници и не са официално потвърдени.", "weitere_links": ["heise online (доклад за доставките в Китай)"], "_src": "3a8f3e41"}, "2026-11-11-fortis-games-schliessung": {"titel": "Мобилното студио Fortis Games затваря, засегнати са около 440 работни места, Las Vegas Sands спира финансирането", "schlagzeile": "Fortis Games затваря – около 440 работни места, казино гигантът спира парите", "kurz": "Основаното през 2022 г. мобилно студио Fortis Games затвори, засегнати са около 440 позиции. Според бивш служител инвеститорът Las Vegas Sands е прекратил финансирането и всички договори по света. Двете игри на студиото бяха все още в ранна тестова фаза.", "zusammenfassung": "Поредно голямо затваряне в игралната индустрия: Fortis Games вече не съществува, засегнати са около 440 работни места. Главният изпълнителен директор Стивън Чианг потвърди затварянето пред GamesBeat на 10 ноември. Той каза, че екипът е разочарован, че след над пет години не е постигнал целите си, и сега ще се съсредоточи върху това да помогне на служителите да намерят нова работа. Бивш продуцент написа в LinkedIn, че компанията майка Las Vegas Sands е решила да спре финансирането и да прекрати всички договори по света. Студиото от Сан Франциско е основано през 2022 г. от Чианг, който преди това е работил в Electronic Arts и Zynga. Fortis работеше по мобилните игри Twilight Towers и Bloom & Breakfast, които бяха в ранен soft launch; според продуцента със солидни показатели. Бивш директор по комуникациите пък написа, че подходът, ориентиран към общността, не е намерил достатъчен отклик сред играчите. Какво ще стане с двете игри, не е известно.", "_src": "2298d3f0"}, "2026-11-11-windows11-speicherintegritaet": {"titel": "Windows 11 вече включва автоматично целостта на паметта (HVCI) на повече компютри – защита, която може да забави игрите", "schlagzeile": "Windows 11 включва целостта на паметта – какво означава това за геймърите", "kurz": "С ноемврийската актуализация Windows 11 автоматично включва целостта на паметта (HVCI) на повече съществуващи компютри. Защитата блокира подправени драйвери, но според самия Microsoft може да струва производителност в игрите. Ако сте я изключили съзнателно, тя остава изключена, а изключването ѝ все още е възможно.", "zusammenfassung": "Microsoft затяга настройка за сигурност, която засяга геймърите. От незадължителната октомврийска актуализация, а сега и с актуализацията от Patch Tuesday KB5132061, Windows 11 може при актуализации автоматично да включва целостта на паметта, наричана още HVCI. Досега тя обикновено беше активна само на нови компютри и при чисти инсталации. Според Windows Latest промяната важи за Windows 11 25H2 и 26H2. Целостта на паметта работи в изолирана от хипервайзора на Windows зона и там проверява дали драйверите и кодът на ядрото са надеждни, така че дори превзето ядро не може да изпълни непроверен код. На някои компютри за целта ще бъде включена и базираната на виртуализация сигурност (VBS). Преди включване Windows проверява хардуера, съвместимостта на драйверите и производителността, а внедряването е постепенно. Ако сте изключили функцията сами, Windows няма да я включи отново; фирмените политики имат предимство. Уловката за геймърите: самият Microsoft преди няколко години препоръча в помощна статия да се изключи целостта на паметта за по-добра производителност в игрите. Тя може да се изключи от Защита на Windows, Защита на устройството, Подробности за изолацията на ядрото. Дали да го направите, е въпрос на баланс, защото защитата е насочена срещу зловреден софтуер, който се промъква в ядрото на Windows чрез драйвери.", "_src": "0b7240ab"}, "2026-11-10-fairgames-eingestellt": {"titel": "Sony спира live-service шутъра Fairgames след разочароващ тест, без съкращения в Haven Studios", "schlagzeile": "Sony спира Fairgames – поредният live-service шутър е история", "kurz": "PlayStation прекрати разработката на шутъра за обири Fairgames от Haven Studios. Според вътрешен имейл, за който съобщава Bloomberg, отзивите и задържането на играчите в тест не са достигнали целите. Съкращения няма да има, студиото ще подпомага други екипи на Sony.", "zusammenfassung": "Fairgames е история. Sony прекрати разработката на live-service шутъра три години след обявяването му през 2023 г., както първо съобщи Bloomberg. Във вътрешен имейл ръководителите в PlayStation Шон Декър и Джон Дойл пишат, че скорошен тест е убедил технически и организационно, но отзивите и задържането на играчите са били смесени и под целите. Заедно с трудния пазар за PvP шутъри е взето решение да не се продължава. Според съобщенията разработчикът Haven Studios няма да бъде закрит и не се планират съкращения; екипът ще подпомага други студия на Sony. Haven е основано през 2021 г. от Джейд Реймънд, която вече напусна студиото, и е купено от Sony през 2022 г. Fairgames е било преработвано няколко пъти от представянето си, а вътрешни тестове е трябвало да са приети зле още през 2025 г. Истински геймплей никога не беше показан официално, само рендерирани сцени от обявяващия трейлър. Стратегията на Sony за live-service игри от 2022 г. предвиждаше поне десет такива заглавия до 2026 г. Наред с успехи като Helldivers 2 вече има много спрени проекти и провала на Concord.", "weitere_links": ["Polygon", "IGN"], "_src": "ff8dd113"}, "2026-11-10-nvidia-tsmc-bestellungen": {"titel": "Доклад от Тайван: Nvidia може да намали поръчките на чипове в TSMC, AMD и проектантите на ASIC биха спечелили", "schlagzeile": "Изтичане: Намалява ли Nvidia поръчките си за чипове в TSMC?", "kurz": "Тайванският вестник Commercial Times съобщава, позовавайки се на неназовани източници от веригата на доставки, че Nvidia може да поръчва по-малко чипове от TSMC. Посочва се натискът от скандала около Дженсън Хуанг и по-строгите проверки за износ. Докладът не назовава продукт, производствен процес, обем или срок. Nvidia и TSMC не коментираха.", "zusammenfassung": "Nvidia може да намали поръчките си към договорния производител TSMC. Това съобщава тайванският вестник Commercial Times, позовавайки се на неназовани източници от веригата на доставки; TechPowerUp подхвана доклада. Не се казва за какви продукти, производствен процес, количества и период става дума. Като причини докладът посочва натиск отвътре и отвън: вътрешно скандалът около Дженсън Хуанг и разследването на борда на Nvidia, външно по-строгите проверки за износ. Освен това в Хонконг е трябвало да има складирани чипове H200. Споменава се и подозрението, че някои фирми, одобрени за H200, може да са фиктивни, но изрично като подозрение, а не като установен факт. Ако Nvidia освободи капацитет, вестникът очаква AMD и разработчици на собствени AI чипове като MediaTek, Alchip и GUC да го поемат. Съкращенията биха засегнали най-вече доставчици като TSMC и ASE. За геймърите това не би означавало автоматично по-евтини видеокарти, защото паметта, която в момента е в недостиг, не идва от TSMC. Докладът се основава на един източник; Nvidia и TSMC не са го коментирали. До потвърждение трябва да се приема като слух.", "ursprungsquelle": "Commercial Times (Тайван), чрез TechPowerUp", "_src": "a929a8ec"}, "2026-11-10-gta6-xbox-fsr4-dateien": {"titel": "Датамайнъри откриха FSR библиотеки на AMD в Xbox пакета на GTA 6, дали се ползва FSR 4.1.2, остава неясно", "schlagzeile": "Изтичане: Ползва ли GTA 6 на Xbox вече AI ъпскейлинга FSR 4 на AMD?", "kurz": "Предварителното изтегляне на GTA 6 за Xbox съдържа два файла на AMD, чиито имена съвпадат с интеграцията на FSR 4.1.2 за Xbox Series X|S. Това е знак, а не доказателство: файловете на играта са криптирани, а същият интерфейс може да премине и към по-стария FSR 3.1. Rockstar не е коментирал.", "zusammenfassung": "Скоро след старта на предварителното изтегляне на GTA 6 за Xbox датамайнъри откриха в инсталационния пакет две библиотеки на AMD: amd_fidelityfx_loader_xbox.dll и amd_fidelityfx_upscaler_xbox.dll. Откри ги датамайнърът Tex2, а други потребители сравниха имената с документацията на FSR 4.1.2 за Xbox Series X|S. Първи съобщи VideoCardz, а PC Games Hardware постави находката в контекст. AMD и Microsoft пуснаха FSR 4.1.2 за Xbox на 4 ноември; това е първият базиран на AI ъпскейлър за конзолите, с два INT8 модела, Full и Lite. Имената на файловете обаче не доказват, че GTA 6 наистина използва FSR 4.1.2. Същият SDK на AMD съдържа и класическия FSR 3.1.6, към който интерфейсът може да премине. Тъй като файловете на играта са криптирани, съдържанието на библиотеките още не може да се провери. За конзолите Rockstar досега потвърди само 30 fps на всички модели и PSSR на PS5 Pro; официална информация за ъпскейлинга на Xbox няма. Най-късно при старта на 19 ноември анализите би трябвало да покажат кой метод се използва.", "ursprungsquelle": "Датамайнър Tex2 (X), първо съобщено от VideoCardz", "_src": "548f3594"}, "2026-11-10-patchday-november-1235": {"titel": "Patch Tuesday на Microsoft за ноември 2026: поправени 1235 уязвимости, сред тях активно експлоатирана zero-day в Outlook", "schlagzeile": "Рекорден Patch Tuesday: 1235 уязвимости – дупка в Outlook вече се атакува", "kurz": "Microsoft поправи 1235 уязвимости в сигурността в ноемврийския Patch Tuesday, 66 от тях критични. Уязвимост за подправяне в Outlook вече се използва за кражба на данни за NTLM акаунти. Windows 11 получава KB5132061 и KB5131087, а Windows 10 в програмата ESU – KB5131096.", "zusammenfassung": "Ноемврийският Patch Tuesday на Microsoft отново е огромен: според BleepingComputer актуализациите поправят 1235 уязвимости; още 108 бяха поправени по-рано през месеца и не се броят. През октомври бяха дори 1411; Microsoft все по-често използва AI за откриване на уязвимости. 66 уязвимости са критични, 48 от тях позволяват отдалечено изпълнение на код. Около 639 засягат Windows и негови компоненти. Най-спешна е уязвимост за подправяне в Microsoft Outlook, която вече се атакува. Според Microsoft е достатъчно жертвата да отвори специално подготвен файл със съобщение: тогава Outlook се свързва със сървър на нападателите без обичайното предупреждение и може да разкрие данни за вход под формата на NTLM хешове. Windows 11 получава кумулативните актуализации KB5132061 и KB5131087, а Windows 10 22H2 в програмата за разширени актуализации на защитата – KB5131096. Според Neowin при някои потребители инсталирането на KB5132061 се проваля с грешка 0x800f0993. Въпреки това всеки, който ползва Windows или Office, трябва да инсталира актуализациите скоро, особено заради уязвимостта в Outlook.", "weitere_links": ["Dr. Windows", "Neowin (грешка при инсталиране)"], "_src": "e3b7656c"}, "2026-11-10-fritzbox-5690-pro-speicher": {"titel": "Fritz!Box 5690 Pro: според сервизните данни по-новите устройства имат само половината RAM и флаш памет при същия артикулен номер", "schlagzeile": "Fritz!Box 5690 Pro: по-новите устройства с половин памет – същият номер", "kurz": "По-новите бройки на Fritz!Box 5690 Pro очевидно имат само 1 GB RAM и 2 GB флаш вместо 2 и 4 GB. Артикулният номер и хардуерната версия са същите, разликата личи само в хардуерната подревизия. Fritz говори за обичайни за бранша промени без влияние върху производителността.", "zusammenfassung": "Който купи днес Fritz!Box 5690 Pro, не получава непременно същия хардуер като купувачите при старта. Забелязал го е потребител с две устройства: по-новото показваше значително по-голямо натоварване на RAM при същата версия на Fritz!OS. Според сервизните данни устройство от юли 2024 г. има 2 GB RAM и 4 GB флаш, а едно от юни 2026 г. само 1 GB RAM и 2 GB флаш. Използваемата за системата RAM пада така от 1754 на 742 MB, а вътрешната памет, използвана например за Fritz!NAS, се свива от около 1,7 GB на 680 MB. Вариантите се различават само по хардуерната подревизия, която се е повишила от 3 на 5; артикулният номер и хардуерната версия са същите, а отвън рутерите изглеждат еднакво. Кога точно е направена промяната, не е ясно; известно време двата варианта изглежда са доставяни паралелно. Fritz заяви пред Router-FAQ.de, че вътрешни компоненти като чиповете памет понякога се променят по време на жизнения цикъл на продукта; това било обичайно за бранша и не променяло спецификацията и производителността. Компанията не потвърди изрично намаляването наполовина. Сравнителни тестове на двата варианта още няма, неясно е и дали това ще се отрази на бъдещи актуализации. Все пак е неловко, защото при пускането през юни 2024 г. Fritz изрично рекламираше големия капацитет на паметта.", "_src": "aa5e40e9"}, "2026-11-10-auto-sr-xbox-ally-ryzen": {"titel": "Microsoft Auto SR излиза от предварителната версия на ROG Xbox Ally X и X20 и идва на Copilot+ компютри с AMD Ryzen, нов режим до 120 fps", "schlagzeile": "Мащабирането Auto SR в Windows: вече преносимо, с HDR и до 120 fps", "kurz": "AI мащабирането Auto SR на Microsoft официално стартира на преносимите конзоли ROG Xbox Ally X и X20. Новото е режим за производителност до 120 fps, работа в преносим режим без докинг станция и комбинация с Auto HDR. Auto SR вече работи и на избрани Copilot+ компютри с AMD Ryzen.", "zusammenfassung": "В блога на DirectX Microsoft обяви официалния старт на Automatic Super Resolution (Auto SR) на преносимите конзоли ROG Xbox Ally X и ROG Xbox Ally X20. Auto SR кара игрите да работят вътрешно с по-ниска резолюция и ги мащабира с изкуствен интелект на NPU, без играта да трябва да поддържа това. Досега функцията беше достъпна само като предварителна версия и само в докинг станция. Сега тя работи и на вградения екран и на батерия. Поддържат се и игри в 1080p, а на монитор Auto SR може да ги мащабира до 1440p. Нов режим за производителност вдига границата от досегашните около 60 до 75 fps до 120 fps; в примера на Microsoft с Rocket League средната стойност се е повишила от 70 на 115 fps. Освен това за първи път Auto SR и Auto HDR могат да се използват едновременно. Преносимият режим, 1080p и новите Copilot+ компютри с AMD Ryzen са достъпни веднага. Режимът за производителност и поддръжката на Auto HDR ще идват постепенно с обновления на Windows. Нужни са актуалните обновления на Windows 11, обновен Game Bar и пакетът Auto Super Resolution от Microsoft Store.", "_src": "539f5a74"}, "2026-11-10-gpu-taskman-vram": {"titel": "GPU Taskman: инструмент с отворен код показва точно кои програми колко графична памет заемат", "schlagzeile": "Кой изяжда VRAM-а ти? Безплатен инструмент го показва за всяка програма", "kurz": "Разработчикът от Microsoft и GitHub Скот Хансълман пусна инструмента с отворен код GPU Taskman. Той показва за всяка програма колко графична памет е заета, както и натоварването, температурата и честотата на GPU. Инструментът все още е експериментален.", "zusammenfassung": "Скот Хансълман, вицепрезидент в Microsoft и GitHub, разработи GPU Taskman – безплатен инструмент за командния ред. Той трябва да показва по-точно от диспечера на задачите на Windows къде отива графичната памет. Показват се заетостта на VRAM, системната памет, използвана от GPU, и отделните процеси, както и натоварване, температура, консумация, честота и стойности за PCIe. Инструментът разграничава например работния плот, браузърите, игрите и AI приложенията. При локални AI модели в llama.cpp, Ollama или LM Studio той може да изчисли отделно паметта за теглата на модела и за KV кеша. На геймърите може да помогне да открият тесни места във VRAM, които причиняват накъсване. Хансълман обаче предупреждава, че използваната системна RAM не означава автоматично препълване на VRAM, а инструментът не разпознава отделни текстури. GPU Taskman поддържа карти на NVIDIA и AMD под Windows 10 и 11, както и Linux, WSL и Mac компютри с Apple Silicon; версия 0.3.5 добавя GPU на Intel под Linux. Той е достъпен под лиценз MIT в GitHub, с преносима версия за Windows. Софтуерът все още е експериментален, а някои стойности са приблизителни.", "_src": "43537581"}, "2026-11-10-ps-plus-pc-app-ende": {"titel": "Sony спира приложението PlayStation Plus за PC на 10 декември, Death Stranding 2 влиза в каталога Extra", "schlagzeile": "Край на стрийминга на PS Plus на PC – ползвали са го само 0,4%", "kurz": "Sony спира приложението PlayStation Plus за Windows на 10.12.2026 г. и така прекратява стрийминга на игри от PS Plus на PC. Според Sony приложението са ползвали под 0,4% от членовете с Premium. В същата публикация Sony обявява новите игри в Extra и Premium начело с Death Stranding 2.", "zusammenfassung": "В самия край на публикацията си за новите игри в PS Plus за ноември Sony обяви края на приложението за PC. От 10 декември приложението PlayStation Plus за PC вече няма да е достъпно, а с него и облачният стрийминг на игри от PS Plus Premium на компютри с Windows. Като причина Sony посочва слабото използване: под 0,4% от имащите право членове с Premium са ползвали приложението. Абонаментите и предимствата на PS5 и PS4 не са засегнати, а Sony ще уведоми директно засегнатите потребители. Така изчезва един от начините да се играят игри за PlayStation на PC без конзола. Сред новостите в каталога Extra и Premium през ноември са Death Stranding 2: On the Beach, Atomfall и Dragon Quest III HD-2D Remake. Hell Let Loose идва на 11 ноември, а Like a Dragon: Pirate Yakuza in Hawaii, Trepang2, MotoGP 26 и Cricket 26 – на 24 ноември. Само за Premium се добавят Soul Reaver 2 и Freedom Wars Remastered.", "weitere_links": ["Eurogamer", "PlayStation в X"], "_src": "235d58ff"}, "2026-11-10-amd-zen6-ipc-epyc": {"titel": "AMD разкрива архитектурата Zen 6: 27% по-висок IPC, стартират Epyc 9006 „Venice“ с до 256 ядра", "schlagzeile": "Zen 6 е тук: AMD обещава 27% повече IPC – първо при сървърните Epyc", "kurz": "AMD разкри технологията зад Zen 6 и посочва 27% по-висок IPC спрямо Zen 5. Първите чипове със Zen 6 са сървърните процесори Epyc 9006 „Venice“ с до 256 ядра и до 5,3 GHz. Стойността на IPC идва от необичайно сравнение на AMD. За настолни процесори Ryzen със Zen 6 AMD все още не е казала нищо.", "zusammenfassung": "С края на ембаргото AMD публикува тази вечер много подробности за архитектурата Zen 6. Според AMD IPC, тоест производителността на такт, нараства средно с 27% спрямо Zen 5, с около 20% при обикновени приложения и около 31% при задачи с изкуствен интелект. ComputerBase и heise обаче посочват, че AMD е сравнила 16 ядра Zen 6c в един чиплет с 16 ядра Zen 5, разпределени в два чиплета, което не е класическо сравнение на IPC. Технически ядрото става по-широко: op кешът нараства до 6750 записа и подава 18 вместо 12 микрооперации на такт, а регистровият файл и буферът за пренареждане растат до 352 и 640 записа. AVX-512 остава, както и SMT. Обикновените ядра Zen 6 са по дванадесет в чиплет с 48 MB L3 кеш, а компактните Zen 6c – по 32 в чиплет със 128 MB L3, произведени по 2-нанометровия процес на TSMC. Първите продукти са сървърните процесори Epyc 9006 „Venice“ с до 256 ядра, 16 канала за DDR5 памет, PCIe 6.0 и до 600 вата. Високочестотните модели достигат до 5,3 GHz. AMD казва, че вече доставя, а първите системи трябва да излязат още тази година. При първите дистанционни измервания на heise едно ядро Zen 5 е имало нужда от около 22% повече време в Blender от едно ядро Zen 6, което обаче работи и на по-висока честота. През 2027 г. следват по-малка платформа, както и Venice-X с 3D V-Cache и Verano с памет LPDDR5X. След това в пътната карта са Zen 7 „Florence“ за 2028 г. и Zen 8 „Ravenna“. На събитието AMD не каза нищо за процесори Ryzen за настолни компютри и лаптопи със Zen 6, нито за срока им.", "weitere_links": ["heise online", "AMD в X"], "_src": "d9fcfe1b"}, "2026-11-10-amd-mext-flash-statt-ram": {"titel": "AMD MEXT: софтуер прехвърля рядко използваната памет на флаш, за да спести скъпа DRAM", "schlagzeile": "Криза с RAM: AMD иска да спести до 75% DRAM чрез флаш памет", "kurz": "AMD представи MEXT – софтуер, който прехвърля рядко използвани страници от паметта от DRAM на флаш SSD. Така сървърите трябва да работят почти толкова бързо с много по-малко скъпа памет. Засега предложението е само за сървъри Epyc. Всички данни за производителността са от AMD.", "zusammenfassung": "С MEXT AMD отговаря на продължаващия недостиг на памет. Според AMD DRAM представлява от 75 до 90% от цената на сървъра в зависимост от конфигурацията, докато голяма част от паметта остава неизползвана или е с излишен капацитет. MEXT разпознава „студени“ страници от паметта и ги премества на флаш памет, тоест на NVMe SSD. Модели с изкуствен интелект трябва да предвиждат кои данни скоро ще са нужни отново и да ги връщат навреме в DRAM. Според Wccftech софтуерът се състои от драйвер за Linux, AI машина, която работи на едно ядро Epyc, и инструмент за наблюдение. Според AMD така нуждата от DRAM може да се намали с 20 до 75% при сходна производителност. В пример от проектирането на чипове сървър с наполовина по-малко DRAM все още постига 95% от производителността. Тези стойности са данни на производителя, независими тестове все още липсват. Според Phoronix драйверът за Linux не е с отворен код. Засега MEXT е предназначен само за сървъри Epyc с NVMe устройства, а по-късно ще има лиценз. AMD намекна, че подобно решение може да стане интересно и за обикновени компютри, но конкретни планове няма.", "weitere_links": ["ComputerBase", "Phoronix"], "_src": "f9b8ff0f"}, "2026-11-10-gta6-vorbestell-rekord-xbox-cloud": {"titel": "Според Sony и Microsoft GTA 6 е най-поръчваната предварително игра в техните магазини, Xbox One я получава през облака, Xbox сключва 10-годишно партньорство с Take-Two", "schlagzeile": "GTA 6 чупи рекорди по предварителни поръчки – и идва дори на Xbox One", "kurz": "Sony и Microsoft съобщават, че GTA 6 е най-поръчваната предварително игра в историята на PlayStation Store и Microsoft Store. Чрез Xbox Cloud Gaming при старта тя ще върви и на стария Xbox One. Шефката на Xbox Аша Шарма говори за ново 10-годишно партньорство с Take-Two. Никой не дава конкретни данни за продажбите.", "zusammenfassung": "В PlayStation Blog Sony пише, че GTA 6 е най-поръчваната предварително игра в историята на PlayStation Store. Microsoft съобщава същото за Microsoft Store в Xbox Wire. Нито една от двете компании не дава числа; Take-Two наскоро каза само, че предварителните поръчки далеч надхвърлят очакванията. Заради очаквания наплив Sony и Microsoft съветват играта да се изтегли предварително възможно най-рано. На PlayStation GTA 6 излиза на 19 ноември в полунощ местно време, като се започва от Нова Зеландия. Xbox Cloud Gaming предлага играта от 19 ноември в 1:00 ч. по източноамериканско време, тоест в 7:00 ч. в Австрия, на Xbox One и Xbox Series X|S, с графичните настройки на Series S. Стрийминг на PC или смартфон не е предвиден. В X шефката на Xbox Аша Шарма нарече това „първата стъпка“ от ново 10-годишно стратегическо партньорство с Take-Two, без да дава подробности. Според Xbox Wire през следващите месеци в Xbox Cloud Gaming ще се появят още игри на Rockstar като GTA V и Red Dead Redemption 2. От 11 ноември играчите в поддържаните държави могат да купуват и време за игра в облака без абонамент за Game Pass.", "weitere_links": ["PlayStation.Blog", "Аша Шарма в X", "IGN"], "_src": "1f6dc907"}, "2026-11-10-eu-dfa-lootboxen-entwurf": {"titel": "Изтекъл проект на европейския Digital Fairness Act: лутбоксовете по подразбиране изключени за непълнолетни, pay-to-win забранен за деца", "schlagzeile": "Изтичане: иска ли ЕС да изключи по подразбиране лутбоксовете за деца?", "kurz": "Предполагаем проект на европейския закон Digital Fairness Act излезе предсрочно. Той предвижда лутбоксовете да са изключени по подразбиране за непълнолетни, а всички играчи да могат да ги изключват. Официалното представяне е планирано за 11 ноември, а до закон има още много.", "zusammenfassung": "Френското специализирано издание Contexte публикува предполагаем проект на Digital Fairness Act, а Eurogamer съобщава за него. Според Eurogamer Европейската комисия смята да представи официално предложението на 11 ноември. Проектът е насочен срещу нелоялни практики в дигиталния свят, включително монетизацията в игрите. Всички играчи трябва да могат да изключват лутбоксовете, тоест награди със случайно съдържание; за непълнолетните те трябва да са изключени по подразбиране. Механики pay-to-progress и pay-to-win не трябва да се предлагат на деца, ако продуктът е насочен към тях или доставчикът знае, че го ползват непълнолетни. При виртуалните валути реалната цена на покупките трябва да е прозрачна, както и шансовете за печалба при лутбоксовете. Текстът предвижда и задължителна възрастова класификация за игрите. Освен игрите засяга рекламата от инфлуенсъри, скритите цени и трудно прекратимите абонаменти. Важно: става дума за изтекъл проект, който може още да се промени до представянето. След това следват преговори; според Eurogamer законът може да бъде приет в края на 2027 г. и да се прилага широко до 2030 г.", "ursprungsquelle": "Contexte (via Video Games Industry Memo)", "_src": "792e7165"}, "2026-11-10-asrock-vbios-tool-1-0-6": {"titel": "ASRock пуска инструмента за флашване на VBIOS 1.0.6 за RX 7900 XT/XTX, след като версия 1.0.5 направи карти неизползваеми", "schlagzeile": "След „тухлясали“ RX 7900 XTX: ASRock пуска нов BIOS инструмент – без обяснение", "kurz": "ASRock пусна инструмента за флашване ASRVBFlash 1.0.6 за Radeon RX 7900 XT и XTX. Според потребители предишната версия 1.0.5 е извадила карти от строя след обновяването. ASRock не казва какво е променено и каква е била причината.", "zusammenfassung": "В началото на ноември се натрупаха съобщения, че Radeon RX 7900 XT и XTX на ASRock не стартират след официално обновяване на VBIOS. Виновен беше инструментът ASRVBFlash 1.0.5: след рестарта системата вече не зареждаше. След това ASRock очевидно свали версията от страниците си за изтегляне. Сега тихомълком се появи версия 1.0.6, която според TechPowerUp трябва да предотвратява повредата и правилно да инсталира обновлението на фърмуера за по-голяма сигурност. Няма списък с промени, нито обяснение на причината, което критикува и PCGH. Остава неясно как ASRock постъпва с вече повредените карти. Според TechPowerUp клиент в Япония е получил отговор, че карта, повредена от официалното обновление, се покрива от гаранцията. На клиент в Европа обаче е казано, че свалянето на охладителя за повторно флашване на BIOS чипа води до загуба на гаранцията. Затова засегнатите трябва да минат през RMA, вместо да експериментират сами. Който още не е обновил, може и да изчака опита на други потребители с 1.0.6.", "weitere_links": ["PC Games Hardware", "Wccftech"], "_src": "a328de5f"}, "2026-11-10-gta6-30fps-ps5-pro": {"titel": "Rockstar потвърждава: GTA 6 цели 30 fps на всички конзоли, PS5 Pro получава PSSR и ексклузивни сенки с ray tracing", "schlagzeile": "GTA 6 върви на 30 fps – и на PS5 Pro, но със сенки с ray tracing", "kurz": "Rockstar потвърди, че GTA 6 цели 30 кадъра в секунда на всички конзоли, включително на PS5 Pro. В замяна Pro версията получава по-рязка картина чрез PSSR и ексклузивни сенки с ray tracing. Предварителното изтегляне е достъпно от днес, а премиерата е на 19 ноември.", "zusammenfassung": "Със старта на предварителното изтегляне Rockstar Games за първи път официално обясни техниката на GTA 6 на конзолите. Играта е разработена от нулата за сегашното поколение конзоли и цели 30 кадъра в секунда, като изстисква двете платформи „до абсолютните им граници“. Според Rockstar това важи за PS5, PS5 Pro, Xbox Series X и Series S. Rockstar не споменава режим с 60 fps. PS5 Pro получава по-рязка картина чрез AI мащабирането на Sony PSSR и сенки с ray tracing, които има само там. На PS5 GTA 6 използва хаптиката, адаптивните тригери и високоговорителя на DualSense, както и Tempest 3D Audio; Rockstar и Sony казват, че играта се играе най-добре на PS5. Remote Play се поддържа на PlayStation и Xbox. Чрез Xbox Cloud Gaming играта може да се стриймва на конзоли Xbox с графичните настройки на Series S, но не и на PC. Rockstar все още не е обявила версия за PC. В зависимост от конзолата изтеглянето изисква до 212 GB. Има и нов трейлър за предварителното изтегляне с почти 30 секунди нови сцени.", "weitere_links": ["PlayStation.Blog", "Eurogamer", "Rockstar Games в X"], "_src": "1689ad08"}, "2026-11-10-steam-deck-framerate-daten": {"titel": "Steam вече показва в страниците на магазина средната кадрова честота на играчите на Steam Deck", "schlagzeile": "Steam вече показва реални fps – как върви една игра на Deck?", "kurz": "Valve вече показва в Steam за много игри средната кадрова честота на Steam Deck. Данните идват от играчи, които са се съгласили да ги споделят. По-късно ще бъдат добавени и други устройства.", "zusammenfassung": "Valve добави нов показател за производителност в Steam. В раздела за съвместимост със Steam Deck на страницата на игра след клик върху „Научете повече“ вече се вижда средната кадрова честота на Steam Deck. Хистограма показва и колко често е измервана всяка стойност, така че се виждат и колебанията. Данните идват от играчи, които са се съгласили да изпращат данни за кадровата честота. Стойността се показва при игри, които Valve е проверила за съвместимост с Deck, тоест с оценки „Потвърдена“, „Може да се играе“ или „Не се поддържа“. Valve обяснява, че досегашната оценка се базира на фиксирани тестови критерии и не отговаря на представата на всеки играч за плавна игра. Игра с оценка „Не се поддържа“ може за някои все пак да е добре играема, докато потвърдена игра може да има нисък fps. Според Valve функцията в бъдеще ще обхване и други устройства. Дали сред тях ще са и обикновени настолни компютри с многото им хардуерни комбинации, не е ясно.", "weitere_links": ["PC Gamer", "GamingOnLinux"], "_src": "6dbc5420"}, "2026-11-10-msi-rtx50-preise-china": {"titel": "Доклад от Китай: MSI щяла силно да вдигне през ноември дистрибуторските цени на картите RTX 50, на RTX 5080 с до 8000 юана", "schlagzeile": "Изтичане: MSI щяла да поскъпне RTX 5080 в Китай с до 8000 юана", "kurz": "Според китайския браншов канал ChannelGate MSI вдига през ноември дистрибуторските цени на всички карти RTX 50. При RTX 5080 увеличението щяло да е от 1300 до 8000 юана, или около 190 до 1200 долара. Става дума за цени за дистрибутори в Китай, не за официални цени за крайни клиенти. MSI не е потвърдила това.", "zusammenfassung": "Китайският браншов канал ChannelGate (Board Channels) съобщава за нови ценови листи на MSI за ноември. Според него дистрибуторските цени на всички модели RTX 50 в Китай се повишават спрямо октомври. За серията RTX 5080 се посочват от 1300 до 8000 юана повече, за RTX 5070 Ti от 800 до 4000 юана, а за RTX 5070 от 500 до 1000 юана. RTX 5060 Ti щяла да поскъпне с 200 до 400 юана в зависимост от паметта, RTX 5060 с 200 до 500 юана, а дори RTX 3050 със 100 юана. Wccftech преизчислява максималната стойност за RTX 5080 на около 1200 долара. Важно: максимумът важи само за отделни модели и става дума за цени за търговци в Китай, а не за нова световна препоръчителна цена. Дали и колко силно това ще засегне Европа, не е ясно. Съобщението се вписва в по-ранни доклади на ChannelGate за поскъпвания при други производители на карти. Основната причина щели да са силно повишените цени на паметта. Самата MSI не е коментирала, затова остава непотвърден доклад.", "ursprungsquelle": "ChannelGate / Board Channels (WeChat), via harukaze5719", "weitere_links": ["IT之家 (ChannelGate)", "TechRadar"], "_src": "59a47e79"}, "2026-11-10-arc-raiders-17-mio": {"titel": "Nexon: Arc Raiders е продадена в над 17 милиона копия за една година, приходите се очаква да спаднат през четвъртото тримесечие", "schlagzeile": "Arc Raiders надхвърли 17 милиона – но продажбите се забавят", "kurz": "Според издателя Nexon екстракшън шутърът Arc Raiders е продаден в над 17 милиона копия за първия си рожден ден. През третото тримесечие обаче са добавени само един милион. Nexon очаква през четвъртото тримесечие по-малко приходи, отколкото при старта преди година.", "zusammenfassung": "В тримесечния си отчет Nexon даде нови данни за Arc Raiders на Embark Studios. Екстракшън шутърът излезе в края на октомври 2025 г. и оттогава е продаден в над 17 милиона копия. Според Nexon обаче през третото тримесечие на 2026 г. са добавени само около един милион, така че продажбите значително са се забавили. За четвъртото тримесечие Nexon очаква по-малко приходи от играта, отколкото в същото тримесечие на миналата година, когато беше успешният старт. Спрямо предходното тримесечие приходите се очаква да останат приблизително същите. Според Nexon приходите са в рамките на прогнозата, а обновлението Frozen Trail е върнало бивши играчи и е спечелило нови. Arc Raiders остава едно от най-важните заглавия на Nexon и беше основната причина за ръста на приходите през първите девет месеца на годината. Все още не е ясно дали ще има постоянен самостоятелен PvE режим; в Китай такъв вече има.", "_src": "95842a04"}, "2026-11-10-nvidia-fbi-sammelklagen": {"titel": "Подозрения за шпионаж около шефа на NVIDIA Хуанг: според Тръмп ФБР проверява случая, адвокатски кантори търсят инвеститори за искове", "schlagzeile": "Шпионската афера около NVIDIA: ФБР проверява случая, задават се искове", "kurz": "По случая с предполагаемата китайска шпионка от обкръжението на шефа на NVIDIA Дженсън Хуанг вече проверява ФБР, според президента на САЩ Тръмп. Не е ясно дали евентуално разследване засяга и Хуанг. Няколко американски адвокатски кантори търсят инвеститори за възможни колективни искове срещу NVIDIA.", "zusammenfassung": "Аферата около шефа на NVIDIA Дженсън Хуанг и предполагаемата китайска шпионка Алис Хуанг набира скорост. Според Spiegel и Reuters президентът на САЩ Доналд Тръмп е казал, че ФБР разглежда случая. Не е ясно дали проверката засяга и самия Дженсън Хуанг; въпреки еднаквата фамилия двамата не са роднини. Тръмп защити Хуанг и каза по същество, че му вярва, че не е знаел нищо за шпионска дейност. Хуанг по-рано призна връзката и се извини публично, а бордът на NVIDIA започна разследване с външни експерти. Според PC Gamer няколко американски адвокатски кантори, сред които Rosen Law Firm, търсят инвеститори за възможни искове заради подвеждащи изявления. Според Guardian в Сан Хосе вече е заведен иск, в който NVIDIA и Хуанг са обвинени, че са премълчали възможен риск за сигурността. Работодателят на Алис Хуанг, Megaspeed, е заподозрян, че е изнасял чипове на NVIDIA за Китай без разрешение; NVIDIA и Megaspeed по-рано отрекоха това. Според PC Gamer Хуанг трябва да даде показания при закрити врата пред комисии на Конгреса на 18 ноември. Нито едно от обвиненията досега не е решено от съд.", "weitere_links": ["PC Gamer"], "_src": "79f7d817"}, "2026-11-10-chrome-zero-day": {"titel": "Chrome 157 затваря девет уязвимости, сред които активно използваната CVE-2026-125350", "schlagzeile": "Уязвимост в Chrome вече се атакува – обнови сега до версия 157", "kurz": "Google пусна актуализация на Chrome с девет корекции за сигурност. Уязвимост в XML компонента на браузъра вече се използва активно. Сигурните версии са 157.0.8103.50/.51 за Windows и Mac и 157.0.8103.50 за Linux.", "zusammenfassung": "Google пусна актуализация за сигурност на Chrome, която затваря девет уязвимости, съобщава Golem. Според Google поне една от тях вече се използва активно: CVE-2026-125350. Става дума за грешка от типа use-after-free в компонента, който обработва XML данни; тежестта е оценена като висока, но Google все още не дава CVSS оценка. Google не казва как и срещу кого се използва уязвимостта. Не е ясно и дали потребителят трябва да кликне нещо, за да успее атаката. От останалите осем уязвимости шест са с висока, а две със средна тежест; засегнати са, наред с други, JavaScript енджинът V8, WebGL и интерфейси към GPU и файловата система. Както обикновено, Google задържа техническите подробности, докато повечето потребители не обновят. Сигурните версии са 157.0.8103.50/.51 за Windows и macOS и 157.0.8103.50 за Linux. Други браузъри на базата на Chromium като Edge, Vivaldi или Brave вероятно също са засегнати и ще получат актуализации в следващите дни. Съвет: Помощ › Всичко за Google Chrome стартира проверката за актуализация; след това рестартирай браузъра.", "_src": "3c9a011f"}, "2026-11-10-switch-eshop-geschenke": {"titel": "Системната актуализация 23.5.0 за Switch подготвя функция за подаръци в Nintendo eShop за семейни групи", "schlagzeile": "Switch и Switch 2: скоро ще подаряваш игри – но само в семейството", "kurz": "С системна актуализация 23.5.0 Nintendo подготвя възможността за подаряване на игри от eShop. Функцията ще се активира с актуализация на eShop в средата на ноември. Подаръци могат да се пращат само на членове на собствената семейна група.", "zusammenfassung": "Nintendo пусна системна актуализация 23.5.0 за Switch 2 и първия Switch. Тя подготвя нова функция: дигитални игри, DLC и пакети за ъпгрейд от eShop скоро ще могат да се подаряват. Ограничението: получателите трябва да са членове на собствената семейна група в Nintendo Account, която има до осем членове. Според Nintendo наблюдаваните детски акаунти не могат да изпращат подаръци, някои продукти са изключени, а броят на покупките за подарък за даден период е ограничен; точни лимити Nintendo не дава. При покупка се отбелязва „Купи като подарък“ на страницата на продукта, избира се получателят и неговата конзола и се плаща както обикновено. Подаръкът пристига веднага в менюто HOME на получателя. Функцията ще бъде активирана едва с актуализация на eShop: в бележките към актуализацията се посочва 17 ноември, а Nintendo of America пише за 16 ноември, вероятно заради часовата зона. На Switch 2 версия 23.5.0 позволява и настройване на функциите за достъпност още при първоначалната настройка. Който иска да подари игри на приятели извън семейната група, ще трябва и занапред да използва карти за подарък за eShop.", "weitere_links": ["VGChartz (бележки към актуализацията)", "Nintendo of America в X (подсказка)"], "_src": "51b1c15b"}, "2026-11-10-mesa-26-3": {"titel": "Излезе Mesa 26.3: AMD Anti-Lag за RADV, графиката Nova Lake е включена по подразбиране, Vulkan Video за NVK", "schlagzeile": "Linux графичният драйвер Mesa 26.3: Anti-Lag за Radeon и още Vulkan", "kurz": "Свободната колекция графични драйвери Mesa 26.3 е тук. Потребителите на Radeon получават чрез RADV разширението на Vulkan за AMD Anti-Lag, а графиката Intel Nova Lake вече не е експериментална. Добавят се и Vulkan Video за драйвера на NVIDIA NVK и много подобрения за Vulkan.", "zusammenfassung": "Излезе Mesa 26.3 – четвъртото голямо издание за годината на свободните OpenGL и Vulkan драйвери за Linux, съобщават Phoronix и 9to5Linux. За геймърите с Radeon карта най-важната новост е VK_AMD_anti_lag във Vulkan драйвера RADV – Vulkan интерфейсът за AMD Anti-Lag, който намалява входното забавяне. RADV носи и подобрения за ранните GCN GPU и поддръжка за GFX1171. При Intel графиката на Nova Lake вече е включена по подразбиране и не е експериментална, а новият компилатор за шейдъри Jay е активиран. Intel включва и компресия на буферите, която според Phoronix трябва да подобри производителността в игри с DXVK, тоест при Windows игри чрез Proton. Свободният драйвер на NVIDIA NVK получава Vulkan Video за видео ускорение. Добавят се и много нови Vulkan разширения за Arm Mali, PowerVR и други драйвери. Mesa 26.3 е достъпна във FreeDesktop.org; повечето дистрибуции ще я доставят със следващите актуализации на пакетите. Колко помага Anti-Lag в отделните игри зависи от това дали играта или слоят за транслация го използва; измервания все още няма.", "weitere_links": ["9to5Linux"], "_src": "24e0a075"}, "2026-11-10-take-two-ki-decompiling": {"titel": "Take-Two засилва техническата и правната защита срещу обратния инженеринг на GTA 6 с помощта на ИИ", "schlagzeile": "Неофициален PC порт на GTA 6 чрез ИИ? Take-Two засилва защитата", "kurz": "Шефът на Take-Two Строс Зелник приема сериозно декомпилирането с помощта на ИИ и иска да засили техническата защита и правните действия. Причината е опасението, че GTA 6 може да се появи неофициално на PC. За официална PC версия или диск Take-Two не казва нищо; това ще дойде от Rockstar.", "zusammenfassung": "Преди старта на GTA 6 на 19 ноември расте опасението, че инструменти с ИИ могат по-бързо да декомпилират конзолни игри и да ги разпространяват като неофициални PC портове. IGN попита главния изпълнителен директор на Take-Two Строс Зелник за това в интервю и по време на въпросите на инвеститорите. Зелник казва, че индустрията дълго е била до голяма степен пощадена от пиратството заради размера на файловете, сложността и връзката със сървъри, но това става все по-трудно. Затова Take-Two се съсредоточава върху засилване на техническата защита и правните си действия. Той очаква пиратството да засегне бизнеса „в по-голяма или по-малка степен“, но го смята за управляемо и не го вижда като финансова заплаха. Според IGN част от тревогата е свързана със сигурността на PS5: homebrew сцената работи по jailbreak-ове за по-нов фърмуер, а GTA 6 се очаква да изисква актуален фърмуер. Зелник не каза кога GTA 6 официално ще излезе на PC. Според Insider Gaming (позовавайки се на Variety) той посочи, че такава информация винаги идва от лейбъла, тоест от Rockstar; същото важи и за евентуална версия на диск. При старта GTA 6 излиза само за PS5 и Xbox Series X|S. Бивш технически директор на Rockstar North наскоро предположи, че Rockstar може да ускори PC порт по тази причина, но това не е потвърдено.", "weitere_links": ["Insider Gaming"], "_src": "a25dcecd"}, "2026-11-10-sega-newsletter-leak": {"titel": "SEGA: атака срещу доставчика на бюлетини ARARA разкрива около 2,2 милиона имейл адреса", "schlagzeile": "Изтичане на данни при SEGA: 2,2 млн. имейл адреса откраднати от доставчик", "kurz": "При атака срещу японския доставчик на бюлетини ARARA са изтекли около 2,2 милиона имейл адреса на клиенти на SEGA. Според SEGA имена, пароли и платежни данни не са засегнати, нито акаунтите в SEGA. Клиентите трябва да внимават за фалшиви имейли от името на SEGA.", "zusammenfassung": "SEGA потвърди на 9 ноември изтичане на данни при своя доставчик на бюлетини ARARA. Засегнати са 2 196 044 имейл адреса; при 92 273 от тях са изтекли и данни, свързани с изпращането, като какво точно – още се проучва. Според SEGA става дума за единадесет бюлетина на SEGA и SEGA Fave, изпратени между юли и октомври 2026 г., например за аркадни игри като CHUNITHM и maimai, за Tokyo Game Show и за лотарийни акции. Според SEGA имена, дати на раждане, адреси, телефонни номера, данни за кредитни карти и пароли не са засегнати. Имейл адресите от SEGA Account също минават през друга система и не са част от изтичането. Злоупотреба с данните засега не е потвърдена. Самата ARARA съобщи за пробива в началото на ноември; според BleepingComputer и Infosecurity Magazine там общо са засегнати около 77 милиона имейл адреса на около 380 корпоративни клиенти, очевидно чрез уязвимост в уеб сървъри. SEGA спря изпращането чрез ARARA и ще информира засегнатите поотделно. Който е получавал бюлетини на SEGA, трябва да внимава особено за фишинг в имейли, свързани със SEGA.", "weitere_links": ["SEGA (съобщение, на японски)", "Infosecurity Magazine"], "_src": "ba66609c"}, "2026-11-10-take-two-gta6-vorbestellungen": {"titel": "Take-Two: предварителните поръчки за GTA 6 далеч надхвърлят очакванията, до 3,5 млрд. долара в тримесечието на старта", "schlagzeile": "GTA 6: предварителни поръчки „далеч над очакванията“ – Take-Two чака рекорд", "kurz": "Десет дни преди старта на GTA 6 Take-Two съобщава за предварителни поръчки на „безпрецедентно“ ниво. За текущото тримесечие компанията очаква net bookings от 3,35 до 3,5 млрд. долара. Конкретни числа за предварителните поръчки Take-Two все още не дава.", "zusammenfassung": "Take-Two представи на 9 ноември резултатите си за второто тримесечие на финансовата 2027 година, а GTA 6 беше в центъра на вниманието. Според главния изпълнителен директор Строс Зелник предварителните поръчки са „далеч над очакванията“ и продължават да достигат „безпрецедентни“ нива, съобщават Insider Gaming, Eurogamer и PC Gamer. За текущото трето тримесечие, в което попада стартът на 19 ноември, Take-Two очаква net bookings от 3,35 до 3,5 млрд. долара. Според PC Gamer това дори е малко под оценката на анализаторите от 3,51 млрд. долара (LSEG, чрез Reuters). За цялата финансова 2027 година компанията очаква 8 до 8,2 млрд. долара. Take-Two все още не дава конкретни числа за предварителните поръчки, защото суровите данни без сравнение биха могли да заблудят. Изминалото тримесечие беше по-слабо: net bookings от 1,6 млрд. долара бяха под очакванията и с 18 процента под миналогодишните. Една от причините е NBA 2K27, която стартира добре, но остана под прогнозата; Зелник вижда очакването за GTA 6 като една от причините. Take-Two даде и нови данни за продажби: GTA 5 е на около 235 милиона копия, а Red Dead Redemption 2 наближава 90 милиона. Поредицата GTA като цяло има почти 480 милиона продадени бройки.", "weitere_links": ["PC Gamer", "Eurogamer", "Insider Gaming (GTA 5)", "Insider Gaming (RDR2)"], "_src": "38d7088e"}, "2026-11-10-skydance-games-entlassungen": {"titel": "Skydance Games съкращава служители и орязва проекти – месец след сливането на Paramount и Warner Bros.", "schlagzeile": "След мегасливането: Skydance Games съкращава разработчици и орязва проекти", "kurz": "Skydance Games съкрати работни места и „намали някои проекти“. Това става месец след сливането на Paramount и Warner Bros. Discovery. Компанията не казва колко души са засегнати.", "zusammenfassung": "Skydance Games потвърди съкращения, съобщават IGN и PC Gamer, позовавайки се на изявление пред Variety. Компанията е решила да намали някои проекти и затова има засегнати позиции; това не е оценка на таланта или отдадеността на засегнатите. Първи за напускането си съобщиха служители на Paramount Games Studio, основано едва през юни. Към Paramount Games спадат, наред с други, Skydance Interactive и Skydance New Media. Там наскоро бяха обявени игри като Teenage Mutant Ninja Turtles: The Last Ronin, както и адаптации на Yellowstone, Tulsa King и Lioness. Не е известно кои проекти се орязват. Skydance не казва колко работни места отпадат; според Insider Gaming засегнати са поне 30 разработчици, вероятно повече. Съкращенията идват около месец след одобрението на сливането на Paramount и Warner Bros. Discovery под шапката на Skydance. Какво означава това за подразделението Warner Bros. Games, остава открито.", "weitere_links": ["PC Gamer"], "_src": "a7836025"}, "2026-11-10-rdna5-gfx13-linux": {"titel": "AMD публикува пачове за Linux драйвера за GFX13 – графичното IP от следващо поколение (вероятно RDNA 5)", "schlagzeile": "RDNA 5 наближава: AMD изпраща първите Linux драйвери за GFX13", "kurz": "AMD публикува над 12 600 реда код за драйвера на Linux ядрото за GFX13, следващото поколение графика Radeon. Най-вероятно става дума за RDNA 5. Засега пачовете не разкриват нови подробности за производителност или функции.", "zusammenfassung": "Разработчикът на AMD Алекс Дойхер публикува серия пачове, които подготвят драйвера на Linux ядрото AMDGPU за GFX13, съобщават Phoronix и VideoCardz. GFX13 е следващото графично IP на AMD и много вероятно означава RDNA 5; AMD не е потвърдила официално името. Осемте пача съдържат над 12 600 реда код, без обичайните големи заглавни файлове. Те включват и поддръжка за конкретните варианти GFX 13.0.1 и GFX 13.0.4. Според Phoronix засега пачовете разкриват малко за възможностите или новите функции на RDNA 5. За компилатора LLVM пачове за GFX13 имаше още от началото на годината, сега следва драйверът за ядрото. Phoronix очаква поддръжката в Linux ядро 7.5. Други блокове, които вероятно ще са част от RDNA 5 GPU, като Display Core Next 6, вече са в ядрото. AMD често публикува ранни Linux драйвери месеци преди пускането на пазара; AMD не дава дата за видеокарти с RDNA 5.", "weitere_links": ["VideoCardz"], "_src": "c780eb89"}, "2026-11-10-nvidia-megaspeed-nyt": {"titel": "Доклад на NYT: NVIDIA се е намесила в разследване в САЩ срещу заподозрения контрабандист на ИИ чипове Megaspeed", "schlagzeile": "Доклад: NVIDIA е забавила разследване за контрабанда на чипове", "kurz": "Според New York Times главният юрисконсулт на NVIDIA се е обърнал директно през 2025 г. към Министерството на търговията на САЩ, което разследваше фирмата Megaspeed за предполагаема контрабанда на чипове към Китай. Разследването засяда и е предадено на Министерството на правосъдието. Става дума за медиен доклад; нямаме позиция на NVIDIA.", "zusammenfassung": "След новината за разследването на борда на NVIDIA около главния изпълнителен директор Дженсън Хуанг идва нов натиск: според Wccftech New York Times пише за ролята на NVIDIA в разследванията срещу фирмата Megaspeed. Компанията за центрове за данни със седалище в Сингапур беше подозирана, че служи като параван, за да вкарва контрабандно ИИ ускорители на NVIDIA в Китай, заобикаляйки американския експортен контрол. Megaspeed се ръководи от Алис Хуанг, която според американските разузнавателни служби е работила за Пекин; това е същата жена, с която Дженсън Хуанг призна за връзка. Според доклада главният юрисконсулт на NVIDIA Тим Тетър се е обърнал директно през 2025 г. към Bureau of Industry and Security към Министерството на търговията. Той се е позовал на това, че номинираният от Тръмп Джеф Кеслър му е разрешил този пряк контакт. Няколко служители са възприели това като сериозно нарушение на обичайните процедури. След това разследването засяда и е предадено на Министерството на правосъдието. Разговорите на фирмени адвокати с ведомства сами по себе си са нормални; спорно според доклада е естеството на контакта. Според Wccftech на 18 ноември Хуанг предстои закрито изслушване в Конгреса на САЩ. Обвиненията идват от медийни публикации; нямахме позиция на NVIDIA по тях.", "_src": "12d2733c"}, "2026-11-09-dark-heresy-release": {"titel": "Warhammer 40,000: Dark Heresy на Owlcat излиза на 28 януари 2027 г. за PC, PS5 и Xbox Series", "schlagzeile": "Warhammer 40k: Dark Heresy има дата – излиза на 28 януари 2027 г.", "kurz": "Owlcat Games обяви датата на излизане на Warhammer 40,000: Dark Heresy. Тактическата ролева игра излиза на 28.01.2027 за PC, PS5 и Xbox Series X/S, а версия за Switch 2 ще последва по-късно. Играете като инквизитор, който преследва еретици.", "zusammenfassung": "Owlcat Games обяви с прессъобщение и трейлър датата на излизане на тактическата си ролева игра Warhammer 40,000: Dark Heresy, съобщават Eurogamer и GameStar. Играта излиза на 28 януари 2027 г. за PC, PlayStation 5 и Xbox Series X/S. Дата за Switch 2 ще бъде обявена „на по-късен етап“. Dark Heresy надгражда Warhammer 40,000: Rogue Trader, който Owlcat издаде преди няколко години. Този път играете като инквизитор, който издирва еретици и тъмни влияния в 41-вото хилядолетие. Според Eurogamer Owlcat е преработила много от основните системи. От известно време тече бета с целия първи акт, достъпна за купувачите на Founders Edition. Бетата ще бъде изключена на 7 януари, докато Owlcat подготвя играта за старта. Eurogamer припомня, че Rogue Trader беше хвален за света и битките, но при излизането си имаше проблеми с бъгове и слаба производителност. Затова тепърва ще се види как ще работи Dark Heresy при старта. Паралелно Owlcat работи по ролева игра по научнофантастичната поредица The Expanse.", "weitere_links": ["GameStar"], "_src": "e9845177"}, "2026-11-09-ps-portal-speicher-japan": {"titel": "Sony пуска в Япония нов модел PlayStation Portal с вградена памет за бъдещи функции", "schlagzeile": "Нов PS Portal със собствена памет – Sony намеква за още функции", "kurz": "Sony пуска в Япония на 10.12.2026 нов модел PlayStation Portal с вградена памет. Според Sony Japan паметта е предвидена за бъдещи функции, а подробностите ще бъдат обявени по-късно. Цената остава 39 980 йени, предварителните поръчки започват на 13.11.2026, а дали моделът ще дойде и в Европа, не е ясно.", "zusammenfassung": "Sony пуска в Япония обновен модел на PlayStation Portal, съобщава IGN, позовавайки се на официалния блог на Sony Japan. Най-важната разлика спрямо досегашното устройство е вградената памет. Sony пише, че я е добавила с оглед на бъдещи функции и ще съобщи подробности, когато бъдат уточнени. Какви ще са тези функции, Sony все още не казва. Едновременно с това Sony променя официалното японско име от „PlayStation Portal Remote Player“ на „PlayStation Portal Player“. В блога Sony подчертава също, че дори играчи без PS5 могат да играят PS5 игри на Portal; това се отнася до облачния стрийминг за абонатите на PS Plus Premium, който Sony въведе миналата година. IGN тълкува паметта и смяната на името като възможна стъпка от обикновен аксесоар за Remote Play към по-самостоятелна преносима конзола; това е оценка, а не обявление на Sony. Новият модел излиза в Япония на 10 декември, предварителните поръчки започват на 13 ноември, а цената остава 39 980 йени. Той е само на японски и изисква японски PSN акаунт. Дали и кога ще излезе в други региони, не е известно.", "_src": "e6a33542"}, "2026-11-09-sshole-angriffe": {"titel": "Уязвимостта в OpenSSH „SSHole“ (CVE-2026-123158) се използва активно, нападатели получават root на системи с Alpine", "schlagzeile": "Уязвимостта „SSHole“ в OpenSSH вече се атакува – обновете Alpine сървърите", "kurz": "Уязвимостта в OpenSSH на системи с musl като Alpine Linux, за която писахме на 05.11.2026, вече се използва активно. Няколко фирми за сигурност съобщават за атаки, а в един honeypot нападателите са получили root достъп. Уязвимостта вече се нарича „SSHole“ (CVE-2026-123158); решението е OpenSSH 10.6p2 и рестарт на sshd след това.", "zusammenfassung": "Уязвимостта в OpenSSH, за която писахме на 5 ноември, вече се атакува активно, съобщават BleepingComputer, SecurityWeek и The Hacker News. Тя вече носи прякора „SSHole“ и идентификатора CVE-2026-123158 (CVSS 8.1). Засегнат е OpenSSH преди версия 10.6p2 на Linux системи с C библиотеката musl без PAM, например стандартната конфигурация на Alpine Linux; откривателят посочва за проверка и OpenWrt, Buildroot, Yocto и много Docker образи. С много дълга парола от 257 до 1024 байта нападателите могат да влязат в акаунти, които изобщо не би трябвало да приемат парола. Според BleepingComputer опитите за атаки са започнали на 5 ноември, когато няколко часа след поправката се появи proof of concept. Фирмата Previdian потвърждава успешен root достъп на собствен honeypot с истински Alpine Linux и до 8 ноември е отчела 20 опита от 13 IP адреса от девет държави. GreyNoise регистрира първото успешно използване в реална среда на 7 ноември и наблюдава 16 успешни вериги на атака: нападателите проучваха системата и контейнерите, запитваха облачни метаданни, опитваха да прочетат хешове на пароли и root SSH ключове и да добавят свои ключове за постоянен достъп. Решението е OpenSSH 10.6p2 или поправеният пакет на дистрибуцията; Alpine публикува пакети за всички клонове от 3.16 нататък. Важно: след обновяването sshd трябва да се рестартира, иначе продължава да работи старата версия; според watchTowr засега уязвимостта използват основно ботнети и криптомайнъри. Като незабавна мярка помага PasswordAuthentication no. Администраторите трябва също да проверят логовете за неочаквани записи „Accepted password for“ при акаунти без парола и за непознати SSH ключове.", "weitere_links": ["SecurityWeek", "The Hacker News", "Help Net Security"], "_src": "36ee778e"}, "2026-11-09-gta6-festival-miami": {"titel": "Rockstar обявява „Grand Theft Auto VI: The Festival“ на 21 ноември в Маями с Travis Scott, Cardi B и Justice", "schlagzeile": "GTA 6 получава собствен музикален фестивал – с Travis Scott и Cardi B", "kurz": "Rockstar отбелязва старта на GTA 6 с музикален фестивал в Маями. „Grand Theft Auto VI: The Festival“ ще се проведе на 21.11.2026 в Mana Wynwood, сред изпълнителите са Travis Scott, Cardi B, Kodak Black и Justice. Билетите се разпределят чрез лотария, а самата игра излиза на 19.11.2026.", "zusammenfassung": "Rockstar Games обяви в X музикален фестивал за старта на GTA 6, съобщават VGC и Eurogamer. „Grand Theft Auto VI: The Festival“ ще се проведе на 21 ноември в Mana Wynwood в Маями, два дни след излизането на играта на 19 ноември. Според Rockstar ще излязат артисти от играта и от официалния саундтрак. Потвърдени според VGC са сред други Travis Scott, Don Toliver, Kodak Black, Sofaygo, Cardi B, Ca7riel и Paco Amoroso, Justice, Metro Boomin, Rauw & Friends, Suero и Tainy, както и няколко DJ сета в дуо. Билетите се продават чрез платформата DICE и се разпределят чрез лотария. Според Rockstar трябва да се регистрирате за лотарията за предварителна продажба до вторник, 10 ноември, 16:00 ч. източно време в САЩ (22:00 ч. в Австрия); шансът за билети идва в сряда в 12:00 ч. източно време (18:00 ч. при нас). За играта излизат два саундтрака на CD, винил и в стрийминг услугите: „GTA 6: The Album“ с 34 нови песни на 19 ноември, сред които с Travis Scott и Keith Richards, и на 11 декември „Grand Theft Auto VI: Original Score“ с 30 композиции на френското електронно дуо Justice.", "weitere_links": ["Rockstar Games в X", "Rockstar Games в X (лотария за билети)", "Eurogamer"], "_src": "31cad77d"}, "2026-11-09-amd-ssd-fix-26-11-1": {"titel": "AMD потвърждава постоянен запис върху SSD заради драйвера Radeon, поправката се очаква с Adrenalin 26.11.1", "schlagzeile": "Драйверът Radeon изяжда живота на SSD: поправка се очаква с 26.11.1", "kurz": "Допълнение към новината ни от 08.11.2026: според TechPowerUp и PC Gamer грешката, при която услуга на драйвера Radeon постоянно пише върху SSD, ще бъде поправена с Adrenalin 26.11.1. Според TechPowerUp засегнати са версиите 26.10.1 и 26.10.2, а дата за новия драйвер все още няма. Потребители съобщават за спад на здравето на SSD с около 1 процент на месец.", "zusammenfassung": "За грешката в драйвера Radeon с постоянен запис върху SSD, за която писахме на 8 ноември, се очертава решение. Според TechPowerUp AMD е потвърдила, че са засегнати драйверите Adrenalin 26.10.1 и 26.10.2 и че поправката ще дойде с версия 26.11.1. PC Gamer цитира представителя на AMD AMD_Vik в Reddit, според когото проблемът „би трябвало да е поправен“ в 26.11.1; точна дата няма, но според PC Gamer драйверът се очаква в рамките на месеца. Виновникът е услугата atieclxx.exe от AMD External Events Utility, която отговаря например за разпознаването на монитори и клавишните комбинации на софтуера Radeon и явно записва данни в безкраен цикъл. Съобщава се за 0,3 до 1,5 MB/s, а един потребител в Reddit посочва постоянни 5 MB/s. Потребител в X е измерил 19,5 GB запис за 12 часа и смята, че грешката съществува от Adrenalin 26.7.1 от юни. В Reddit потребители съобщават, че здравето на SSD-то им пада с около 1 процент на месец заради това; това са потребителски наблюдения, а не измервания на AMD. Не всяка система е засегната, а PC Gamer не успя да възпроизведе грешката. Като временно решение TechPowerUp посочва изключване на AMD External Events Utility, което може да причини проблеми с картината, или изключване на Resizable BAR, което може да струва производителност. TechPowerUp по-скоро съветва да се изчака официалният драйвер.", "weitere_links": ["PC Gamer", "ComputerBase"], "_src": "fc743806"}, "2026-11-09-amdlss5-2-radeon": {"titel": "Модът AMDLSS5 2.0 носи невронно рендериране в стил DLSS 5 на картите Radeon със собствен енджин", "schlagzeile": "Мод носи невронното рендериране на DLSS 5 на Radeon – вече много по-бързо", "kurz": "Неофициалният мод AMDLSS5 излезе във версия 2.0 и има за цел да донесе невронно рендериране в стил DLSS 5 на картите Radeon. Според разработчика вече работи на собствен енджин и е значително по-бърз от други модове. Измерванията са само от разработчика. Модът няма нищо общо с AMD или NVIDIA.", "zusammenfassung": "Wccftech съобщава за версия 2.0 на общностния мод AMDLSS5 от разработчика Wehaveall. Той цели да донесе на картите AMD Radeon невронно рендериране в стил DLSS 5, тоест подобрения с изкуствен интелект на осветлението и материалите, като се включва в съществуващите DirectX 12 вериги за мащабиране. Новото е собствен енджин, който заменя досегашната зависимост от друг мод и би трябвало да има по-малко натоварване. В публикация в Reddit разработчикът показва резултати от PresentMon в Resident Evil Requiem в 4K с FSR на RX 9070 XT: средно 101,2 fps и 78,5 fps при 1% low, срещу 91,3 и 66,0 с версия 1.6.1 и 61,6 и 55,5 с други модове. Оттам идват рекламираните 64 процента повече fps, но само в сравнение с други модове, а не с играта без мод или с истинския DLSS 5 на NVIDIA. Това са данни на разработчика от една сцена с една карта; независими тестове още няма. Нова поддръжка получават PRAGMATA, Nioh 3 и GTA V Enhanced, последната само в офлайн режим на историята с изключен BattlEye. Основни цели са RX 9070 и RX 9070 XT; серията RX 9060 би трябвало теоретично да работи, а картите RX 7000 имат експериментална алфа поддръжка, но според Wccftech разработчикът не е проверил нито едното на реален хардуер. Добавени са и 39 цветови профила, локално тонално картографиране, подобрени ambient occlusion и непряко осветление, както и преработено 2x генериране на кадри в избрани игри. Модът е безплатен в GitHub, но изходният код на новия енджин още не е публикуван.", "_src": "23e75a0d"}, "2026-11-09-amazon-us-amd-vor-nvidia": {"titel": "Amazon САЩ през октомври: AMD продава повече видеокарти от NVIDIA, RX 9070 XT е най-продавана", "schlagzeile": "Amazon САЩ: AMD продаде повече видеокарти от NVIDIA през октомври", "kurz": "Според данните за продажбите в Amazon САЩ за октомври 2026 г. AMD е продала малко повече видеокарти от NVIDIA: около 9200 срещу 8900 броя. Най-продаваната карта е Radeon RX 9070 XT с около 3300 броя. NVIDIA все пак има повече приходи заради по-високите средни цени. Данните са от събирач на данни, а не от производителите.", "zusammenfassung": "Wccftech съобщава за данни за продажбите в Amazon САЩ за октомври 2026 г., събрани от TechEpiphany. Според тях AMD е продала там през октомври с малко най-много видеокарти: около 9200 броя срещу около 8900 за NVIDIA. Според Wccftech това е забележително, защото Amazon САЩ обикновено е доминиран от NVIDIA, докато AMD по-често води например в Германия. По приходи NVIDIA остава напред, тъй като средната ѝ продажна цена е 1313 долара срещу 915 долара за AMD. Най-продавана е Radeon RX 9070 XT с около 3300 броя; RTX 5070 Ti достига едва около една трета от това. Второ място заема RTX 5060 Ti (8 и 16 GB заедно) с около 2250 броя, следвана от RX 9060 XT с около 2150. RTX 5070 остава под 2000 броя, а RTX 5090 стига само до около 150 заради слабата наличност. Дори старата Arc A380 се е продала повече – около 500 броя. Според данните Intel достига около 6,22 процента дял благодарение на Arc B570, B580 и картите Arc Pro. Wccftech смята, че силно повишените цени са основната причина купувачите да избират по-евтини карти. Важно: данните обхващат само един магазин в САЩ и не идват от AMD, NVIDIA или Amazon; затова са само моментна картина, а не пазарни дялове за целия пазар.", "_src": "1307b37c"}, "2026-11-09-bit-reactor-entlassungen": {"titel": "Star Wars Zero Company: студиото Bit Reactor съкращава служители въпреки добрите отзиви и милион продажби", "schlagzeile": "Star Wars Zero Company: студиото съкращава хора – въпреки хита и 84 точки", "kurz": "Bit Reactor, студиото зад Star Wars Zero Company, е съкратило служители. VGC съобщава това въз основа на публикации в LinkedIn на засегнати разработчици. А играта получи добри отзиви и според EA е продадена в един милион копия. Колко работни места са засегнати, не е ясно.", "zusammenfassung": "Bit Reactor, разработчикът на Star Wars Zero Company, е съкратил служители, съобщава VGC, позовавайки се на сайта Bespin Bulletin. Няколко разработчици, сред които старши environment artist, UI инженер, продуцент и старши QA анализатор, са написали през последните дни в LinkedIn, че са засегнати. Колко позиции общо отпадат, не е известно. Според съобщения преди излизането през август студиото е пуснало в неплатен отпуск около 80 процента от служителите си, защото парите са свършвали. През октомври шефът на студиото Greg Foertsch каза, че част от тях се връщат; според съобщения така студиото отново е достигнало над половината от предишния си размер. Не е ясно дали сега са засегнати и завърнали се служители или само хора, които не са били върнати след отпуска. Поне един засегнат пише, че е съкратен след три месеца отпуск. Горчиво е, защото Star Wars Zero Company излезе в края на август с много добри отзиви и има 84 точки в Metacritic. На 9 октомври официалният акаунт EA Star Wars съобщи за един милион продадени копия. VGC не цитира официално становище на Bit Reactor за съкращенията.", "weitere_links": ["GameStar"], "_src": "52d9b77e"}, "2026-11-09-notepadpp-7zip-luecken": {"titel": "Notepad++ 8.9.9 затваря шест уязвимости, 7-Zip 26.06 поправя неуточнени уязвимости", "schlagzeile": "Notepad++ и 7-Zip: обновления запушват дупки в сигурността – обновете сами", "kurz": "Notepad++ 8.9.9 затваря шест уязвимости, като най-сериозната е с висок риск. Според разработчика 7-Zip 26.06 също поправя уязвимости, но без подробности. 7-Zip няма функция за обновяване, затова трябва да го обновите сами. В Windows това става лесно с winget.", "zusammenfassung": "Два широко използвани инструмента за Windows получиха обновления за сигурност, съобщава heise online. Notepad++ 8.9.9 на разработчика Don Ho затваря шест уязвимости. Най-сериозна е препълване на буфер в heap паметта в SAML декодера на плъгина mimeTools: подправени SAML съобщения биха могли при декодиране да презапишат паметта и евентуално да изпълнят зловреден код. Бюлетинът оценява риска като висок, но не посочва CVSS оценка. Останалите пет уязвимости се считат за средни, като според heise някои от тях вероятно позволяват повишаване на правата в системата, например чрез UAC записването на защитени файлове или съобщения между прозорци. CVE номера още няма. Освен това версията ускорява търсенето във файлове и обновява компонента на редактора Scintilla до 5.6.9. Notepad++ има собствена проверка за обновления; алтернативно помага winget update Notepad++.Notepad++. Архиваторът 7-Zip излезе през уикенда във версия 26.06. Разработчикът Igor Pavlov пише само, че са поправени някои грешки и уязвимости, без да казва кои и колко сериозни. Той е подобрил и поддръжката на файлове, разделени с Linux инструмента split. Тъй като 7-Zip не проверява за обновления, потребителите трябва сами да изтеглят новата версия или в Windows да използват winget upgrade 7zip.7zip. heise препоръчва с winget upgrade --all да се инсталират наведнъж всички налични обновления.", "weitere_links": ["heise online (7-Zip)"], "_src": "2abed807"}, "2026-11-09-sonicwall-sslvpn-angriffe": {"titel": "SonicWall: атакува се уязвимост в SSLVPN, обновленията на фърмуера поправят седем пробива", "schlagzeile": "Защитни стени SonicWall: VPN уязвимост се атакува – обновете веднага", "kurz": "Нападатели очевидно използват уязвимост в SSLVPN на защитните стени SonicWall, с която може да се заобиколи SAML вписването, а с него и многофакторното удостоверяване. SonicWall и американската агенция CISA съветват бързо обновяване. SSLVPN е уязвим само ако SAML е включен за VPN вписване. Новият фърмуер поправя общо седем уязвимости.", "zusammenfassung": "SonicWall публикува в петък бюлетин за сигурност за седем уязвимости в SonicOS, съобщава heise online. За една от тях производителят допуска, че вече може да е използвана при атаки; американската агенция за сигурност CISA също предупреждава. Става дума за CVE-2026-19868 (CVSS 7.1, висок риск): който има валидни данни за вход за друг метод на вписване, може с нея да заобиколи SAML удостоверяването, което се използва например за единно вписване. Така очевидно може да се заобиколи и многофакторното удостоверяване, наложено чрез SAML. Според SonicWall SSLVPN е уязвим само ако SAML е включен за SSLVPN вписвания. Поправката е SonicOS 7.3.4-7013 за защитни стени Gen7 и 8.2.3-8015 за устройства Gen8, както и по-новите версии. Обновленията затварят още шест уязвимости, сред тях две с CVSS 8.8, свързани с междудомейн политики и проверка на сесии, и препълване на буфер в heap в SSL-VPN, което може да се задейства без удостоверяване (CVSS 7.5). Към тях се добавят две препълвания на буфер в TACACS+ и слабо хеширане на пароли при виртуални устройства, всички със среден риск. heise напомня, че SonicWall още в началото на октомври съобщи за критична уязвимост с максимална оценка в устройствата SMA1000. Засегнати са предимно фирми и администратори; който поддържа защитна стена SonicWall у дома или в офиса, трябва да обнови фърмуера сега.", "_src": "6679ffee"}, "2026-11-08-windows11-app-updates": {"titel": "Windows 11 тества централна страница за обновления на приложения от трети страни", "schlagzeile": "Край на изскачащите прозорци? Windows 11 тества общи обновления", "kurz": "В предварителна версия на Windows 11 26H2 в Настройките се появи нова страница „Обновления на приложения“. Тя трябва да събира на едно място обновленията на програми от трети страни, като браузъри или медийни плейъри, вместо всяко приложение да показва свои известия. Това ще работи само ако разработчиците регистрират приложенията си. При теста на Windows Latest още нямаше нито един регистриран доставчик.", "zusammenfassung": "Windows Latest откри в предварителна версия на Windows 11 26H2 страница „Обновления на приложения“ в Настройки > Приложения. Страницата вече се беше появявала за кратко през декември 2025 г. и сега се появи отново, което според Windows Latest подсказва скорошно пускане. Целта е обновленията на програми извън Microsoft Store да се събират на едно място, вместо всяко приложение да показва свои изскачащи прозорци, както навремето прочутият обновител на Java. Основата е „Windows Update Orchestration Platform“, която Microsoft представи през 2025 г. Разработчиците могат да регистрират там приложенията си като доставчици и да запазят собствените си сървъри и инсталатори за обновления; Windows поема само координацията. Ще се поддържат MSIX и APPX пакети, както и класически Win32 програми. За регистрация разработчиците трябва да предоставят скрипт или програма, която търси обновления; по подразбиране Windows изпълнява тази проверка на всеки 22 часа. Windows ще планира инсталирането подобно на системните обновления, като отчита използването, батерията и мрежата, за да не прекъсва работата. На тестовия компютър на Windows Latest обаче страницата съобщаваше, че няма регистриран доставчик на приложения, дори самата Microsoft за Teams или Outlook, а бутонът за проверка на обновления беше неактивен. Следователно това е функция в тестов етап, която още не може да се използва. Дали наистина ще помогне, зависи от това колко разработчици ще се включат; Microsoft не иска да принуждава никого. Microsoft не е обявила дата на пускане.", "_src": "06466579"}, "2026-11-08-nvidia-board-untersuchung-huang": {"titel": "Бордът на NVIDIA започва независимо разследване относно главния изпълнителен директор Дженсън Хуанг", "schlagzeile": "Бордът на NVIDIA започва разследване – CEO признава афера", "kurz": "Бордът на директорите на NVIDIA започна независимо разследване, след като медии съобщиха, че главният изпълнителен директор Дженсън Хуанг е бил мишена на чуждо разузнаване. В съобщение до служителите, публикувано от NVIDIA, Хуанг призна, че е изневерил на съпругата си. Според борда засега няма причина да се смята, че националната сигурност или фирмени тайни са компрометирани. Хуанг остава CEO.", "zusammenfassung": "Вечерта на 8 ноември 2026 г. NVIDIA публикува две изявления. В първото бордът обявява независимо разследване: комисия от независими директори с помощта на външни адвокати ще провери дали основателят и CEO Дженсън Хуанг е бил мишена на дейност на чуждо разузнаване. Бордът пише, че няма причина да смята, че националната сигурност или тайни на NVIDIA са компрометирани, но ще разгледа цялата налична информация. Хуанг подкрепя проверката и ще сътрудничи; бордът изразява доверие в него и в ръководния му екип. Във второто изявление, съобщение до служителите, публикувано първо от Axios, Хуанг се извинява на семейството си и на служителите и признава, че е изневерил на съпругата си. Предисторията са материали на Financial Times и New York Times от предходните дни. Според тях меморандум, основан на информация от американското разузнаване, приписва на Хуанг връзка с жена на име Алис Хуанг, бивш ръководител в Megaspeed, клиент на NVIDIA; според тези материали американските служби я смятали за информатор на Министерството на държавната сигурност на Китай. Въпреки еднаквата фамилия двамата не са роднини, според материалите. Нито меморандумът, нито основанията му са публични, а нито Хуанг, нито бордът коментират по същество обвиненията в шпионаж; според Axios съобщението на Хуанг не споменава Алис Хуанг. Следователно изявлението на борда не потвърждава обвиненията. Според NYT целта е била да се научи повече за американските AI чипове. Говорителят на NVIDIA Джон Рицо е заявил, според ComputerBase, че събитията няма да забавят работата на компанията. Не е ясно кога ще има резултати от разследването; бордът ще информира при необходимост.", "weitere_links": ["heise online", "IGN"], "_src": "ae83deda"}, "2026-11-08-layden-ps5-300": {"titel": "Бившият шеф на PlayStation Шон Лейдън: Sony има нужда от PS5 за 300 долара, а не от PS6 за 1200", "schlagzeile": "Бивш шеф на PlayStation: не PS6 за 1200 $, а PS5 за 300 $", "kurz": "Бившият шеф на PlayStation Шон Лейдън съветва Sony вместо скъпо PS6 да направи значително по-евтино PS5. „Иновацията не трябва да идва от PS6 за 1200 долара, а от още едно PS5 за 300 долара“, каза той в подкаста The Trophy Room. Според него PS5 е първата платформа, която с времето е поскъпнала. Това не казва нищо за официалните планове за PS6.", "zusammenfassung": "Шон Лейдън, бивш президент и CEO на Sony Interactive Entertainment America, коментира следващото PlayStation в подкаста The Trophy Room, съобщава IGN. Според него PS6, която залага основно на повече рейтрейсинг и повече терафлопа, не носи достатъчно истинска иновация. „Мисля, че имаме достатъчно мощ в машината“, каза Лейдън. За него истинската иновация не би била PS6 за 1200 долара, а още едно PS5 за 300 долара. Той припомни, че PS2 се е продавало за 99 долара в края на живота си, докато PS5 е първата платформа, която според него с времето поскъпва. Sony трябвало да направи конзолата по-малка и по-евтина; чипът и операционната система са достатъчно добри за игрите, които хората искат да играят. IGN дава контекст: при старта преди шест години PS5 струваше 499 долара в САЩ, а Digital Edition – 399 долара. Директно от PlayStation стандартната версия днес струва 649, Digital Edition – 599, а PS5 Pro – 899 долара. Sony обяснява поскъпванията с трудната икономическа среда. Официална информация за PS6 има малко: през май Sony каза, че още решава кога да я пусне, а доклад от февруари говореше за възможно отлагане до 2028 или 2029 г. Лейдън отдавна не е в Sony; думите му са лично мнение, а не информация за плановете на Sony. Конкретна цена на PS6 не е известна; 1200-те долара са изострен пример на Лейдън.", "_src": "5da916e2"}, "2026-11-08-amd-radeon-ssd-writes": {"titel": "AMD потвърждава грешка в драйвера Radeon, която постоянно пише на SSD", "schlagzeile": "Драйверът Radeon пише непрекъснато на SSD-то в покой", "kurz": "Някои потребители на карти AMD Radeon съобщават, че графичният драйвер постоянно пише върху системния SSD дори когато компютърът е в покой. За виновен се сочи процесът atieclxx, тоест AMD External Events Client Module. Според Wccftech и Neowin AMD е признала проблема и работи по поправка; тя не фигурира в бележките към Adrenalin 26.10.2 от 30.10.2026 г. Не всяка система изглежда засегната и не е доказано колко реално скъсява това живота на SSD.", "zusammenfassung": "На 8.11.2026 г. Wccftech и Neowin съобщиха за грешка в графичните драйвери Radeon на AMD, която може да предизвика постоянни записи върху системния диск, дори когато компютърът не прави нищо друго. За спусък се сочи процесът atieclxx, AMD External Events Client Module, който принадлежи към AMD External Events Utility и сред другото управлява смяна на монитори, бързи клавиши и FreeSync. Данните на потребителите често са между около 0,3 и 1,5 мегабайта в секунда, отделни доклади споменават около 5 мегабайта в секунда. При непрекъснати 5 MB/s това теоретично прави около 432 гигабайта хост записи на ден; Wccftech подчертава, че това е горна граница при постоянна натовареност и не съответства автоматично на обема, реално записан в NAND. Според репортажите не е доказано дали и колко грешката скъсява живота на SSD. Проблемът не бил съвсем нов и се появявал под Windows 10 и Windows 11 на различни карти Radeon и версии на Adrenalin; някои компютри с актуалния драйвер 26.10.2 според потребители изобщо не показват необичайно натоварване. Служител на AMD с име AMD_Matt през октомври потвърдил поведението като истински проблем, който се разследва. Друг представител, AMD_Vik, по-късно дал сигнал, че поправка вероятно вече е внесена, но може да е изпуснала срока за следващата версия на драйвера. Adrenalin Edition 26.10.2, излязла на 30.10.2026 г., не споменава грешката в официалните бележки към версията. Neowin добавя, че AMD е посочила връзка с PCIe филтъра на Microsoft и Resizable BAR. Като заобиколни решения и двете издания посочват временно спиране на услугата AMD External Events Utility през управлението на услугите на Windows или изключване на Resizable BAR; и двете могат да засегнат FreeSync, бързите клавиши на Adrenalin или производителността в игрите. Някои потребители обаче съобщават, че FreeSync и ReBAR са продължили да работят след спирането на услугата. Който иска да провери дали собственият му компютър е засегнат, трябва в Монитора на ресурсите, раздел Диск, да търси постоянна записваща активност от atieclxx. Според репортажите още няма обновление на драйвера с поправката.", "weitere_links": ["Neowin"], "_src": "f2340f0a"}, "2026-11-08-gpu-preise-plus40": {"titel": "Цени на видеокарти: средно почти 40 процента нагоре от август", "schlagzeile": "Видеокартите са почти 40% по-скъпи от август", "kurz": "GameStar сравни актуалните цени на видеокарти: от август 2026 г. следените модели са поскъпнали средно с почти 40 процента. Между януари и август промяната без RTX 5090 все още беше около три процента. Според анализа самата RTX 5090 е скочила от около 3000 евро през януари през 4350 евро през август до сегашни около 7500 евро.", "zusammenfassung": "На 8.11.2026 г. GameStar публикува нов поглед към уличните цени на актуалните видеокарти. През август същият преглед на 16 модела на AMD, NVIDIA и Intel без RTX 5090 все още показваше средна промяна около три процента спрямо януари 2026 г. Оттогава тенденцията при практически всички разгледани карти сочи само нагоре. Докладът съзнателно изключва RTX 5090 от средната стойност, защото като топ модел с 32 гигабайта памет тя заема особено място. Цената ѝ е нараснала от около 3000 евро през януари през 4350 евро през август до сегашни около 7500 евро. И под нея, чак до RTX 5050, картината също е мрачна: ако посоката се запази, RTX 5080 скоро ще е над 2000 евро, а за входната RTX 5050 ще се дължат почти 400 евро. За следените модели GameStar стига до средно поскъпване от почти 40 процента от август. Текстът сочи като причина продължаващия бум на изкуствения интелект. Хардуерни компании като AMD също ясно казвали, че се виждат преди всичко като фирми за центрове за данни, а не за игри. Всички известни на автора прогнози за кризата с паметта и хардуера приемат, че положението ще продължи години и по-скоро ще се влоши, отколкото да се подобри. Точните ценови прогнози са трудни; авторът все пак очаква още по-високи цени и по-лоша наличност. Процентите идват от собствения ценови анализ на GameStar; освен 5090, 5080 и 5050 текстът не изрежда цените на отделните модели в таблица.", "_src": "cf2fd89d"}, "2026-11-08-12v2x6-kabel-rtx-pro-6000": {"titel": "Повредени 12V-2×6 кабели при две RTX PRO 6000 въпреки първокласно захранване", "schlagzeile": "PC за 32 000 $: 12V-2×6 кабели се ронят при две RTX PRO 6000", "kurz": "Потребител в Reddit с две NVIDIA RTX PRO 6000 Blackwell откри повредена оплетка и на двата захранващи кабела 12V-2×6, въпреки че картите бяха ограничени до 500 вата. Повредите се появиха откъм GPU и откъм захранването, но нищо не се е стопило. Захранването е Seasonic PRIME TX-1600 Noctua Edition. Причината не е измерена; става дума за единичен случай.", "zusammenfassung": "VideoCardz съобщава за публикация в Reddit на потребителя Doomslayer606, който използва в работната си станция две NVIDIA RTX PRO 6000 Blackwell в 600-ватовата Workstation Edition с по 96 GB GDDR7. Според VideoCardz картите струват общо над 32 000 долара. Захранват се от Seasonic PRIME TX-1600 Noctua Edition с два собствени 16-пинови кабела. Въпреки че собственикът е ограничил двете карти до 500 вата, той забелязал и на двата кабела, че оплетката на два отделни проводника е твърда, напукана и лесно се отлепва. Повредите се появили както при конекторите на видеокартите, така и откъм захранването, където били дори по-големи, макар тези конектори почти да не са пипани. Самата изолация на проводниците останала непокътната, а нито по картите, нито по захранването имало видими следи от стопяване или обезцветяване. Преди това потребителят забелязал, че от време на време GPU или NVMe SSD изчезва от PCIe шината, затова няколко пъти е преоткачвал кабелите. Той подозира локално прегряване заради неравномерно разпределен ток, но температура и ток не са измервани. В резултат е купил резервни кабели с термична защита и обмисля да ограничи картите до 450 вата; при 300 вата е загубил 40 до 50 процента производителност в своите задачи. Според материала Seasonic и NVIDIA не са коментирали. Това е единичен случай без потвърждение от производителя, но се вписва в дългата поредица проблеми около 16-пиновия конектор. VideoCardz съветва захранващите конектори да се проверяват редовно, без постоянно да се откачват и закачват.", "_src": "a3d9d41a"}, "2026-11-08-rtings-woled-edge-rot": {"titel": "Дълготраен тест на RTINGS: 14 от 16 по-стари WOLED телевизора имат повредени пиксели по краищата", "schlagzeile": "„Edge rot“: 14 от 16 WOLED телевизора с мъртви пиксели по краищата", "kurz": "В 18 000-часовия тест на RTINGS 14 от 16 телевизора с WOLED панели на LG Display развиха мъртви пиксели по краищата на екрана. RTINGS нарича това „edge rot“; няма нищо общо с прегарянето. Трите тествани QD-OLED телевизора не бяха засегнати. Засегнати са основно модели от 2020 до 2022 г.; по-новите панели от 2024 г. насам не са тествани.", "zusammenfassung": "Тестовият сайт RTINGS публикува резултати от ускорения си тест за дълготрайност, в който телевизорите са работили около 18 000 часа. От 16 устройства с WOLED панели на LG Display 14 са развили мъртви пиксели, малки групи пиксели или видими повреди по краищата на екрана, т.е. 87,5 процента. RTINGS нарича явлението „edge rot“. За разлика от прегарянето, според RTINGS то не зависи от показването на статично съдържание и не може да се избегне с разнообразно съдържание. При по-старите WBC панели засегнати са 9 от 10 устройства, пет от тях тежко; при по-новите WBE панели – 5 от 6, сред тях модели на LG и Sony. LG G3 от 2023 г. не показа повреди по краищата. Трите QD-OLED телевизора с панели на Samsung Display нямаха edge rot; RTINGS обаче подчертава, че три бройки са твърде малко, за да се обяви QD-OLED за имунен. Три проверени OLED монитора, включително един WOLED модел, също не показаха повреди по краищата. Двама служители на RTINGS са открили проблема и на личните си устройства от 2020 и 2021 г. Точната причина не е изяснена; обсъждат се замърсяване при производството и слабости в защитния слой, който трябва да пази панела от влага. LG Electronics и LG Display потвърдиха пред RTINGS, че явлението може да се появи при малък брой продукти, изложени дълго на топлина, влага или други тежки условия, но не се очаква при нормални условия. 87,5 процента са резултат от малка тестова група при непрекъснато натоварване, а не процент на дефекти при всички продадени устройства. RTINGS все още не е установил дали са засегнати панели от 2024 г. насам.", "weitere_links": ["Hardware Busters"], "_src": "d6fa466e"}, "2026-11-07-warzone-switch2": {"titel": "Call of Duty: Warzone вече е безплатна на Nintendo Switch 2", "schlagzeile": "Warzone вече е безплатна на Nintendo Switch 2", "kurz": "Call of Duty: Warzone излезе на Nintendo Switch 2 и е безплатна в Nintendo eShop. Не е нужно да се купува Modern Warfare 4, но е нужен акаунт в Activision. Стартът съвпадна със Season 1; едновременно приключи поддръжката за PlayStation 4 и Xbox One.", "zusammenfassung": "Според Insider Gaming Call of Duty: Warzone е достъпна на Nintendo Switch 2 и може да се изтегли от eShop като самостоятелна безплатна игра. Който няма Modern Warfare 4, пак може да играе battle royale. Нужен е акаунт в Activision. Стартът дойде заедно със Season 1; Activision пише, че може да се влезе в Hajin, Zodiac и останалите карти и плейлисти, докато безплатната игра пристига за пръв път на преносимото устройство на Nintendo. Nintendo Life отрази офертата на 7.11.2026 и измери на собственото си устройство 122 GB; нямаме официален размер на изтеглянето от Activision. Insider Gaming представя хода като завръщане на поредицата към хардуера на Nintendo: Modern Warfare 4 според този разказ е първата Call of Duty на конзола Nintendo след Ghosts на Wii U. Със Season 1 Activision прекрати поддръжката за PlayStation 4 и Xbox One; напредъкът се твърди, че може да се пренесе на поддържани платформи чрез същия свързан акаунт в Activision. Разделителна способност, кадрова честота и подробности за crossplay на версията за Switch 2 не са посочени в наличното ни отразяване. Самият старт беше на 6.11.2026; използваната от нас статия на Insider Gaming излезе на 7.11.2026.", "weitere_links": ["Nintendo Life (измерване 122 GB)"], "_src": "88111250"}, "2026-11-07-pulse-elevate-verschoben": {"titel": "Sony отлага безсрочно тонколоните Pulse Elevate заради производствен проблем", "schlagzeile": "Sony отлага Pulse Elevate безсрочно – точно преди старта", "kurz": "Sony отложи безсрочно началото на продажбите на безжичните тонколони Pulse Elevate. Датата 12 ноември отпада, защото тестовете за качество са открили производствен проблем. Sony не посочва нова дата; какво става с вече направените предварителни поръчки, не е ясно.", "zusammenfassung": "На 6.11.2026 Sony отложи безсрочно старта на тонколоните Pulse Elevate в PlayStation Blog. Eurogamer и IGN отразиха съобщението на 7.11.2026. В блога Sony пише, че текущите тестове за качество са установили производствен проблем и затова е взето решение стартът да се отложи; допълнителното време трябва да гарантира, че продуктът ще даде предвиденото изживяване. Sony не посочва нова дата и не описва проблема подробно. Тонколоните трябваше да излязат в продажба по света на 12 ноември, само дни след съобщението. Препоръчителната цена на обновената страница в блога е 219,99 щатски долара, 219,99 евро и 199,99 паунда. Pulse Elevate е първата безжична двойка тонколони на Sony за настолни игри и стои до слушалките Pulse Elite и слушалките Pulse Explore. Свързват се чрез PlayStation Link с PS5, компютри, Mac и PlayStation Portal и могат едновременно да се сдвояват с телефон по Bluetooth. В дясната тонколона има микрофон с това, което Sony нарича подпомагано от ИИ потискане на шума. Вариантът Midnight Black трябваше да е наличен навсякъде, белият – само в избрани държави, сред които Германия, Австрия и Великобритания. Предварителните поръчки течаха от септември. Eurogamer пише, че не е ясно какво се случва сега с тези поръчки.", "weitere_links": ["PlayStation Blog (официално съобщение)", "IGN"], "_src": "67242cb4"}, "2026-11-07-anno117-fsr3-rtx30": {"titel": "Anno 117 Update 3.0: FSR 3 Frame Generation вече е включен по подразбиране на GeForce RTX 30", "schlagzeile": "Anno 117 вече включва Frame Generation на AMD при картите RTX 30", "kurz": "С Update 3.0 Anno 117: Pax Romana включва по подразбиране FSR 3 Frame Generation на AMD при картите GeForce RTX 30 в автоматичните графични настройки. Причина: собственият DLSS Frame Generation на NVIDIA работи едва от RTX 40 нагоре. Повече показвани fps обаче не означават по-малко забавяне на входа.", "zusammenfassung": "Ubisoft Mainz пусна на 5 ноември 2026 г. Update 3.0 за Anno 117: Pax Romana заедно с разширението „Dawn of the Delta“. Според официалните бележки към пача автоматичното разпознаване на графиката вече включва по подразбиране FSR 3 Frame Generation на AMD при картите GeForce от серията RTX 30. PCGH отрази това на 7 ноември и обяснява контекста: DLSS Frame Generation на NVIDIA официално е запазен за сериите RTX 40 и RTX 50, докато FSR 3 работи независимо от производителя и не изисква AI блокове. При системи, на които играта задава профил „Нисък“, Frame Generation обаче вече не се включва автоматично, за да се избегнат колебания при компютри близо до минималните изисквания. Ubisoft не дава конкретни данни за прираста на fps. Frame Generation вмъква междинни кадри: показваната честота на кадрите расте, но забавянето на входа не намалява от това. Други промени засягат накъсването при движение на камерата над големи градове, спадовете в производителността при маркиране на пътища и архива на книгата със задачи. Според бележките към пача обновлението оправя и множество сривове и грешки. Който не използва автоматичната настройка или не иска Frame Generation, може да го управлява в графичните опции.", "weitere_links": ["Anno Union: бележки към Update 3.0"], "_src": "e94737ea"}, "2026-11-07-assassins-creed-mars-rom": {"titel": "Доклад: Ubisoft работи по Assassin's Creed „Mars“ в Древен Рим и по мобилното отклонение „Pocket“", "schlagzeile": "Изтичане: Връща ли се Assassin's Creed в Рим?", "kurz": "Според създателя на съдържание J0nathan Ubisoft разработва Assassin's Creed с кодово име „Mars“, чието действие трябва да е в Древен Рим, както и мобилно заглавие „Pocket“ в Йерусалим. Insider Gaming знае кодовите имена, но не успя да провери достатъчно данните. Според доклада излизане би било възможно едва около 2029/2030 г.", "zusammenfassung": "Insider Gaming съобщи на 7 ноември 2026 г. за твърдения на youtuber-а J0nathan, който в миналото често е имал вярна информация за Assassin's Creed. Според него Ubisoft работи по Assassin's Creed с кодово име „Mars“, чието действие трябва да е в Древен Рим. Два източника с достъп до вътрешните системи на Ubisoft са потвърдили това; смята се за възможна връзка с планирания сериал по Assassin's Creed. Втори проект с кодово име „Pocket“ трябва да е мобилна игра с действие в Йерусалим. Insider Gaming казва, че също е чувал за кодовите имена, но не е успял да провери подробностите според своите стандарти. Поредицата напоследък преминава през бурен период, включително след напускането на Marc-Alexis Côté. Според по-ранни източници на Insider Gaming следващата голяма игра, Assassin's Creed Hexe, е отложена вътрешно с още една година, вероятно за 2028 г. Затова според доклада игра в Рим не би трябвало да се очаква преди 2029/2030 г. Ubisoft не коментира. Нищо не е потвърдено; проекти в ранен етап могат да се променят или да бъдат прекратени.", "zuverlaessigkeit_hinweis": "Непотвърдено: източникът е youtuber-ът J0nathan със смесена, но често точна история при Assassin's Creed. Insider Gaming знае кодовите имена, но не успя да провери подробностите. Няма изявление от Ubisoft.", "weitere_links": ["TheGamer: кодово име Mars"], "_src": "ef82e5b6"}, "2026-11-07-microsoft-gpu-patent-ki": {"titel": "Патентна заявка на Microsoft: неизползвана GPU мощ на лични устройства за AI обучение срещу кредити", "schlagzeile": "Пари за неактивната ти GPU? Патент на Microsoft описва AI обучение", "kurz": "Патентна заявка на Microsoft, публикувана на 5 ноември, описва система, която разделя AI обучението на малки подзадачи и ги разпределя към неизползвани GPU на крайни устройства. Потребителите трябва да се съгласят и биха могли да получават кредити. Microsoft не е обявила продукт.", "zusammenfassung": "Insider Gaming съобщава за патентна заявка на Microsoft със заглавие „Opportunistic Micro-training on Edge Devices Using Spare GPU Utilization“ (US-20260349820-A1), публикувана на 5 ноември 2026 г. Тя описва система, която разделя големи задачи за AI обучение на независимо обучаеми мини задачи и ги разпределя към устройства, чиято GPU в момента има малко работа. Дали едно устройство е свободно, трябва да се определя по натоварването на GPU и CPU, паметта, температурата и консумацията на ток. Според текста системата не бива да пречи на ползването, т.е. да забавя програми, да изтощава батерии или да прегрява устройства. Участват само потребители, които са съгласни. Извършената изчислителна работа трябва да се отчита и да се записва като кредит в профила, който може да се използва например за софтуер, достъп до модели или пари. Microsoft би била посредник между трети страни, нуждаещи се от изчислителна мощ, и собствениците на устройствата. Остават отворени въпроси за поверителността, разрешенията и допълнителното износване на видеокартата. Важно: патентната заявка не е обещание за продукт; много патенти никога не се реализират. Microsoft не е обявила подобна услуга.", "_src": "1f47cb8a"}, "2026-11-07-hwinfo-rx7500-razor-lake": {"titel": "Бета на HWiNFO разпознава необявената Radeon RX 7500 и Intel Razor Lake-H/HX/S", "schlagzeile": "Изтичане: HWiNFO познава RX 7500 и Razor Lake", "kurz": "Бета HWiNFO 8.55 Build 6115 изброява AMD Radeon RX 7500, която AMD още не е обявила. Същият билд подобрява разпознаването на Intel Razor Lake-H, -HX и -S, както и Nova Lake-E. Спецификациите и пускането на RX 7500 остават неизвестни; поддръжката на име в инструменти не е гаранция за пускане.", "zusammenfassung": "TechPowerUp и VideoCardz съобщават, че бета HWiNFO версия 8.55 Build 6115 за първи път разпознава „AMD Radeon RX 7500“. AMD не е представила официално картата; в changelog има само името, без спецификации или дата. TechPowerUp смята Navi 33 / RDNA 3 за най-вероятния кандидат за чип, защото тази архитектура вече захранва RX 7400 и RX 7600 – модел помежду им би бил тясно позициониран. Името RX 7500 или RX 7500 XT според доклади се е появявало още в по-стари слухове около 2024, без конкретен пуск. VideoCardz допълнително сочи към по-ранни прототипни следи за Navi 33 XE с 6 GB GDDR6 и Device-ID 749F; дали финалният продукт изглежда така, не е потвърдено. Същият билд на HWiNFO разширява поддръжката за Intel Nova Lake-E и Razor Lake-H/HX/S. Razor Lake се смята за следващо поколение след Nova Lake; retail чиповете са далеч, тъй като Nova Lake-S се очаква едва около Q1 2027. CPU-Z 3.02 вече добави Razor Lake в началото на седмицата; HWiNFO имаше временна поддръжка за Razor Lake-AX още през август. AMD и Intel не са потвърдили записите.", "zuverlaessigkeit_hinweis": "Непотвърдено: Само поддръжка на име/ID в бета HWiNFO 8.55-6115 и доклади от TechPowerUp и VideoCardz. Няма официално обявление от AMD или Intel; спецификациите и пускането на RX 7500 са неизвестни. Разпознаването от инструмент не е гаранция за пускане.", "weitere_links": ["VideoCardz: HWiNFO RX 7500 и Razor Lake", "Форум HWiNFO: Бета 8.55-6115"], "_src": "34935787"}, "2026-11-07-vulkan-1-4-368": {"titel": "Vulkan 1.4.368 с нови разширения от Valve и NVIDIA", "schlagzeile": "Vulkan 1.4.368: Valve и NVIDIA добавят нови разширения", "kurz": "Khronos Group пусна Vulkan 1.4.368. Седмичното обновление носи две нови разширения: едно от Mesa разработчика на Valve Mike Blumenkrantz за данни на върхове и разширение на NVIDIA за вътрешни драйверни хендъли. За играчите нищо не се променя веднага; това е градивен елемент за драйвери и енджини.", "zusammenfassung": "Vulkan 1.4.368 е най-новото седмично обновление на спецификацията на междуплатформения графичен и изчислителен интерфейс, както съобщи Phoronix на 7 ноември 2026 г. По съдържание обновлението е малко: отстранени са шест вътрешно докладвани проблема в спецификацията. Нови са две разширения. VK_EXT_vertex_address_binding_unrestricted е от Mike Blumenkrantz от Linux графичния екип на Valve, известен Mesa разработчик. То помага, когато данните за върховете при едно извикване за рисуване се изнасят в отделен буфер, за да се пести памет, и за целта изключва една проверка на адресите. Второто, VK_NV_internal_handle, е собствено разширение на NVIDIA: с него програми и енджини могат да получават вътрешни драйверни хендъли за определени Vulkan обекти и да ги подават към други интерфейси на NVIDIA. Двете разширения първо трябва да стигнат до драйверите и софтуера, преди да променят нещо в игрите. Vulkan е, наред с другото, основата на Proton в Linux и Steam Deck, където приносът на Valve е особено важен. Всички подробности са в хранилището Vulkan-Docs на Khronos Group в GitHub.", "weitere_links": ["Khronos Vulkan-Docs в GitHub"], "_src": "9f12e9de"}, "2026-11-07-razor-lake-lga1954-2028": {"titel": "Доклад: Intel Razor Lake-S трябва да излезе през 2028 г. върху сокета LGA 1954 на Nova Lake", "schlagzeile": "Изтичане: Razor Lake ще пасне ли на сокета на Nova Lake през 2028?", "kurz": "Според инсайдъра Jaykihn Razor Lake-S на Intel в момента е планиран за 2028 г. и трябва да използва същия сокет LGA 1954 като Nova Lake-S. Който премине на Nova Lake през 2027 г., би могъл да надгради с още едно поколение процесори без нова дънна платка. Intel не е потвърдила нищо от това.", "zusammenfassung": "На 7 ноември 2026 г. Wccftech и HotHardware обобщиха изказвания на инсайдъра за Intel Jaykihn: Razor Lake-S е „в момента планиран като продукт за 2028 г.“, а Intel официално не е казала нищо. Nova Lake-S, следващото настолно поколение, се очаква в началото на 2027 г. и въвежда новия сокет LGA 1954. Според докладите Razor Lake-S трябва да работи на същия сокет, така че Intel за първи път от доста време би имала две настолни поколения на една платформа. Още през юни Jaykihn писа, че LGA 1954 ще поддържа дори процесори след Razor Lake на платки с 64 MB BIOS флаш памет, включително всички Z платки. Като архитектура на P-ядрата на Razor Lake докладите посочват Griffin Cove, наследник на Coyote Cove от Nova Lake; настолните чипове няма да имат SMT. Освен това някои варианти, първоначално планирани за Nova Lake, като Nova Lake-AX, са преминали към семейството Razor Lake. Тримесечието през 2028 г. не е известно; Wccftech предполага Computex 2028 или втората половина на годината. Мениджърът на Intel Robert Hallock загатна през март, че компанията се вслушва в критиките за честата смяна на сокети, но конкретен ангажимент няма. Вижда се първа подготовка: CPU-Z 3.02 и бета версия на HWiNFO вече разпознават Razor Lake. Всички данни за срок и сокет са непотвърдени и може да се променят; решенията за покупка не бива да се основават на тях.", "zuverlaessigkeit_hinweis": "Непотвърдено: изказвания на инсайдъра Jaykihn (X), който често е бил прав за пътните карти на Intel; подхванати от Wccftech и HotHardware. Няма потвърждение от Intel; срокът и сокетът може да се променят.", "weitere_links": ["HotHardware: Razor Lake-S на LGA 1954", "VideoCardz: LGA 1954 и след Razor Lake (юни)"], "_src": "4d9282a2"}, "2026-11-07-cpuz-ram-rueckgang": {"titel": "Статистика на CPU-Z: делът на компютрите с 32 и 64 GB спада за първи път на годишна база", "schlagzeile": "За първи път по-малко RAM: CPU-Z отчита ръст на компютрите с 16 GB", "kurz": "Според статистиката на CPU-Z Validator делът на компютрите с 32 GB RAM спада с 2,5% на годишна база, а при 64 GB – дори с 18%. Системите с 16 GB и 8 GB обаче растат, а DDR4 печели дял пред DDR5. Данните отразяват само подадени валидации, не пазарни данни.", "zusammenfassung": "Doc TB, един от разработчиците на CPU-Z, публикува на 6 ноември 2026 г. нови данни от CPU-Z Validator, а VideoCardz ги разгледа на 7 ноември. Според тях обемът RAM в регистрираните компютри намалява за първи път на годишна база. 32 GB остава най-честата конфигурация с 37,2%, но губи 2,5% от дела си. При 64 GB спадът е 18%, а делът вече е 7,3%. Системите с 16 GB растат с 12,9% до 33,0% и са точно зад 32 GB. Растат и 8 GB – с 5,5% до 11,0%, както и 24 GB – с 19,7% до 2,3%. При поколението памет DDR4 расте с 6,0% до 54,5%, а DDR5 пада с 2,9% до 32,9%. Данните не посочват причина, но съвпадат със силно поскъпналата RAM през последните месеци, за която тикерът съобщава многократно. Важно: статистиката се базира само на системи, които потребителите активно подават във валидатора, и не е пазарно проучване. Промените са относителни дялове и не означават, че собствениците махат RAM.", "weitere_links": ["Doc TB (CPU-Z) в X, 06.11.2026"], "_src": "299d8b24"}, "2026-11-07-custom-engine-wald-rtx3080": {"titel": "Собствен енджин: разработчик рендерира гъста гора с около 130 fps на RTX 3080 – без хардуерен ray tracing", "schlagzeile": "130 fps на RTX 3080: любителски енджин рендерира гора без ray tracing", "kurz": "Разработчикът и модър Toni Macaroni показва собственоръчно написан енджин, който трябва да рендерира гъста гора в 1440p със средно около 130 fps на RTX 3080. Той разчита на геометрия, подобна на Nanite, воксели и вокселно осветление вместо хардуерен ray tracing. Стойностите идват от самия разработчик и става дума само за техническо демо.", "zusammenfassung": "PCGH и Wccftech съобщават за техническо демо на разработчика и модър Toni Macaroni, чието видео в YouTube според PCGH има над 500 000 гледания. По собствените му думи работи по енджина от около осем месеца, след като дълго е използвал енджина с отворен код Godot. Сцената показва хълмист пейзаж с гъста гора, около един милион инстанции и четири милиона триъгълника. На GeForce RTX 3080 в 1440p трябва да постига средно около 130 fps, до 200 при въздушни кадри и около 80 fps в гъстия подлес. Технически енджинът използва групирани нива на детайлност с виртуална геометрия, подобна на Nanite, вокселни представяния за далечната растителност и опростени проксита за много далечни обекти. Осветлението съчетава screen-space техники с вокселно глобално осветление и минава без хардуерно ускорен ray tracing, подобно на подхода в Kingdom Come: Deliverance II. Енджинът е умишлено специализиран: преди всичко трябва да показва добре много обекти с голям брой полигони, а системата за времето е готова само частично. Стойностите за fps са данни на разработчика; точните настройки и евентуален ъпскейлинг не са известни. Демо без персонажи, физика и AI не е сравнимо с готова игра, а публична версия засега няма.", "weitere_links": ["Wccftech: Custom Forest Engine"], "_src": "9e0e5944"}, "2026-11-07-windows-hello-pin-parallel": {"titel": "Windows 11 Insider: PIN успоредно със сканиране на лице или пръстов отпечатък от Windows Hello", "schlagzeile": "Windows 11: въвеждане на PIN докато Hello сканира", "kurz": "В експерименталния Insider билд на Windows 11 26340.9882 може да се въвежда PIN, докато Windows Hello още проверява лице или пръстов отпечатък. Заключеният екран показва „Look at the camera or enter your PIN“; печели методът, който заработи пръв. Разпространението е експериментално; няма retail дата.", "zusammenfassung": "Windows Latest тества Build 26340.9882 от 6 ноември 2026 (база Windows 11 26H2, Experimental канал): На екрана за вход полето за PIN се появява успоредно с проверката на Windows Hello. Вместо да се чака провал на лицевото разпознаване или неудобно да се избират опции за вход, бележките на Microsoft казват „whichever method works first“. След рестарт PIN-first остава от съображения за сигурност. Ако Face се провали, има директен намек „Retry face sign-in“. На устройства с IR камера и сензор за пръстов отпечатък подсказката може да спомене лице и отпечатък, с PIN отдолу. Новост: Event Log ID 4628 и 4629 под Security за настроени или неуспешни Hello методи; допълнителни Operational събития помагат на ИТ. Според теста функцията се е появила без ViVeTool. Експерименталните билдове могат да съдържат бъгове; Microsoft не каза кога поведението ще стигне стабилния канал.", "_src": "fc64848d"}, "2026-11-07-tsmc-3d-dram-nvidia": {"titel": "TSMC обмисля вход в 3D-DRAM – тласъкът се твърди, че е от NVIDIA", "schlagzeile": "TSMC обмисля 3D-DRAM: тласъкът се твърди, че е от NVIDIA", "kurz": "Според доклад на The Information от 6.11.2026 договорният производител TSMC обмисля вход в производството на 3D-DRAM. Тласъкът се твърди, че е дошъл от NVIDIA, най-големия клиент на TSMC. Докладът не посочва конкретни заводи, инвестиции или начална дата. TSMC не пожела да коментира пазарни слухове пред The Information и препрати към ролята си на логическа фабрика; NVIDIA според текста не е отговорила.", "zusammenfassung": "The Information съобщи на 6.11.2026, позовавайки се на двама души, запознати с разговорите, че TSMC обмисля вход в производството на 3D-DRAM. Отключващият фактор се твърди, че е била заявка от NVIDIA. igor'sLAB подхвана и коментира доклада на 7.11.2026. Според този разказ TSMC е започнала да изработва възможни производствени концепции за вертикално изградена DRAM; посочените варианти са строеж на нови заводи или придобиване на съществуващ завод и последващото му преобразуване. Не са посочени начало на производство, суми за инвестиции или планиран капацитет. Инициативата се твърди, че се води от Hsu Kuo-chin, вицепрезидент на TSMC за Advanced Packaging, който преди това е работил за Micron в Тайван. TSMC заяви пред The Information, че по принцип не коментира пазарни слухове, и посочи насочеността си като фабрика за логически чипове. Според доклада NVIDIA не е отговорила на запитване, а Reuters не успя независимо да потвърди сведенията. Технически 3D-DRAM е нещо различно от вече утвърдената High Bandwidth Memory: при HBM се подреждат няколко отделно произведени DRAM чипа, а при 3D-DRAM самите слоеве паметови клетки трябва да се интегрират вертикално, за да се увеличи плътността. Успешен вход би въвел TSMC на пазар, който досега се владее главно от Samsung, SK hynix и Micron. Същевременно от доклада не следва близък старт на масово производство, защото топлината, интеграцията на процесите и достатъчният добив се смятат за открити пречки, а разработката може да отнеме години. На фона на оскъдната и скъпа памет за компютри и центрове за данни допълнителен производител би бил съществен, но засега има само медиен доклад и възможни развойни обсъждания.", "weitere_links": ["The Verge (чрез The Information)", "Seoul Economic Daily", "Wccftech (обновление)"], "_src": "406e56e5"}, "2026-11-06-openai-gpt6-cyber-bugs": {"titel": "OpenAI представя GPT-6 Cyber: според фирмата 81 находки във Firefox и 948 Linux LPE", "schlagzeile": "OpenAI GPT-6 Cyber намира 81 бъга във Firefox и 948 в Linux", "kurz": "OpenAI представи GPT-6 Cyber, непубличен модел за сигурност. Според фирмата е открил 81 неизвестни досега high-severity уязвимости във Firefox и е разработил експлойти за 948 случая на локално повишаване на привилегии в Linux. Цифрите са от OpenAI и не са независимо пълно одитно потвърждение.", "zusammenfassung": "BleepingComputer, Phoronix и Golem съобщават за обявата на OpenAI за GPT-6 Cyber. Моделът не е публичен и в момента е ограничен до активирани клиенти в програмата Daybreak Red. OpenAI твърди, че е открил 81 неизвестни досега high-severity уязвимости във Firefox и е съразработил пачове; много вече били разгърнати в Mozilla. За изследване на Linux ядрото OpenAI цитира 2308 потенциални находки, 1724 възпроизведени уязвимости и 948 експлойта за локално повишаване на привилегии от unprivileged към root. В бенчмарка ExploitGym фирмата цитира 48,5% успех срещу 32,1% при предшественика GPT-5.6 Cyber. В Preparedness Framework OpenAI оценява cyber способността като „Critical“. Независимата дълбочина на одит за обхват и тежест е ограничена – цифрите са фирмени твърдения, не доказателство, че „Linux е общо взето несигурен“. OpenAI предупреждава за ограничен времеви прозорец, в който защитниците трябва да ползват frontier модели за укрепване, преди подобни способности да станат по-широко достъпни.", "weitere_links": ["Phoronix: OpenAI 948 Linux LPE Bugs", "Golem: OpenAI твърди, че е намерил почти 1000 root уязвимости"], "_src": "1b3a3edb"}, "2026-11-06-zen6-tee-riscv": {"titel": "AMD Zen 6: фирмуерен намек за TEE на база RISC-V вместо ARM PSP", "schlagzeile": "Zen 6: AMD преминава TEE от ARM към RISC-V", "kurz": "Commit в linux-firmware за AMD PMF Trusted Application на Zen 6 клиент (Family 1Ah M80h) споменава TEE на база RISC-V. Досега Secure Processor обикновено работеше на ARM Cortex-A5 с TrustZone. Дали RISC-V е наистина нов от Zen 6, или само за първи път е документиран, остава отворено.", "zusammenfassung": "Phoronix съобщава за commit в linux-firmware, който добавя PMF-TA firmware v4 за платформата 1AH_M80H – това съответства на предстоящите AMD Ryzen Zen 6 клиентски CPU. Текстът на commit-а казва, че Trusted Application вече работи на TEE на база RISC-V, използва по-голям shared-memory layout и разширени policy условия, включително до 20 персонализирани BIOS входа. Platform Management Framework управлява сред другото мощност, термика и системно поведение. Традиционно AMD Platform Security Processor / Secure Processor се базираше на ARM Cortex-A5 с TrustZone. Phoronix не намира по-стари публични намеци за RISC-V TEE в Ryzen/EPYC и оставя отворено дали функцията е нова за Zen 6, или при по-стари SoC просто никога не е споменавана. Commit-ът не назовава финален маркетингов етикет на поколението Ryzen. За Linux enablement и ентусиасти по сигурността архитектурната смяна все пак е рядък детайл за Zen 6 преди продуктовия пуск.", "_src": "73845857"}, "2026-11-06-epic-linux-launcher-distros": {"titel": "Epic Games Launcher Preview: широка поддръжка на Linux дистрибуции и планирано връщане на AppImage", "schlagzeile": "Epic: новият launcher ще поддържа много Linux дистрибуции", "kurz": "Epic потвърждава пред GamingOnLinux, че новият launcher в preview трябва да поддържа колкото се може повече Linux дистрибуции – изрично сред тях Fedora, SteamOS, Cachy и Omarchy. Опаковането още се променя; AppImage трябва да се върне още този месец. Preview не означава готова матрица от дистрибуции.", "zusammenfassung": "GamingOnLinux попита Jake Jones (Communications Director, Epic Games) за Linux поддръжката на новия Epic Games Launcher. Според изявлението Epic планира да поддържа „колкото се може повече Linux дистрибуции“, включително Fedora, SteamOS, Cachy, Omarchy и други. Preview започна с AppImage, по-късно премина към .deb за Debian/Ubuntu; FAQ посочваше Fedora като скоро. Epic тества и оценява формати за опаковане и иска да възстанови AppImage още този месец. Докато матрицата не е фиксирана, форматите могат да идват и да си отиват. Flatpak/Flathub остава отворено в съобщението. Статусът на launcher-а е Preview, не финален store rollout за всяка дистрибуция. Fortnite или Easy Anti-Cheat v2 са отделна тема и тук не се продават като „Fortnite идва на Linux“. Заедно с вече известния прозорец на GOG Galaxy за Linux през 2027 конкуренцията на store клиенти на Linux остава интересна.", "_src": "e2ba62e3"}, "2026-11-06-mindfactory-cyberangriff": {"titel": "Mindfactory съобщава за кибератака: паролите на клиенти са нулирани, органът е уведомен", "schlagzeile": "Mindfactory: хакерска атака – паролите са нулирани", "kurz": "Хардуерният магазин Mindfactory съобщи на 6 ноември 2026 за кибератака и уведоми клиенти и органа за защита на данните. Възможно засегнати: адрес, имейл, телефон и криптирани пароли; банковите данни според магазина не са в shop системата. Всички shop пароли са нулирани; нужна е предпазливост към фишинг.", "zusammenfassung": "heise online и Golem съобщават, че Mindfactory е станал жертва на кибератака и е уведомил клиентите с изявление. Компанията е подала сигнал до властите и е включила компетентния орган за защита на данните. Според актуалното състояние Mindfactory не може да изключи, че нападатели са получили достъп до адрес, имейл, телефон и криптирано съхранени пароли. Пароли в ясен текст и банкови или картови данни според компанията не са засегнати, защото платежните данни са при доставчици на услуги. Всички клиентски пароли за магазина са нулирани превантивно; следващият вход изисква нова парола, занапред с модерен hash метод. Управителят Marcel Kirchner говори за форензично разследване, без изнудване и за затворена уязвимост. Клиентите трябва да са внимателни към неочаквани имейли, SMS или обаждания, защото контактните данни могат да се злоупотребят за измами. Бележка за прозрачност: Mindfactory принадлежи към групата heise от средата на 2025; heise online е част от същата корпоративна група. Обхватът и точният момент на атаката все още се изясняваха към момента на съобщението.", "weitere_links": ["Golem: Хакери атакуват Mindfactory", "GameStar: Кибератака при Mindfactory"], "_src": "c989d014"}, "2026-11-06-nier-366gb-update": {"titel": "Ъпдейт на NieR: Automata по погрешка иска 366 GB – обявена е поправка", "schlagzeile": "Ъпдейт на NieR: Automata изяжда 366 GB – студиото се извинява", "kurz": "Steam ъпдейт за NieR: Automata от 6 ноември 2026 (JST) изисква много повече място от предвиденото — Insider Gaming сочи 366 GB срещу около 50 GB за базовата игра. Трябвало да добави езици; обявени са поправка и заобиколен път чрез махане на DLC.", "zusammenfassung": "Insider Gaming съобщава за дефектен Steam ъпдейт на NieR: Automata: след този от 6 ноември 2026 (японско време) размерът на инсталацията е далеч по-голям от предвидения — около 366 GB срещу ~50 GB за базовата игра. Бележките говореха за добавяне на опростен китайски, традиционен китайски и корейски. Акаунтът NieR Series в X се извини и обяви поправка. Заобиколен път: Properties → DLC, махане на DLC и продължаване с базовата игра. Няма ново сюжетно DLC от 2024; играта е надминала 10 млн. копия през февруари 2026. Кратката бележка не обяснява точната причина за раздутия даунлоуд.", "_src": "c9a67187"}, "2026-11-06-qnap-plex2shell": {"titel": "QNAP предупреждава: нападатели компрометират NAS през Plex2Shell в Plex Media Server", "schlagzeile": "QNAP: хакери атакуват NAS през Plex2Shell – обновете Plex", "kurz": "QNAP докладва компрометирания на NAS през веригата уязвимости Plex2Shell в Plex Media Server. Потребителите трябва да обновят Plex в App Center поне до 1.43.3.10861; при съмнение може да се наложи преинсталация на ОС. Самият QTS не е засегнат.", "zusammenfassung": "BleepingComputer отразява предупреждение за сигурност на QNAP: няколко потребители са докладвали, че Plex Media Server на техните NAS е компрометиран през уязвимостите Plex2Shell. Plex2Shell обхваща четири CVE (CVE-2026-96652, CVE-2026-96654, CVE-2026-96655, CVE-2026-96656), докладвани от Zach Main на 27 юли; експлоатацията е започнала след публикуване на техническите детайли на 16 октомври. CISA е добавила CVE в каталога Known Exploited на 20 октомври 2026 с кратък срок за агенциите. QNAP казва, че уязвимостите са само в Plex Media Server, не в QTS/QuTS hero. Препоръчва обновяване до Plex 1.43.3.10861 от App Center на QNAP. Който има уязвим Plex, достъпен от интернет, трябва да третира устройството като потенциално компрометирано: обновяването не премахва вече инсталирани payload-и. QNAP съветва чиста преинсталация на QTS/QuTS hero, нулиране на пароли и — ако трябва отдалечен достъп — VPN вместо препращане на порт 32400.", "_src": "48cb0d6c"}, "2026-11-06-ratchet-ranger-rumble": {"titel": "Ratchet & Clank: Ranger Rumble се спира – сървъри до май 2027", "schlagzeile": "Ratchet & Clank: Ranger Rumble свършва – сървъри на 1 май 2027", "kurz": "Мобилният спин-оф Ratchet & Clank: Ranger Rumble е отменен: финален ъпдейт на 6 ноември 2026, премахване от магазините на 21 ноември, спиране на сървърите на 1 май 2027. Играта все още беше в soft launch преди планираното глобално пускане.", "zusammenfassung": "IGN съобщава за спирането на Ratchet & Clank: Ranger Rumble. Според студиото последният планиран ъпдейт излиза на 6 ноември 2026; приложението напуска магазините на 21 ноември 2026. Който вече я има, може да играе до 1 май 2027, когато сървърите спират окончателно. Покупки в приложението са премахнати; възстановяванията сочат към Apple или Google. Arena shooter спин-офът е от Oh BiBi с Insomniac Games и PlayStation Studios и все още е бил в soft launch преди световна премиера, според IGN. Още през юли блогът на PlayStation говореше за скорошно глобално пускане след успешна тестова фаза. VGC също отразява отмяната на безплатния мобилен шутер.", "weitere_links": ["VGC: Sony’s Ratchet & Clank mobile shooter cancelled"], "_src": "99d65582"}, "2026-11-06-poe2-1-0-exilecon": {"titel": "Path of Exile 2 пълно пускане на 11 декември 2026: Shadow, Duelist и лига Conquerors of Wraeclast", "schlagzeile": "Path of Exile 2 1.0: Shadow, Duelist, старт 11.12.", "kurz": "Grinding Gear Games обяви на ExileCon пълното пускане на Path of Exile 2 за 11 декември 2026. Новости: класовете Shadow и Duelist, както и завършените кампанийни актове пет и шест. Идва и лигата „Conquerors of Wraeclast“ с изграждане на база и армия.", "zusammenfassung": "PC Gamer обобщава keynote на ExileCon за Path of Exile 2 версия 1.0: Пълното пускане след около две години Early Access е датирано за 11 декември 2026. Стартират два нови класа: Shadow, фокусиран върху кинжали и капани със stealth, и Duelist, ориентиран към мечове. Shadow според студиото може да ascend-не като Assassin или да избере новата Ascendancy Infiltrator; трета Ascendancy е планирана по-късно. Stealth предотвратява чудовищата да виждат героя от разстояние, се нулира при убийство и взаимодейства с капани, които от скривалището се задействат едва при разкриване. Кампанията получава актове пет и шест, включително завръщане в Oriath и въведение в лига механиката. „Conquerors of Wraeclast“ носи base building, армии, командири и по-късно фракционно обвързани Atlas битки. Endgame-ът силно стеснява Atlas skill tree, преработва gems и passive tree включително jewel слотове и добавя много нови bases и uniques. Точният час на пускане и още Ascendancy детайли може още да последват след текущия ExileCon.", "weitere_links": ["PC Gamer: клас Shadow за PoE2 1.0"], "_src": "6ec09cc3"}, "2026-11-06-nvidia-11mio-diebstahl": {"titel": "Хардуер на NVIDIA за 11,4 млн. долара откраднат при транспорт от Оукланд към Тексас", "schlagzeile": "11,4 млн. $ хардуер NVIDIA: шест палета изчезват по пътя", "kurz": "Полицията в Оукланд разследва кражбата на шест палета хардуер NVIDIA за 11,4 млн. долара. Камион с лого на хранителен транспорт е взел товара на 29 август и е изчезнал; следата свършва в окръг Сан Бернардино. Няма обявени арести.", "zusammenfassung": "Според VideoCardz и местната станция ABC7 News полицията в Оукланд (Калифорния) разследва голяма кражба на хардуер NVIDIA. Шест палета с декларирана стойност 11,4 млн. долара е трябвало да отидат от Оукланд до Форт Уърт, Тексас. На 29 август 2026 камион с лого на фирма за хранителен транспорт е взел товара според плана — след това превозното средство и шофьорите са изчезнали. Следователите са проследили няколко дълги спирания и са загубили следата в окръг Сан Бернардино. Сигналът към полицията е чак на 13 септември. Какви точно продукти е имало на палетите (AI ускорители, цели системи или потребителски GPU) не е публично потвърдено; средната стойност е около 1,9 млн. долара на палет. Професор Олаф Грот (UC Berkeley) каза пред ABC7, че такива чипове са много по-скъпи в чужбина и са риск за сигурността. VideoCardz споменава и по-ранни кражби, свързани с NVIDIA в Bay Area (над 7,5 млн. през 2025) и случай в Бразилия с откраднати ZOTAC RTX 5090. Засега няма арести и потвърждение, че товарът е открит.", "weitere_links": ["ABC7 News: $11.4M Nvidia cargo stolen from Oakland", "Wccftech: NVIDIA GPUs Worth $11.4 Million Stolen"], "_src": "8bfcec8e"}, "2026-11-06-micron-fab-stop": {"titel": "Micron уж спира строежа на RAM фабрика в Тайван заради спор със синдикати", "schlagzeile": "Micron спира RAM фабрика в Тайван – спор със синдикати", "kurz": "PCGH съобщава, позовавайки се на Bloomberg, че Micron е спряла строежа на фабрика в Таоюан и е замразила плановете за разширение. Фонът е конфликт с тайвански синдикати за дял от печалбите. Пълно излизане не е потвърдено.", "zusammenfassung": "Според PC Games Hardware и източници на Bloomberg на място Micron е спряла строежа на планирана полупроводникова фабрика в Таоюан (Тайван) и иска да замрази плановете за разширение. PCGH оценява инвестицията на около 4 млрд. евро. Стъпката се вписва в по-дълъг конфликт със синдикати, които искат дял на служителите от растящите печалби. В Тайчжун преди две седмици е постигнат компромис, чието приемане сред работниците е спорно; в Таоюан преговорите продължават, включително символична стачка — първата в тайванската полупроводникова индустрия. Синдикатът в Таоюан отхвърля вината и казва, че не иска да застраши печалбите на фирмата. Дали спирането е трайно или лост за преговори, остава отворено. За купувачите на PC е важно, защото повече RAM капацитет се вижда като изход от недостига — а този капацитет сега спира.", "_src": "2080eae5"}, "2026-11-06-switch2-verkauf-minus37": {"titel": "Switch 2: Nintendo отчита 37,4% по-малко хардуерни продажби за полугодието", "schlagzeile": "Switch 2: 37% по-малко продажби от рекордната година – софтът расте", "kurz": "Според данни на Nintendo и GameStar sell-in на Switch 2 от април до септември 2026 е паднал с 37,4% до 6,49 млн. броя (предишна година 10,36 млн.). Софтуерът е нараснал с 18,8%; годишната прогноза от 16,5 млн. остава.", "zusammenfassung": "GameStar обобщава полугодишните числа на Nintendo: от април до септември 2026 Nintendo е продала на търговията 6,49 млн. Switch 2 — с 37,4% по-малко от 10,36 млн. за същия период предната година. В първото тримесечие 3,82 млн., от юли до септември още 2,67 млн. Годишното сравнение е изкривено от премиерата на 5 юни 2025 и натрупаното търсене. От септември Switch 2 е по-скъпа (Европа официално 499,99 €). Nintendo сочи цени на памет, валутни курсове и петрол. Годишната прогноза от 16,5 млн. до март 2027 остава според GameStar и VGC. Софтуерът за Switch 2 е нараснал с 18,8% до 24,49 млн. броя за полугодието; нетната печалба — с единадесет процента. VGC добавя, че Switch 2 все още води оригиналната Switch и PS5 по кумулативна база от премиерата. Това са sell-in числа, не непременно продажби към крайни клиенти.", "weitere_links": ["Nintendo IR: Financial Results Explanatory Material", "VGC: Switch 2 sales down 37%, still beating original"], "_src": "9aaf69f1"}, "2026-11-06-rtx5070ti-doppel-msrp": {"titel": "GeForce RTX 5070 Ti почти достига двойната MSRP в американски онлайн магазини", "schlagzeile": "RTX 5070 Ti стига 1340 $ – почти двойна MSRP в САЩ", "kurz": "След RTX 5090 и 5080 скача и RTX 5070 Ti: най-евтината проследена онлайн оферта в САЩ е 1339,99 $, някои модели 1499,99 $. MSRP при старта беше 749 $. NVIDIA преди това отричаше слухове за прекратяване.", "zusammenfassung": "VideoCardz съобщава, че GeForce RTX 5070 Ti се продава доста над MSRP в големи американски онлайн магазини. Картата стартира през февруари 2025 с MSRP 749 $; най-евтината проследена оферта на 6 ноември 2026 е 1339,99 $ (около 79% над MSRP). Модели в B&H и Best Buy са около 1400–1499,99 $ — близо или двойно спрямо стартовата цена. За осем дни най-евтината проследена цена е нараснала със 160 $ (от 1179,99 $ на 29 октомври). Примери: GIGABYTE AERO OC в Newegg за 1339,99 $; ASUS PRIME OC и TUF GAMING OC в B&H за 1399,99 $ и 1499,99 $. През януари 2026 NVIDIA отрече слухове за край на 5070 Ti; ASUS тогава посочи недостиг на памет. Картата все още е налична, така че спиране на производството не е доказано — но ценовата спирала след 5090 и 5080 продължава при 5070 Ti.", "_src": "d18a0453"}, "2026-11-06-asus-xg-core-9060xt": {"titel": "ASUS XG Core: външна Radeon RX 9060 XT LP 16 GB през USB4 за лаптопи и хендхелди", "schlagzeile": "ASUS XG Core: външна RX 9060 XT LP 16 GB през USB4", "kurz": "ASUS представя XG Core: компактна външна графична кутия с Radeon RX 9060 XT LP 16 GB GDDR6 и USB4 за съвместими лаптопи, мини PC и хендхелди като ROG Ally X. Без официална цена; шведски магазин сочи около 1207 € с ДДС според TechPowerUp.", "zusammenfassung": "В прессъобщение, публикувано от TechPowerUp, ASUS обявява XG Core: външна графична единица с AMD Radeon RX 9060 XT LP (RDNA 4) и 16 GB GDDR6. Кутията е около 144 × 117 × 39 mm и се свързва през USB4 със съвместими хостове — ASUS споменава и Thunderbolt 3, както и ROG Ally X и ROG Xbox Ally X. HDMI и DisplayPort са вградени; настройката е през GPU Tweak III. ASUS цели игри, творчество и локални AI натоварвания (напр. ComfyUI, LM Studio, Ollama). Липсва официална MSRP; коментари в TechPowerUp цитират шведски магазин за около 1346 $ / 1207 € с 25% ДДС — не е потвърдена MSRP. Наличността в DE/AT остава неясна.", "_src": "e27a1951"}, "2026-11-06-medusa-point-6-8-kerne": {"titel": "Още Zen 6 Medusa Point семпли: 6 и 8 ядра в Geekbench записи на Lenovo", "schlagzeile": "Изтичане: Medusa Point 2/3 с 6 и 8 ядра се появява при Lenovo", "kurz": "След 10-ядрения семпъл в Geekbench 7 уж са се появили още два инженерни семпъла AMD Zen 6 Medusa Point: 8 ядра (2+6) и 6 ядра (1+5), и двата като Medusa Point 2/3 на системи Lenovo. Непотвърдено; тактове и резултати силно се люлеят.", "zusammenfassung": "VideoCardz съобщава за още два Geekbench 7 записа за AMD Zen 6 Medusa Point, този път с 6 и 8 ядра и етикет Medusa Point 2/3. И двата семпъла са тествани на системи Lenovo. 8-ядреният (100-000002152-50_Y) има 16 нишки в клъстери 2+6 и 8 MB L3; 6-ядреният (100-000001658-50_Y) 12 нишки в 1+5 и 4 MB L3. И двата споделят ID Family 26 Model 224 Stepping 0, за разлика от 10-ядрения Medusa Point 1. Резултати Geekbench 7: 8C по-късен рун 2889 / 15099 (макс. 5,28 GHz), по-ранен много по-слаб; 6C 1732 / 8340 при само ~2,04 GHz. VideoCardz подчертава, че тактове и резултати при инженерни семпли силно варират и не са финални. Мобилен дебют на Zen 6 се очаква около CES 2027. AMD не е потвърдила семплите.", "zuverlaessigkeit_hinweis": "Непотвърдено: Geekbench 7 записи на инженерни семпли на системи Lenovo, според VideoCardz. Тактове и резултати силно се различават между рунове. Не е финален продукт; AMD не е потвърдила.", "_src": "66dba83d"}, "2026-11-06-windows11-27h2": {"titel": "Windows 11 27H2 трябва за пръв път от три години да обнови техническата основа", "schlagzeile": "Windows 11 27H2: истински платформен ъпдейт, не само UI", "kurz": "Dr. Windows съобщава, цитирайки The Verge: версия 27H2 през 2027 трябва да обнови ядрото и модела на драйверите на Windows 11 — първа промяна от 24H2/25H2/26H2, които са технически еднакви. Според докладите Windows 12 не е планиран за 2027.", "zusammenfassung": "Според Dr. Windows (с позоваване на The Verge) Windows 11 през 2027 ще получи платформен ъпдейт с версия 27H2. От 24H2 насам 25H2 и 26H2 са еднакви на техническо ниво (ядро, модел на драйвери и базови елементи); новостите са засягали главно UI и сменяеми компоненти. 27H2 трябва да промени тази основа за пръв път от три години. Това може да изисква тестове за съвместимост, особено при системен софтуер като решения за сигурност. Дали някои функции ще бъдат изкуствено вързани към 27H2, остава отворено. Докладите подчертават и че това не обявява Windows 12 за 2027; остава Windows 11. Новината по същество потвърждава планове, вече очертани от Microsoft. The Verge е зад paywall; ядрото се потвърждава през Dr. Windows и Golem («без Windows 12»).", "weitere_links": ["Golem.de: Im nächsten Jahr kommt wohl kein Windows 12"], "_src": "76b75cda"}, "2026-11-06-msi-claw-fsr41": {"titel": "MSI иска FSR 4.1 за Claw A8 през декември чрез драйвер на производителя", "schlagzeile": "MSI Claw A8: FSR 4.1 се очаква през декември с OEM драйвер", "kurz": "MSI потвърждава, че Claw A8 (Ryzen Z2 Extreme / Radeon 890M) трябва да получи AMD FSR Upscaling 4.1 чрез собствен графичен драйвер — цел декември 2026, при успешна валидация. Текущ драйвер оправя бъгове в рендера, но още няма FSR 4.1.", "zusammenfassung": "VideoCardz съобщава с позоваване на MSI: хендхелдът Claw A8 трябва да получи AMD FSR Upscaling 4.1 чрез графичен драйвер на производителя. MSI цели декември 2026, ако валидацията мине. Claw A8 ползва Ryzen Z2 Extreme с Radeon 890M. AMD отвори FSR 4.1 за Ryzen Z2 Extreme и други handheld APU на 20 октомври; стандартните Adrenalin драйвери официално не поддържат хендхелди, затова MSI, ASUS или Lenovo трябва да разпространяват свои. Драйвер 32.0.32016.5 за Claw A8 BZ2EM вече е наличен: оправя грешни сенки, светлинни глитчове, FSR артефакти, частици и черни квадрати — но още без FSR 4.1. Това потвърждава официален път вместо неофициални модифицирани драйвери.", "_src": "fa2c559e"}, "2026-11-06-nvidia-dlss-override-19": {"titel": "NVIDIA App: DLSS Override за още 19 игри, включително Witcher 3 и PUBG", "schlagzeile": "NVIDIA App: DLSS Override за още 19 игри е отключен", "kurz": "Актуализация на NVIDIA App добавя DLSS Override профили за още 19 заглавия. Сред тях са по-стари игри като The Witcher 3 и PUBG както и предстоящи или обявени издания. Override позволява принудително ползване на по-нови DLSS модели и режими, където драйверът го поддържа.", "zusammenfassung": "TechPowerUp съобщава за NVIDIA App актуализация 11.0.9.585 с поддръжка на DLSS Override за още 19 игри и Optimal Settings профили за шест заглавия. В списъка Override са сред другите Honeycomb: The World Beyond, WARDOGS, PUBG: Battlegrounds, Aniimo, 007 First Light, Active Matter, Enlisted, Dragon's Dogma 2, The Witcher 3: Wild Hunt, AION 2, Halloween: The Game, HOT WHEELS Infinite Rush, Silent Hill: Townfall, Control Resonant, Ace Combat 8: Wings of Theve, Dynasty Warriors 3 Complete Edition Remastered, Star Wars: Galactic Racer, Gears of War: E-Day и Clive Barker's Hellraiser: Revival. Optimal Settings идват сред другите за AION 2, Aniimo, Control Resonant, EA Sports FC 27, Gears of War: E-Day и Star Wars: Galactic Racer. Някои заглавия вече са били в по-ранни builds според TechPowerUp; NVIDIA не обяснява дублиранията и не казва кои override опции получава всяка игра. DLSS Override е в настройките на графичната програма и може да принуждава по-нови DLSS модели или режими като DLAA, ако играта не ги предлага. Changelog-ът иначе споменава само общи поправки за стабилност и сигурност.", "weitere_links": ["VideoCardz: 19 DLSS Override профила"], "_src": "df35ce8c"}, "2026-11-06-unity-buyout-gespraeche": {"titel": "Доклади: Silver Lake и саудитският PIF са водили предварителни разговори за покупка на Unity", "schlagzeile": "Изтичане: Silver Lake и PIF говорили за покупка на Unity", "kurz": "Според доклад на Reuters Silver Lake и саудитският Public Investment Fund след сделката за EA са водили предварителни разговори за придобиване на Unity. Вторични доклади споменават оценки около около 25 милиарда долара. Сделка не е гарантирана; акциите скочиха от слуховете.", "zusammenfassung": "Няколко медии, цитирайки Reuters, съобщават, че Silver Lake и саудитският Public Investment Fund са водили предварителни разговори за възможна покупка на Unity. Същите участници наскоро бяха в голямата сделка за EA; Silver Lake вече имало миноритарен дял в Unity. Insider Gaming посочва оценка от порядъка на около 25 милиарда долара и пише, че Unity разглежда опции с банка. Това са изрично ранни разговори; сделка не е гарантирана. Само слуховете са вдигнали акциите осезаемо; един доклад говори за почти 15 процента. Unity е известна най-вече с едноименния engine и стои зад много големи игри. Ситуацията остава непотвърдена, докато Unity или инвеститорите не се произнесат официално. Надеждност: средна заради произход Reuters, но предварителен характер.", "zuverlaessigkeit_hinweis": "Непотвърдено: доклад на Reuters за предварителни разговори, поет от PC Gamer, Insider Gaming и IGN. Няма приключена сделка; Unity разглежда опции с банка. Цифри и изход отворени.", "ursprungsquelle": "Reuters", "weitere_links": ["Insider Gaming: Silver Lake и PIF искали Unity", "IGN: Silver Lake и PIF търсели да купят Unity"], "_src": "f1589ccc"}, "2026-11-06-amd-pc-markt-2027": {"titel": "AMD планира за 2027 двуцифрен спад на доставките на PC заради високи цени на паметта", "schlagzeile": "AMD: PC пазарът да спадне двуцифрено през 2027 – RAM тежи", "kurz": "На earnings call Лиса Су каза, че AMD планира двуцифрен спад на световните PC единици през 2027. Причината били по-високи цени на памет и компоненти, които тежат на търсенето. Това е планово допускане за целия пазар, не вече измерен спад.", "zusammenfassung": "На earnings call за третото тримесечие на 2026 CEO-то на AMD Лиса Су заяви, че компанията планира спад на единиците на PC пазара с двуцифрен процент през 2027. Като причина посочва по-високи разходи за памет и компоненти, които оскъпяват десктопи и лаптопи и тежат на търсенето. AMD ще изравни sell-in със sell-through, за да държи запасите здрави. Въпреки очакваната слабост AMD иска да се представи по-добре от пазара чрез Ryzen roadmap и растящия търговски бизнес. Успоредно AMD очаква Data Center да надхвърли 80 процента от приходите през 2027. Client нарасна със 7 процента през Q3 до 2,9 милиарда долара; Gaming падна с 40 процента до 773 милиона, главно заради по-слаби semi-custom продажби в конзолния цикъл. PCGH подчертава, че това е планово допускане, не вече измерен пазарен резултат. VideoCardz отразява същите изказвания. Цените на RAM почти не се появяват в Google Trends DE, но новината остава важна за купувачите на хардуер.", "weitere_links": ["VideoCardz: AMD очаква двуцифрен спад на PC пазара през 2027"], "_src": "093d57bb"}, "2026-11-06-rx9070xt-clustered-geometry": {"titel": "Microsoft Agility SDK: най-голямата актуализация на DirectX Raytracing от 2018 – Clustered Geometry и PTLAS", "schlagzeile": "DirectX: най-голямата raytracing актуализация от 2018 – Clustered Geometry", "kurz": "С Agility SDK 1.722 Preview Microsoft публикува най-обширното разширение на DirectX Raytracing от 2018. Clustered Geometry и Partitioned TLAS трябва да ускорят изграждането на структури и да намалят паметта. В независими измервания на PCGH RX 9070 XT расте от 1,7 до 91 fps; игрите трябва да внедрят API-тата.", "zusammenfassung": "Microsoft нарича новите DirectX Raytracing функции в Agility SDK 1.722 Preview най-обширното разширение от въвеждането на DXR през 2018. Ключови точки са Clustered Geometry (CLAS), Partitioned Top-Level Acceleration Structures (PTLAS) и индиректни builds на acceleration structures. Clustered Geometry разделя геометрията на преизползваеми клъстери до 256 триъгълника; това трябва силно да ускори изграждането в детайлни, динамични сцени и да позволи по-точни отражения и сенки без скъпа proxy геометрия. PTLAS трябва да обновява само променените области. Според ComputerBase и Microsoft в пример с Radeon RX 9070 кадрите са нараснали от 1,2 до 79 fps, а паметта за структури е паднала от около 7519 на 774 MB; scratch паметта е нараснала силно. PC Games Hardware независимо измери и демото D3D12RaytracingClusteredGeometry: RX 9070 XT от 1,7 до 91 fps при 1600×920 (около 54×), BVH памет от 7518 на 771 MiB; RTX 5080 от 1,4 до 310 fps. Без Clustered Geometry Radeon леко водеше; с функцията RTX 5080 беше ясно по-бърза. Preview работи на GeForce RTX, Radeon RX 9000, Intel Arc B-серия и поддържани Core Ultra iGPU; нов хардуер не е нужен, но драйверна поддръжка е. Съществуващите игри не печелят автоматично: студията трябва да интегрират API-тата. Advanced Shader Delivery и други функции от Agility SDK 1.620 са част от същия пакет, но не от числата на raytracing демото.", "weitere_links": ["Microsoft DirectX Blog: Agility SDK 1.620 / 1.722 Preview", "Microsoft: Преглед на Clustered Geometry и PTLAS", "PCGH: RX 9070 XT / RTX 5080 в демото Clustered Geometry"], "_src": "3d54cb6e"}, "2026-11-05-asrock-rx7900-vbios": {"titel": "ASRock VBIOS за RX 7900 XT/XTX: собственици докладват brick-нати GPU след официалната актуализация", "schlagzeile": "ASRock VBIOS brick-ва RX 7900 XT/XTX – свалянията уж са махнати", "kurz": "След официалния ASRock VBIOS от края на октомври собственици на Radeon RX 7900 XT и XTX Phantom Gaming както и Taichi докладват, че картите вече не стартират. Актуализацията трябваше да покрие AMD-SN-6023 и минаваше през ASRVBFlash 1.0.5. HTTP свалянията вече давали 404; някои карти са възстановени само с външен EEPROM програматор.", "zusammenfassung": "В края на октомври ASRock публикува нови VBIOS файлове за десет Radeon RX 7000 карти, включително като част от мярката за сигурност AMD-SN-6023. Няколко собственици съобщават, че след флаш с ASRVBFlash 1.0.5 системата вече не прави POST с инсталиран GPU. Споменават се RX 7900 XT Phantom Gaming както и RX 7900 XTX Phantom Gaming и Taichi, включително White изданието. Проблемът се появява на различни дънни платки, например ASRock и MSI. VideoCardz описва последователността: инструментът проверява съвместимост, Windows се рестартира, след това PC-то не стартира с картата. Поне двама потребители са възстановили RX 7900 XTX Phantom Gaming с външни EEPROM програматори, включително T48 с тестов клипс. Октомврийските сваляния вече отговаряли с HTTP 404, докато FTP връзките частично още работят. Потребител в Япония според Reddit е получил от ASRock Support потвърждение, че повредата ще е покрита от гаранцията; публично фирмено изявление или официална процедура за възстановяване според VideoCardz и Guru3D все още няма. Докато ASRock не изясни и не пусне коригиран фърмуер, собствениците на посочените модели не трябва да инсталират октомврийския фърмуер. Източник: VideoCardz, допълнително Guru3D.", "weitere_links": ["Guru3D: ASRock RX 7000 VBIOS и доклади за brick"], "_src": "1ae75289"}, "2026-11-05-gog-galaxy-linux-2027": {"titel": "Нов GOG Galaxy идва през 2027 – с пълна Linux поддръжка", "schlagzeile": "GOG Galaxy 2027: нов клиент с пълна Linux поддръжка", "kurz": "На първия GOG Showcase GOG потвърди, че през 2027 идва нов Galaxy клиент с пълна Linux поддръжка. Успоредно се преработва клиентът за Windows и Mac. Galaxy остава опционален; офлайн инсталаторите остават.", "zusammenfassung": "GamingOnLinux докладва от първия GOG Showcase: през 2027 трябва да дойде напълно нов GOG Galaxy клиент за всички платформи, за първи път с пълна Linux поддръжка. GOG още през юли е казал на GamingOnLinux, че работи по това; сега срокът е публичен. Според изявлението на GOG клиентът на Windows и Mac трябва да стане по-прост и по-бърз, с по-чиста библиотека. Основното обещание остава: Galaxy е опционален и игрите могат да се свалят и пазят през офлайн инсталатори. Заинтересованите могат да се запишат за бета на годишнишната страница на GOG, когато отвори. GOG работи и по GOG Social, модернизирана общност с нишки, медии и тагове по игри. Докладът не дава повече детайли за Linux клиента; тук не се спекулира.", "_src": "aa4b3b79"}, "2026-11-05-medusa-point-gb7": {"titel": "AMD Zen 6 Medusa Point се появява в Geekbench 7: 10 ядра, single-core над средното на 9950X3D", "schlagzeile": "Изтичане: Medusa Point в Geekbench 7 – ES 10C бие 9950X3D в SC?", "kurz": "Непотвърден резултат от Geekbench 7 показва инженерен образец AMD Medusa Point с 10 ядра и 20 нишки. Single-core е 3100 точки, малко над средното на Ryzen 9 9950X3D. Докладваните честоти около 2,0 GHz изглеждат неправдоподобни за краен продукт.", "zusammenfassung": "VideoCardz и TechPowerUp съобщават за Geekbench 7 запис на инженерния образец 100-000001713-32_Y на платформа Lenovo. Показва 10 ядра и 20 нишки в два клъстера от 4 плюс 6 ядра, плюс 16 MB L3. Single-core е 3100 точки, около 1,6 процента над средното на Ryzen 9 9950X3D от 3051 според VideoCardz. Multi-core достига 18313. База и максимум са около 2,0 GHz / 1996 MHz; това изглежда невероятно за retail честоти и се третира като типичен ES или грешен отчет. TechPowerUp описва клъстерите като възможна смес Zen 6 и Zen 6c и споменава AVX-512 в листинга. Това не е краен продукт; спецификации, честоти и дата остават отворени. По-ранни Geekbench 6 резултати не са пряко сравними. Надеждност: средна, защото има само публичен листинг през leak канали.", "zuverlaessigkeit_hinweis": "Непотвърдено: Geekbench 7 листинг на инженерен образец (100-000001713-32_Y) на платформа Lenovo, докладван от VideoCardz и TechPowerUp чрез HXL. Честотите изглеждат неправдоподобни (около 2,0 GHz). Не е краен продукт; AMD не е потвърдила нищо.", "ursprungsquelle": "Geekbench чрез HXL", "weitere_links": ["TechPowerUp: Medusa Point 10C/20T в Geekbench"], "_src": "ba3c17d9"}, "2026-11-05-switch2-keine-preiserhoehung": {"titel": "Nintendo изключва ново повишение на цената на Switch 2 – въпреки по-слаби продажби на конзоли", "schlagzeile": "Nintendo: не планира ново повишение на цената на Switch 2", "kurz": "Президентът на Nintendo Шунтаро Фурукава изключва нови повишения на цената на Switch 2. Компанията се вижда достатъчно снабдена с чипове памет. В същото време медиите докладват спад на продажбите на конзоли и на печалбата в последното тримесечие.", "zusammenfassung": "При представяне на последните резултати президентът на Nintendo Шунтаро Фурукава според PC Games, Eurogamer, VGC и IGN заяви, че не се планира ново повишение на цената на Switch 2. Nintendo е осигурила достатъчен капацитет на памет и в момента не вижда причина за нова корекция. Nintendo вече е повишавала цените на Switch 2 по-рано, включително с 50 долара / 30 евро в няколко региона. IGN цитира Bloomberg със спад на оперативната печалба от 16 процента до 73,9 милиарда йени в тримесечието до края на септември и 2,67 милиона продадени Switch 2 в този период. VGC говори за около 37-процентов спад на продажбите на Switch 2 в същия контекст, докато Nintendo твърди, че Switch 2 все още се продава по-добре от предшественика в сравнителния прозорец. До края на септември общо са продадени около 26 милиона Switch 2. Nintendo запазва прогнозите за текущата фискална година според PC Games. Недостигът на памет остава тема в бранша; Nintendo се позиционира различно от скорошните повишения на PS5 и Xbox.", "weitere_links": ["IGN: Nintendo изключва нови повишения на цената на Switch 2", "Eurogamer: No plans for more Switch 2 price hikes", "VGC: Nintendo not considering Switch 2 price hike"], "_src": "487162c1"}, "2026-11-05-dlss5-hogwarts-legacy": {"titel": "Hogwarts Legacy получава DLSS 5 с 3D-Guided Neural Rendering на GeForce RTX 50", "schlagzeile": "DLSS 5 Neural Rendering вече в Hogwarts Legacy", "kurz": "От 5 ноември 2026 Hogwarts Legacy на PC поддържа NVIDIA DLSS 5 с 3D-Guided Neural Rendering. Функцията изисква GeForce RTX 50 и актуален Game Ready драйвер; в Display настройките има превключвател „Neural Rendering“. Маркетинговите FPS числа не са ежедневно обещание.", "zusammenfassung": "NVIDIA и Portkey Games съобщават, че Hogwarts Legacy на PC е получил DLSS 5 с 3D-Guided Neural Rendering. Техниката трябва да обогатява осветлението и детайлите на материалите с AI, като запазва геометрията и текстурите на енджина като основа; разработчиците могат да управляват резултата чрез Artist Controls. Изискване според support статията: GeForce RTX 50 Series и GeForce Game Ready Driver 616.64 или по-нов. Активиране под Display настройки: Upscale Type на NVIDIA DLSS, после включване на Neural Rendering; пряк път Shift+Alt+B. Поддържани магазини: Steam, Epic Games Store и Windows Store. Според NVIDIA блога от 5 ноември 2026 War Thunder следва с DLSS 5 в средата на ноември, Where Winds Meet на 23 ноември. Функцията е обвързана с RTX 50 или съвместими cloud/Spark пътища и сама не замества класическото upscaling. Не приемаме FPS маркетинг от демота като практическо обещание.", "weitere_links": ["Portkey Games: активиране на DLSS 5 в Hogwarts Legacy", "NVIDIA Blog: GFN Thursday Hogwarts DLSS 5"], "_src": "beddaa04"}, "2026-11-05-xbox-pc-app-60": {"titel": "Xbox PC приложение: Microsoft обещава до 60 процента по-бърз старт за Insiders", "schlagzeile": "Xbox PC приложението стартира до 60 % по-бързо – първо за Insiders", "kurz": "Xbox Insiders могат от 05.11.2026 да тестват преработено Xbox PC приложение. Microsoft говори за до 60 процента по-бърз старт и забележимо по-пъргави страници и прозорци. Паралелно обновено уеб и cloud gaming изживяване достига до още играчи.", "zusammenfassung": "Jason Beaumont, VP Xbox Experiences, обяви на 05.11.2026 в Xbox Wire по-бързо и по-ясно Xbox изживяване за PC, уеб и облак. Xbox Insiders трябва да могат веднага да ползват актуализираното Xbox PC приложение. Според тестове на Microsoft приложението стартира до 60 процента по-бързо; страници като Home, Store и Game Pass се зареждат до 50 процента по-бързо, а прозорците в приложението се отварят до 65 процента по-бързо. Стойностите зависят от устройството, мрежата, конфигурацията и използването, според бележката. Библиотеката получава по-проста навигация, нови филтри и по-добро сортиране. Приятели и социални функции влизат в основната навигация. Търсенето покрива игри, включително инсталирани заглавия и add-ons, както и хора. Визуално има преработени карти на игри, Home, настройки и анимации. Уеб изживяването за Xbox Cloud Gaming, вече показано на Insiders, трябва в идните седмици автоматично да достигне до повече играчи; който иска да тества по-рано, може да отвори play.xbox.com. Там има раздел Library за облачни игри (закупени и Game Pass), десктоп режим за по-големи екрани, както и тъмен/светъл режим и пет high-contrast теми. Подобно обновяване започва и при облачни приложения на поддържани телевизори и VR слушалки. Който още не е Insider, може да се присъедини през Xbox Insider Hub за Series X|S, Xbox One или Windows. The Verge, Neowin и IGN отразяват обявата.", "weitere_links": ["The Verge: редизайн на Xbox PC приложението", "IGN: Xbox PC приложението 60 % по-бързо според Microsoft", "Neowin: редизайн и по-бързи стартове"], "_src": "f708d215"}, "2026-11-05-nova-lake-h-foto": {"titel": "Изтичане: снимка уж показва непубликуван Intel Nova Lake-H package с multi-tile дизайн", "schlagzeile": "Изтичане: показва ли вече тази снимка Nova Lake-H на Intel с 16 ядра?", "kurz": "Снимка, споделена от momomo_us, уж показва още непубликуван Intel процесорен package с няколко видими силициеви tile-а. Jaykihn потвърди при запитване Nova Lake-H конфигурация с 4+8+4 ядра. Intel не е потвърдил нищо; произходът на изображението остава неясен.", "zusammenfassung": "Хардуерният лийкър momomo_us (188号) сподели на 05.11.2026 в X изрязана снимка, която според VideoCardz уж показва още непубликуван Intel процесорен package с няколко видими силициеви tile-а. VideoCardz не успя да проследи индустриалния или embedded-дънния произход на изображението; видим е само package-ът. На въпроса дали става дума за Nova Lake-H с конфигурация 4+8+4, лийкърът Jaykihn отговори „Yes“. В ъпдейт momomo_us според VideoCardz посочи 16 CPU ядра, 4 Xe GPU ядра и 18 MB кеш. Този брой ядра пасва на коментирания Core Ultra 9 4970H с 4+8+4, т.е. 16 CPU ядра. В таблицата на VideoCardz обаче коментираният 4970H е с 12 Xe3P графични ядра – това се разминава с цифрата „4 Xe“ на momomo; коя GPU цифра е вярна, остава отворено. Дали сниманият екземпляр е конкретно 4970H, остава неясно; VideoCardz не споменава тактови честоти. За сравнение няколко Panther Lake-H модела също ползват 4+8+4. TechPowerUp и Wccftech отразяват изтичането. Intel не е потвърдил данните.", "zuverlaessigkeit_hinweis": "Непотвърдено: снимка от лийкъра momomo_us (@momomo_us / 188号); Jaykihn отговори „Yes“ на запитването за конфигурацията 4+8+4. VideoCardz не успя да проследи произхода на изрязаното изображение. Intel не е потвърдил нищо; тактовите честоти са неизвестни.", "ursprungsquelle": "momomo_us (@momomo_us) в X", "weitere_links": ["TechPowerUp: SoC Nova Lake-H се появява", "Wccftech: Nova Lake-H с six-tile setup"], "_src": "86f9c2aa"}, "2026-11-05-gta6-39-screenshots": {"titel": "Rockstar публикува около 39 нови официални скрийншота на GTA 6 – две седмици до старта в САЩ", "schlagzeile": "GTA 6: Rockstar показва 39 нови скрийншота – две седмици до launch", "kurz": "Rockstar Games публикува около 39 нови официални скрийншота на Grand Theft Auto VI. Поводът е отброяването: в САЩ остават около две седмици до старта на 19.11.2026. Изображенията включват сцени от Vice City / Leonida както и Jason и Lucia.", "zusammenfassung": "Rockstar Games официално пусна голям пакет нови скрийншоти на Grand Theft Auto VI. IGN и други медии говорят за 39 нови изображения за отбелязване на последните две седмици преди старта в САЩ. Американската дата 19.11.2026 се цитира като ориентир. Според IGN, IGN Германия и PC Gamer сред мотивите има сцени от Vice City / Leonida, героите Jason и Lucia, моменти на crime и nightlife, както и детайли като танцьори, бойни кучета и много детайлни пори на кожата. Скрийншотите идват от Rockstar / официалния сайт и X канала на Rockstar; това са потвърдени маркетингови изображения, не изтичания. Нищо отвъд описаното от източниците не се спекулира тук. Google Trends DE дава на GTA 6 стойност 60 като най-висока сред сравнените термини за седем дни; AT е 41.", "weitere_links": ["IGN Германия: 39 нови скрийншота на GTA 6", "PC Gamer: launch скрийншоти с танцьори, кучета и пори", "Rockstar Games (официален сайт)"], "_src": "eb8f6ed6"}, "2026-11-05-discord-native-windows": {"titel": "Discord преизгражда Windows клиента на Rust: ранен build с около 290 MB RAM вместо гигабайти Electron", "schlagzeile": "Discord напуска Electron: Rust клиентът цели край на апетита за RAM", "kurz": "Discord иска да премести Windows desktop клиента от Electron към нативно Rust приложение с GPUI. Ранен build на име Discord Phoenix показва около 290 MB RAM на скрийншот на CTO. Настоящото Electron приложение според доклади може да стигне до диапазона 4 GB.", "zusammenfassung": "CTO на Discord Станислав Вишневски обяви, че Discord изоставя Electron за desktop приложение на Rust с GPUI. ComputerBase и Windows Latest отразяват новината. Ранен Windows 11 скрийншот изброява Discord Phoenix с 290,2 MB RAM. Windows Latest припомня, че самият Discord е тествал рестарт на клиента при надхвърляне на 4 GB, и че нормалната употреба често е под 1 GB, докато idle лесно стига 1 до 2 GB. Discord вече ползва Rust за инфраструктура, глас и части от настоящия клиент; сега трябва да последва целият клиент. Кога започват тестовете или публичният rollout остава отворено. Стъпката пасва на дневния ред за ефективност на Windows 11 на Microsoft. Остава да се види дали паритет на функции и стабилност ще стигнат Electron версията.", "weitere_links": ["Windows Latest: Electron вън, Rust build с ~290 MB"], "_src": "5da0f5ef"}, "2026-11-05-fsr-412-xbox": {"titel": "AMD FSR Upscaling 4.1.2 е налично за разработчици на Xbox Series X|S в GDK от октомври 2026", "schlagzeile": "FSR 4.1.2 идва на Xbox – за пръв път с AI ъпскейлинг", "kurz": "С Microsoft GDK от октомври 2026 разработчиците могат да ползват AMD FSR Upscaling 4.1.2 на Xbox Series X и S. За пръв път на конзолите има ML-базиран AMD FSR upscaling. Съществуващите игри не го получават автоматично; студията трябва да интегрират.", "zusammenfassung": "AMD съобщи в GPUOpen, че FSR Upscaling 4.1.2 е налично за Xbox Series X|S чрез Microsoft Game Development Kit от октомври 2026. Alexander Blake-Davies пише, че така за пръв път на Xbox конзолите пристига ML-базиран AMD FSR upscaling; преди там е имало само аналитичен FSR. За Series X и Series S има два INT8 модела: Full и нов Lite. Според AMD Lite е с по-малко от половината размер и облекчава GPU-то повече. И двата работят на Series X и Series S. Паметта на upscaler-а зависи от render и изходната резолюция, не от модела – изборът е следователно компромис за производителност, не за памет. API-то съответства на FSR SDK под Windows; режимите за качество са Native AA, Quality, Balanced, Performance и Ultra Performance. Чрез FSR SDK 2.4 и ASUS preview драйвер техниката важи и за ROG Xbox Ally handhelds (първо Ally X и X20). Става дума за достъп за разработчици: студията трябва да интегрират, няма автоматични ъпдейти за съществуващи игри, а AMD не е посочила конкретни заглавия. VideoCardz, PC Gamer и TechPowerUp докладват за това.", "weitere_links": ["VideoCardz: FSR 4.1.2 с ML на Series X|S", "PC Gamer: FSR 4.1.2 на Xbox и handhelds", "TechPowerUp: FSR Upscaling 4.1.2 за Xbox"], "_src": "71d4e824"}, "2026-11-05-geforce-8800-gtx-demo": {"titel": "Безплатно Steam демо „GeForce 8800 GTX – 20 Years of a Legend“ чества 20 години CUDA GPU", "schlagzeile": "Nvidia те оставя да разопаковаш 8800 GTX – но иска RTX 4070", "kurz": "От 05.11.2026 в Steam има безплатното демо „GeForce 8800 GTX – 20 Years of a Legend“. То позволява да разопаковаш картата от 2006 и да я вградиш в тогавашен PC – рендерирано с path tracing и DLSS 4.5. Минимум се изисква RTX 4070.", "zusammenfassung": "По повод около 20-годишнината на GeForce 8800 GTX (пазарен старт на 08.11.2006) на 05.11.2026 излезе безплатното Steam демо „GeForce 8800 GTX – 20 Years of a Legend“. Създал го е Unreal Engine художникът Dylan Browne с подкрепа от NVIDIA. Полуинтерактивното демо позволява да разопаковаш картата, да я вградиш в PC от епохата и да разгледаш гейминг стая от 2006 с Easter eggs. Технически ползва path tracing, DLSS 4.5 с Ray Reconstruction и Dynamic Multi Frame Generation, както и RTX Mega Geometry. Системните изисквания в Steam посочват като минимум RTX 4070, 32 GB RAM, 30 GB място и драйвер 621.12 или по-нов; препоръчва се RTX 5080. 8800 GTX се смяташе за първата CUDA-съвместима GPU. Версия за GeForce NOW Ultimate трябва скоро да последва според доклади от eTeknix и The Verge. VideoCardz и Wccftech също отразяват акцията.", "weitere_links": ["eTeknix: Steam демо за 20-годишнината", "The Verge: демо за разопаковане на 8800 GTX", "VideoCardz: unboxing играта изисква RTX 4070", "Wccftech: GeForce 8800 GTX става на 20"], "_src": "16d23a91"}, "2026-11-05-openssh-musl-bypass": {"titel": "OpenSSH и musl: дълги пароли могат да разбият акаунти без парола – поправка в 10.6p2", "schlagzeile": "Дупка в OpenSSH: дълги пароли отварят заключени логини (musl)", "kurz": "На някои Linux системи с musl и без PAM нападатели могат да разбият акаунти без hash на парола с много дълга парола. OpenSSH 10.6p2 и актуализирани Alpine пакети затварят дупката; след това sshd трябва да се рестартира. Дотогава помага PasswordAuthentication no.", "zusammenfassung": "OpenSSH и Alpine Linux предупреждават за тежка, но нишова дупка в OpenSSH без PAM на системи на база musl. Според Alpine и heise засегнат е преди всичко Alpine пакетът openssh-server (без PAM) или openssh-server-pam с UsePAM no. Ако нападател достигне SSH порта и PasswordAuthentication е активен, може да влезе без да знае парола – ако поне един акаунт има „*“ в shadow полето (типично само с ключ) и едновременно поне един локален акаунт има $5$ или $6$ hash. Атаката изпраща много дълга парола от 257 до 1024 байта: musl-crypt() връща „*“ като грешна стойност за ключове над 256 байта, което съвпада със записаното „*“ и пуска проверката. Към момента на advisories още не е бил даден CVE. Поправката е в OpenSSH 10.6p2; Alpine е публикувал актуализирани пакети. След ъпгрейда sshd трябва да се рестартира. Workaround: задайте PasswordAuthentication no и рестартирайте sshd. OpenSSH разработчикът Damien Miller съветва веднага да се изключат логините с парола. Според heise проектът приема, че бъгът по-скоро не възниква в самия OpenSSH, но 10.6p2 го смекчава. Сигналът е от Özgün Kültekin от Wakefield; BleepingComputer и Alpine описват условията подробно.", "weitere_links": ["heise: OpenSSH и Alpine предупреждават за дупка", "BleepingComputer: дупка при акаунти заключени с парола"], "_src": "beadd996"}, "2026-11-04-gta6-vorbestellungen-750-mio": {"titel": "GTA 6: Sensor Tower оценява приходите от предварителни поръчки на над 750 милиона долара", "schlagzeile": "Анализатори: GTA 6 печели над 750 млн. долара още преди премиерата", "kurz": "Според оценка на анализаторската компания Sensor Tower до 03.11.2026 GTA 6 е бил предварително поръчан около 7,7 милиона пъти. Това се равнява на около 751 милиона долара приходи за PS5 и Xbox. Rockstar и Take-Two не са дали официални данни по темата.", "zusammenfassung": "Според IGN анализаторската компания Sensor Tower е проучила предварителните поръчки на Grand Theft Auto VI. До 03.11.2026 по оценка са поръчани 7,71 милиона копия, което се равнява на около 751 милиона долара приходи. По-голямата част идва от PlayStation 5: Sensor Tower отчита там около 74 процента от поръчките и около 559 милиона долара, а при Xbox около 26 процента и около 192 милиона долара. Ultimate Edition струва 100 долара, а стандартната версия 80 долара. Според IGN шефът на Take-Two Строс Зелник вижда в предварителните поръчки най-вече най-верните фенове. За сравнение: според IGN през 2013 г. GTA 5 е спечелила 800 милиона долара в първите 24 часа и е минала милиард след три дни. Дали GTA 6 ще счупи този рекорд, ще стане ясно чак след премиерата. Важно: става дума за оценка на фирма за пазарни проучвания, а не за данни от Rockstar или Take-Two. GTA 6 излиза на 19.11.2026 за PS5 и Xbox Series X|S, а версия за PC все още не е обявена.", "_src": "e55d6220"}, "2026-11-04-windows-paint-luecke": {"titel": "Windows 11: Уязвимост в Paint (CVE-2026-83844) – поправената версия не стига до много потребители", "schlagzeile": "Пробив в Paint на Windows: поправката я има, но не стига до много хора", "kurz": "Приложението Paint в Windows 11 има уязвимост, която нападатели биха могли да използват за отдалечено изпълнение на код. Microsoft вече разпространи поправка чрез Microsoft Store на 13.10.2026. Според съобщения обаче на много потребители и администратори поправената версия изобщо не се предлага.", "zusammenfassung": "Microsoft води уязвимостта в Paint под номер CVE-2026-83844 и я оценява с 8,1 от 10 точки. Самата Microsoft я класифицира като „Важна“, т.е. едно ниво под „Критична“. Става дума за четене извън разрешената област на паметта, което в най-лошия случай позволява изпълнение на зловреден код през мрежата, без потребителят да трябва да щраква каквото и да е. Според Microsoft обаче атаката е трудна за осъществяване и досега не са известни реални атаки. Тъй като Paint се обновява чрез Microsoft Store, обичайното обновяване на Windows само по себе си не защитава от уязвимостта. Според Windows Latest Paint се счита за безопасен от версия 11.2609.401.0, но тази версия не се появяваше в Store дори при включени автоматични обновявания. Администратори в Reddit и във форума на Microsoft също съобщават, че не получават посочената версия. Според Neowin страницата за сигурност на Microsoft първоначално е посочвала друг номер на версия, вероятно поради печатна грешка. Според Neowin е възможно и поетапно разпространение. Инсталираната версия може да се провери в PowerShell с командата „Get-AppxPackage Microsoft.Paint“. Който не използва Paint, може засега и да деинсталира приложението.", "weitere_links": ["Windows Latest: уязвимост в Paint и липсващо обновяване", "Microsoft Security Update Guide: CVE-2026-83844"], "_src": "2d5490bd"}, "2026-11-04-nova-lake-90-grad-limit": {"titel": "Изтичане: Intel Core Ultra 4000 „Nova Lake-S“ щели да работят на най-много 5,1 GHz над 90 °C", "schlagzeile": "Изтичане: Nova Lake на Intel щял да стига само 5,1 GHz над 90 °C", "kurz": "Според информатора Jaykihn всички настолни процесори от серията Nova Lake-S ще ограничават честотата си до най-много 5,1 GHz над 90 °C. Ограничението уж не може да се вдигне. Информацията е предварителна и не е потвърдена от Intel.", "zusammenfassung": "Информаторът за Intel Jaykihn написа на 04.11.2026 в X, че предстоящите настолни процесори Core Ultra 4000 „Nova Lake-S“ на Intel ще получат фиксирана температурна граница. Над 90 °C максималната честота на ядрата щяла да бъде ограничена до 5,1 GHz при всички модели. Това щяло да действа независимо от обичайната аварийна спирачка при 100 °C (TjMax), при която процесорът и без това намалява производителността. Според Jaykihn новата граница от 90 градуса също не може да бъде вдигната. Той самият изрично определя информацията като предварителна. Модели, които и без това не надхвърлят 5,1 GHz, не биха били засегнати. По-бързите модели биха могли да загубят част от буста си, ако охлаждането не е достатъчно. TechPowerUp припомня, че сегашният Core Ultra 9 285K достига до 5,7 GHz и има по-висок TjMax от 105 °C. Освен това според по-ранни съобщения топ моделът с 28 ядра щял за кратко да консумира до 296 W, което вероятно ще изисква мощен охладител. Според TechPowerUp Nova Lake-S се очаква през първото тримесечие на 2027 г. Intel не е потвърдила данните, така че това остава изтичане.", "zuverlaessigkeit_hinweis": "Непотвърдено: единственият източник е информаторът за Intel Jaykihn в X, който сам определя информацията като предварителна. VideoCardz и TechPowerUp предават публикацията. Intel не е потвърдила нищо, окончателните честоти не са известни.", "ursprungsquelle": "Jaykihn (@jaykihn0) в X", "weitere_links": ["Jaykihn в X (оригинална публикация)", "TechPowerUp: Nova Lake-S пада до 5,1 GHz над 90 °C"], "_src": "434bcacb"}, "2026-11-04-god-of-war-laufey-verschoben": {"titel": "God of War Laufey се отлага: новата дата е 20.05.2027", "schlagzeile": "God of War Laufey се отлага: феновете ще чакат три месеца повече", "kurz": "Sony Santa Monica официално отложи God of War Laufey. Вместо на 16.02.2027 играта вече ще излезе на 20.05.2027. Студиото иска да използва допълнителното време за последните щрихи.", "zusammenfassung": "Студиото на PlayStation Santa Monica обяви на 04.11.2026 в X, че God of War Laufey ще излезе по-късно. Досега премиерата беше планирана за 16.02.2027, а новата дата е 20.05.2027. Студиото обяснява отлагането с желанието да довърши играта и да разгърне пълния ѝ потенциал. От представянето през юни екипът е благодарен за огромния ентусиазъм на феновете, се казва в изявлението. Laufey е първата основна част от поредицата, в която главният герой не е Кратос. Вместо това играчите управляват Фей, съпругата на Кратос и майка на Атрей, която умира преди събитията в God of War от 2018 г. Според официалното описание след смъртта си тя се събужда в нещо като отвъдния свят на боговете, наречен „Everywhen“. Eurogamer отбелязва, че така играта избягва претъпкания февруари с много големи заглавия. Студиото планира скоро да сподели още новини.", "weitere_links": ["Eurogamer: God of War Laufey се отлага за май 2027", "Neowin: Sony отлага God of War Laufey"], "_src": "87a1ab5a"}, "2026-11-04-amd-rekord-gaming-einbruch": {"titel": "AMD: рекордни приходи от 13,4 млрд. долара, гейминг с 40 процента надолу – през четвъртото тримесечие вероятно за пръв път повече приходи от Intel", "schlagzeile": "AMD печели повече от всякога, но приходите от гейминг падат с 40 %", "kurz": "AMD постигна рекордни приходи от 13,4 милиарда долара през третото тримесечие на 2026 г., най-вече благодарение на центровете за данни. Приходите от гейминг обаче паднаха с 40 процента, защото скъпата памет спъва видеокартите, конзолите и компютрите. Според собствената си прогноза AMD вероятно за пръв път ще има повече приходи от Intel през четвъртото тримесечие.", "zusammenfassung": "AMD отчете рекордни приходи от 13,4 милиарда долара за третото тримесечие на 2026 г. Според ComputerBase 8,5 милиарда долара от тях идват от бизнеса с центрове за данни, който според TechPowerUp е нараснал с 97 процента на годишна база. В гейминга картината е съвсем различна: това направление се срина с 40 процента спрямо същото тримесечие на миналата година, до 773 милиона долара. Като причина AMD посочва недостига и поскъпването на паметта, които оскъпяват видеокартите, конзолите с чипове на AMD и цели компютри. За четвъртото тримесечие AMD очаква около 17 милиарда долара приходи, с отклонение плюс-минус три процента. Intel очаква за същия период само 15 до 16 милиарда долара. Дори долната граница на прогнозата на AMD е над горната граница на Intel, така че според TechPowerUp AMD за пръв път би имала повече приходи от Intel. Това важи само за приходите, не за печалбата. Същевременно шефката на AMD Лиса Су очаква двуцифрен спад в продажбите на компютри през 2027 г. За геймърите на PC това означава, че AMD продължава да измества фокуса си към центровете за данни и изкуствения интелект.", "weitere_links": ["TechPowerUp: AMD върви към първото си тримесечие с повече приходи от Intel", "PC Games Hardware: тримесечни резултати на AMD"], "_src": "0136260f"}, "2026-11-03-arc-b580-eol": {"titel": "Изтичане: Intel може да спре Arc B580 и да заложи на по-скъпите карти Arc Pro", "schlagzeile": "Изтичане: идва ли краят на бюджетната видеокарта Intel Arc B580?", "kurz": "Според лийкъра Haze2K1 Intel може да спре производството на видеокартата Arc B580. Причината били по-печелившите карти Arc Pro със същия графичен чип. Това е непотвърден слух, Intel не е коментирала.", "zusammenfassung": "Лийкърът Haze2K1 написа на 02.11.2026 в X, че Intel Arc B580 може да бъде спряна. Според публикацията Intel иска да се съсредоточи повече върху професионални карти и карти за работни станции като Arc Pro B50, които се продавали добре за AI приложения. TechPowerUp и Wccftech подхванаха публикацията. Arc B580 излезе през декември 2024 г. за 249 долара като достъпна геймърска карта с 12 GB графична памет. Според TechPowerUp Arc Pro B60 използва същия графичен чип, но има 24 GB памет и струва около 500 долара, което вероятно носи повече печалба на чип. Според TechPowerUp B580 вече е изчерпана при много търговци или се предлага само над първоначалната цена. Самият Haze2K1 се изразява предпазливо и казва само, че картата може да бъде спряна. От слуха не става ясно дали по-малката Arc B570 също би била засегната. Intel не е коментирала слуха, така че той е непотвърден.", "zuverlaessigkeit_hinweis": "Непотвърдено: единственият източник е публикация на лийкъра Haze2K1 в X, който сам казва само „might“ (може би). TechPowerUp и Wccftech преразказват публикацията; няма независим втори източник. Intel не е коментирала.", "ursprungsquelle": "Haze2K1 в X", "weitere_links": ["Haze2K1 в X (оригинална публикация)", "Wccftech: Intel може да спре Arc B580"], "_src": "115ef362"}, "2026-11-03-windows11-8gb-ram": {"titel": "Windows 11 работи осезаемо по-добре на компютри с 8 GB RAM – Microsoft дава подробности и условия", "schlagzeile": "Windows 11 на компютри с 8 GB: обещават до 40% по-бърз мултитаскинг", "kurz": "Microsoft оптимизира Windows 11 за компютри само с 8 GB RAM. Според Microsoft системата реагира до 20 процента по-бързо, а мултитаскингът е до 40 процента по-бърз в лабораторен тест. Нужни са Windows 11 26H2 от компилация 26300.9818 нагоре и обновени приложения.", "zusammenfassung": "На 03.11.2026 Microsoft обясни в Windows Experience Blog как Windows 11 трябва да работи по-добре на компютри с 8 GB RAM. Според шефа на Windows Павън Давулури менюто „Старт“, търсенето, контекстното меню, „Настройки“, Snipping Tool и File Explorer реагират до 20 процента по-бързо на такива устройства, измерено чрез телеметрични данни. До 40 процента по-бързият мултитаскинг идва от един-единствен лабораторен тест на лаптоп на HP със Snapdragon X Plus, а самата Microsoft казва, че това не е общ бенчмарк. Благодарение на по-добре настроената компресия на паметта Windows може да държи до 2 GB повече активни данни в RAM, вместо да ги премества на по-бавния SSD. Така отворените приложения и разделите в браузъра би трябвало по-рядко да се презареждат. Заедно с Edge и приложенията на Microsoft 365 допълнителната употреба на памет при мултитаскинг пада с до 900 MB, като само Word, Excel, PowerPoint и Outlook спестяват около 360 MB. На компютри с 8 GB уиджетите се зареждат едва когато отворите панела с уиджети, което спестява около 200 MB. Изискването е Windows 11 26H2 от компилация 26300.9818 нагоре, която идва първо с незадължителната актуализация от 28.10.2026, а според Windows Latest за всички на Patch Tuesday на 10.11.2026. Edge, Microsoft 365 и Teams също трябва да са обновени, защото част от подобренията идват с обновления на приложенията. За 3D моделиране, тежък видеомонтаж или големи обеми данни Microsoft продължава да препоръчва 16 GB или повече.", "weitere_links": ["Windows Experience Blog (Microsoft): Raising the bar for 8 GB Windows 11 PCs", "TechPowerUp: до 40% по-бърз мултитаскинг на компютри с 8 GB"], "_src": "dd699a8a"}, "2026-11-03-rtx50-preise-china": {"titel": "Изтичане: партньорите вдигат в Китай цените на GeForce RTX 50 – с до 3300 юана", "schlagzeile": "Изтичане: картите RTX 50 пак поскъпват – с до 3300 юана", "kurz": "Според китайската браншова платформа Channelgate партньорите на NVIDIA в Китай отново вдигат цените на GeForce RTX 50. Посочват се поскъпвания от около 100 до 3300 юана в зависимост от модела. Това не е потвърдено, а цифрите важат само за Китай.", "zusammenfassung": "Китайската браншова платформа Channelgate съобщава, че производителите на видеокарти в Китай отново вдигат цените на GeForce RTX 50 през ноември. Според PC Games Hardware Colorful вече е въвела новите цени, а Galax трябва да последва още тази седмица. Според TechPowerUp съобщените поскъпвания са от около 100 до 150 юана за RTX 5060 Ti с 8 GB до 2200–3300 юана за китайската версия RTX 5090 D V2. За RTX 5080 докладът посочва 2500–2800 юана, за RTX 5070 Ti около 1000 юана, а за RTX 5070 около 600–900 юана повече. Преизчислено това са приблизително от 15 до почти 500 щатски долара. Като причини докладът посочва недостига на графична памет и по-скъпите суровини като медта. Според TechPowerUp по-високите цени може да стигнат до магазините една-две седмици по-късно. Тъй като картите RTX 50 в Китай стават дефицитни, търговците според PCGH все повече се насочват към по-стари модели като RTX 3060 и към карти Radeon. NVIDIA и посочените партньори не са потвърдили официално поскъпванията. Дали и доколко това ще се отрази на цените в Европа, не е ясно.", "zuverlaessigkeit_hinweis": "Непотвърдено: всички публикации се основават на китайската браншова платформа Channelgate (кръга на Board Channels). NVIDIA, Colorful и Galax не са потвърдили нищо официално. Цените важат за Китай и не могат да се пренесат 1:1 за Европа.", "ursprungsquelle": "Channelgate (Board Channels), Китай", "weitere_links": ["TechPowerUp: RTX 50 поскъпват с до 500 долара"], "_src": "1fa9041b"}, "2026-11-03-elder-scrolls-6-sentinel": {"titel": "The Elder Scrolls 6 официално се казва „Sentinel“ – Bethesda показа заглавие и лого", "schlagzeile": "След 8 години мълчание The Elder Scrolls 6 най-после има име", "kurz": "По случай 40-годишнината си Bethesda разкри пълното заглавие на следващата ролева игра от Elder Scrolls: The Elder Scrolls VI: Sentinel. Sentinel е град в региона Hammerfell. Дата на излизане все още няма.", "zusammenfassung": "На 03.11.2026 във видео за 40-годишнината на студиото Bethesda официално потвърди, че The Elder Scrolls VI носи подзаглавието „Sentinel“. Във видеото се виждат заглавието и логото, а думата взима и Тод Хауърд. Sentinel е пристанищен град в провинция Hammerfell в северозападната част на Тамриел. Според IGN цитат във видеото е датиран във време след събитията от Skyrim. Играта беше обявена на E3 2018 и оттогава почти нямаше официална информация. Един доклад беше предсказал името още предишната седмица, а сега то е потвърдено. Bethesda не показа дата на излизане, нито геймплей. Според IGN платформите са Xbox и PC, а версия за PlayStation остава неясна. Eurogamer предполага, че повече може да бъде показано на The Game Awards през декември, но това не е потвърдено.", "weitere_links": ["IGN Германия: The Elder Scrolls 6 се казва Sentinel", "PC Gamer: The Elder Scrolls 6: Sentinel вече е официално"], "_src": "0e2f52ba"}, "2026-11-03-gta6-preload-212gb": {"titel": "GTA 6: Rockstar потвърждава предварително изтегляне от 10.11.2026 и до 212 GB", "schlagzeile": "GTA 6 заема до 212 GB – а предварителното изтегляне започва по-рано", "kurz": "Rockstar Games официално потвърди, че предварителното изтегляне на GTA 6 за PS5 и Xbox Series X|S започва на 10.11.2026. В зависимост от конзолата изтеглянето е до 212 GB. Играта все още трябва да излезе на 19.11.2026.", "zusammenfassung": "Rockstar Games публикува следобед на 03.11.2026 подробностите за предварителното изтегляне на Grand Theft Auto VI. На PS5 то започва на 10.11.2026 в полунощ местно време, а на Xbox Series X|S в същия ден в 0:00 GMT, тоест в 1:00 часа в Австрия и Германия. Според Rockstar изтеглянето е до 212 GB в зависимост от устройството, а PlayStation Blog също съветва да се освободят поне 212 GB място. Така по същество се потвърждава изтичане от края на октомври, според което играта заема около 210 GB на PS5. Според публикациите предварителното изтегляне първоначално беше обявено от 12.11.2026, така че дигиталните играчи могат да започнат два дни по-рано. Версиите в кутия идват в магазините на 12.11.2026 и според публикациите съдържат само код за изтегляне. Премиерата остава на 19.11.2026 за PS5 и Xbox Series X|S. За старта Rockstar ще предложи на сайта си и постер с корицата и карта на Леонида за разпечатване. От информацията не става ясно дали Xbox Series S има нужда от по-малко място.", "weitere_links": ["PlayStation Blog: предварителното изтегляне започва на 10 ноември", "IGN Германия: потвърдени часове и размер на инсталацията", "VGC: Rockstar съобщава дата и размер на предварителното изтегляне"], "_src": "91689255"}, "2026-11-03-fedora-45": {"titel": "Fedora Linux 45 излезе – с GNOME 51, KDE Plasma 6.8 и ядро Linux 7.2", "schlagzeile": "Fedora 45 е тук: нов работен плот, нов инсталатор и проверими билдове", "kurz": "Проектът Fedora пусна Fedora Linux 45. Изданието Workstation използва GNOME 51, а изданието KDE – Plasma 6.8, върху ядро Linux 7.2. Сред новостите са Stratis в инсталатора и възпроизводими билдове на пакетите.", "zusammenfassung": "Fedora Linux 45 излезе на 03.11.2026, около шест месеца след Fedora 44 и според Phoronix след две отлагания. Изданието Workstation идва с GNOME 51, а изданието KDE Plasma Desktop с Plasma 6.8. Като ядро се използва Linux 7.2. Според официалното Fedora Magazine една от най-големите новости е поддръжката на системата за съхранение Stratis директно в инсталатора Anaconda. Виртуалната текстова конзола по подразбиране вече се обслужва от KMSCON, а според 9to5Linux Fedora залага на напълно възпроизводими билдове на пакетите. Проверката на подписите на RPM пакетите е включена по подразбиране, а ptrace е ограничен по подразбиране, което трябва да повиши сигурността. Вариантите Atomic като Silverblue и Kinoite вече се инсталират с новия инсталатор WebUI. За разработчиците има между другото GCC 16.2, LLVM 23, Python 3.15, Go 1.27 и Podman 6. Старите VPN плъгини NetworkManager-vpnc и NetworkManager-fortisslvpn отпадат, затова който ги използва, трябва да прехвърли връзките си преди надграждането. Съществуващите инсталации на Fedora 44 могат да се надградят чрез DNF system-upgrade.", "weitere_links": ["Fedora Magazine (официално): Announcing Fedora Linux 45", "Phoronix: Fedora 45 Released"], "_src": "be19dcc2"}, "2026-11-02-zelda-oot-remake-puppenlook": {"titel": "Zelda: Ocarina of Time за Switch 2: Nintendo обяснява спорния кукления вид на римейка", "schlagzeile": "Римейкът на Zelda изглежда като куклен театър – Nintendo обяснява защо", "kurz": "Римейкът на The Legend of Zelda: Ocarina of Time излиза на 5 ноември за Nintendo Switch 2. Графичният стил с герои, наподобяващи кукли, разделя феновете. В интервю разработчиците обясняват, че нарочно са търсили „усещане за куклен театър“ вместо чист фотореализъм.", "zusammenfassung": "Според Polygon Nintendo коментира спорния графичен стил на римейка на The Legend of Zelda: Ocarina of Time. Link, Zelda и други герои изглеждат по-скоро като кукли, отколкото като фотореалистични хора, което предизвика дискусия сред дългогодишните фенове. Арт директорката Ая Шида казва в интервю с разработчиците, че целта не е била просто всичко да изглежда реалистично. Hyrule трябвало да се усеща като плътен свят, който би могъл наистина да съществува, а цветните, ексцентрични герои да създават контраст, както в оригинала. Според Шида ключовите думи на екипа били „усещане за куклен театър“ и „аналоговата атмосфера на филмите с практически ефекти“. Продуцентът на поредицата Еиджи Аонума обяснява, че екипът изпитва носталгия, когато гледа оригинала за Nintendo 64, а изразяването на тази носталгия довело до аналоговия куклен вид. Според Video Games Chronicle римейкът излиза в четвъртък, 5 ноември 2026 г., за Nintendo Switch 2. Разработва го вътрешното подразделение на Nintendo – Nintendo EPD, което създаде и Breath of the Wild и Tears of the Kingdom. Дали стилът ще убеди, ще покажат едва ревютата след излизането.", "weitere_links": ["Video Games Chronicle: Zelda: Ocarina of Time UK midnight launch"], "_src": "dda2e7e2"}, "2026-11-02-rtx5080-preis-heise": {"titel": "RTX 5080 почти не се намира под 2000 евро; според доклад версията с 24 GB може да закъснее", "schlagzeile": "RTX 5080 мина 2000 евро: над 30% по-скъпа само за две седмици", "kurz": "Според heise online GeForce RTX 5080 в момента почти не се намира под 2000 евро; цената ѝ се е повишила с над 30% за две седмици. heise посочва като причина слуховете за спиране на RTX 5090, която вече струва около 8000 евро. Според непотвърден доклад на BenchLife очакваната версия на RTX 5080 с 24 GB може да закъснее.", "zusammenfassung": "След RTX 5090 и RTX 5080 поскъпва осезаемо, съобщава heise online: втората най-бърза геймърска видеокарта на NVIDIA в момента почти не се намира под 2000 евро. Това е с над 30% повече, отколкото само преди две седмици. В средата на октомври се появиха слухове, че NVIDIA може да изтегли RTX 5090 от пазара, което според heise е повишило търсенето на 5080. Самата RTX 5090 вече струва около 8000 евро; последната препоръчителна цена на NVIDIA беше 2099 евро. NVIDIA опроверга спирането на 5090, но само с думите, че картата „ще продължи да се доставя“. Според heise от това не става ясно дали ще продължи да се произвежда. През октомври се говореше и че RTX 5080 с 24 вместо 16 GB GDDR7 ще бъде представена през януари 2027 г. Според тайванския сайт BenchLife обаче производителите на карти все още не са получили от NVIDIA нужната проектна документация, въпреки че тя е била планирана за октомври. Това е непотвърден доклад; NVIDIA не е коментирала. Освен това наличностите от чипове GB203 в Китай вече били разпродадени и щели да стигнат само за един-два месеца. heise посочва бума на ИИ като причина за недостига: същите чипове и оскъдната памет GDDR7 отиват и в скъпи карти за работни станции с по-висок марж. Който търси топ видеокарта, засега трябва да очаква високи цени.", "weitere_links": ["Wccftech: RTX 5080 24 GB may miss January 2027 launch"], "_src": "ecd4a72d"}, "2026-11-02-windows11-smart-app-control-fix": {"titel": "Microsoft поправя грешка: Smart App Control не можеше да се включи след октомврийската актуализация", "schlagzeile": "Windows 11: защитата бе блокирана след октомврийския ъпдейт – вече има поправка", "kurz": "След октомврийската актуализация за сигурност KB5127648 защитната функция Smart App Control в Windows 11 не можеше да се включи на някои компютри. Microsoft поправи грешката с актуализациите от 28 октомври 2026 г., включително незадължителната предварителна актуализация KB5127936. Там, където Smart App Control вече беше включен, защитата работеше през цялото време.", "zusammenfassung": "Според BleepingComputer Microsoft поправи известна грешка в Windows 11, появила се след актуализацията за сигурност KB5127648 от октомври 2026 г. На засегнатите устройства с Windows 11 24H2 или по-нова версия опцията Smart App Control в Защита на Windows беше сива и не можеше да се включи. Smart App Control блокира потенциално опасни приложения в допълнение към SmartScreen и Microsoft Defender. Засегнати бяха само компютри, на които функцията преди това е била изключена. Там, където вече е била включена, устройствата останаха защитени, според Microsoft. Грешката е поправена с актуализациите на Windows от 28 октомври 2026 г. и по-новите, включително незадължителната предварителна актуализация KB5127936. Microsoft препоръчва да се инсталира най-новата актуализация. За фирмени компютри, които не искат да чакат следващия Patch Tuesday, Microsoft предлага временно решение чрез два записа в регистъра или специални групови политики, и в двата случая с рестарт. Според BleepingComputer KB5127936 поправя и проблеми с Отдалечения работен плот при включена „Администраторска защита“, както и грешки с VPN след актуализациите от септември 2026 г. Домашните потребители трябва само да инсталират актуализацията.", "_src": "2c58e168"}, "2026-11-02-raspberry-pi5-16gb-preis": {"titel": "Raspberry Pi 5 с 16 GB RAM поскъпва за четвърти път: 385 вместо 305 долара", "schlagzeile": "Raspberry Pi 5 с 16 GB вече струва 385 долара – три пъти повече от началото", "kurz": "Raspberry Pi вдига каталожната цена на Raspberry Pi 5 с 16 GB RAM от 305 на 385 долара. Това е четвъртото поскъпване от декември 2025 г.; при излизането цената беше 120 долара. Причината е растящата цена на RAM паметта, но този път Raspberry Pi 500+ не поскъпва.", "zusammenfassung": "Според heise online Raspberry Pi 5 с 16 GB LPDDR4 RAM отново поскъпва. Каталожната цена се повишава с 80 долара до 385 долара. Това вече е четвъртото поскъпване след декември 2025 г., февруари 2026 г. и април 2026 г. При излизането тази версия струваше 120 долара, около 135 евро, според heise. Производителят обяснява поскъпването с постоянно растящите цени на RAM паметта. Шефът на Raspberry Pi Ебен Ъптън обяснява, че за 16-гигабайтовия чип памет няма алтернативен доставчик. Същият чип се използва и в Compute Module 5 и Raspberry Pi 500+. Версията на Compute Module 5 с 16 GB поскъпва с 40 долара, а Raspberry Pi 500+ този път не. Според heise поскъпват и някои други модели Raspberry Pi. Заради недостига производителят е въвел допълнителни варианти на сглобяване за няколко продукта, за да може да използва чипове памет от други производители. Golem.de съобщава, че един Pi 5 вече струва почти 350 евро. Колко ще се вдигнат цените в магазините, зависи от търговеца.", "weitere_links": ["Golem.de: Pi 5 und Compute Module – Raspberry Pi kostet mittlerweile fast 350 Euro"], "_src": "7815dfa5"}, "2026-11-02-rtx5090-pro5500-igorslab": {"titel": "RTX 5090 срещу RTX PRO 5500: igor'sLAB проверява дали професионалната карта на NVIDIA отнема чиповете на геймърската видеокарта", "schlagzeile": "Над 8000 евро за RTX 5090: Професионалната карта на NVIDIA ли ѝ взима чиповете?", "kurz": "Според igor'sLAB RTX 5090 с наличност веднага е струвала 8059 евро в германски магазин на 1 ноември 2026 г., докато препоръчителната цена на Founders Edition е 2099 евро. Анализът проверява дали NVIDIA предпочита да влага подходящите чипове GB202 в предстоящата професионална карта RTX PRO 5500, която има същия брой изчислителни блокове. Изводът: икономически правдоподобно, но публично недоказано.", "zusammenfassung": "igor'sLAB е проучил защо GeForce RTX 5090 почти не може да се намери на първоначалната си цена. При проверка на магазини от 1 ноември 2026 г. INNO3D RTX 5090 iCHILL X3 с наличност веднага е струвала 8059 евро в ALTERNATE, а ZOTAC Solid OC White – 8499 евро в Caseking. Германската препоръчителна цена на Founders Edition е 2099 евро, но там тя е обявена като неналична. Във фокуса е предстоящата RTX PRO 5500 Blackwell Workstation Edition: според данни на партньори тя също използва големия чип GB202 със 170 активни стрийминг мултипроцесора и 21 760 CUDA ядра, но има 84 GB GDDR7 с ECC вместо 32 GB. Позовавайки се на анонимни източници, Reuters съобщи на 20 октомври 2026 г. за над три милиона поръчани от Китай карти PRO 5500 на цена около 11 400 долара за брой. Това би дало на NVIDIA стимул да влага подходящите чипове по-скоро в скъпата професионална карта, отколкото в геймърската. igor'sLAB обаче подчертава, че това не е публично доказано: няма данни нито за добива на чипове, нито за разпределението им между двата продукта. Освен това доставките на геймърски карти бяха оскъдни още преди съобщените поръчки за PRO 5500, а редовните доставки на професионалната карта се очаква да започнат едва през първото тримесечие на 2027 г. Като друго тясно място анализът посочва паметта GDDR7, която според TrendForce все повече се заделя за AI и сървърни приложения. Примерните изчисления за разходи и маржове в статията изрично се основават на свободно избрани допускания и не са реални данни на NVIDIA. Изводът на igor'sLAB: професионалната карта е сериозен конкурент за чипове и памет, но измеримо изместване на RTX 5090 не е доказано.", "_src": "bff68b5d"}, "2026-11-01-linux-7-4-rc1": {"titel": "Излезе Linux 7.4-rc1: най-големият merge прозорец в историята на ядрото, до голяма степен задвижен от AI", "schlagzeile": "Linux 7.4: рекорден ъпдейт заради лавина от AI – и Торвалдс е доволен", "kurz": "Линус Торвалдс пусна първата тестова версия на Linux 7.4. С почти 20 000 commit-а merge прозорецът беше най-големият в историята на ядрото, а голяма част от промените са предизвикани от AI инструменти. Сред новостите са подготовката за процесорите Zen 6 на AMD и HDMI 2.1, включен по подразбиране в драйвера AMDGPU.", "zusammenfassung": "Линус Торвалдс пусна Linux 7.4-rc1 в неделя вечерта и така затвори merge прозореца по план. Според Торвалдс той е бил необичайно голям – почти 20 000 commit-а вместо обичайните около 15 000, а според Phoronix най-големият в историята на ядрото. Като главна причина Торвалдс посочва лавината от промени, предизвикани от AI. Той го приема положително: много повече предпочита тази работа да влиза в merge прозореца, отколкото като вълна от поправки в тестовата фаза. Според Торвалдс друга причина може да е, че Linux 7.4 се очаква да стане следващата версия с дългосрочна поддръжка. По думите му една трета от пача са само дефиниции на регистри на GPU на AMD. Според Phoronix новостите включват поддръжка за предстоящите процесори Ryzen със Zen 6, HDMI 2.1 по подразбиране в драйвера AMDGPU и функцията AMD PerfOpt за по-добра AI производителност на интегрираните Radeon GPU. Освен това има поддръжка на Intel IPU8 за предстоящите лаптопи с Nova Lake, повече поддръжка за лаптопи със Snapdragon X2, първи основи за Apple M4 (още не е готово за ежедневна употреба) и по-бързо компилиране на ядрото. До финалната версия предстоят няколко тестови версии. Ако всичко върви по план, Linux 7.4 ще излезе на 20 декември 2026 г., според Phoronix. За обикновените потребители е най-добре да изчакат, докато дистрибуцията им достави новото ядро.", "weitere_links": ["LWN.net: prepatch на ядрото 7.4-rc1"], "_src": "4f089b1b"}, "2026-11-01-gta6-210gb-download": {"titel": "GTA 6: появи се размер за изтегляне от 210 GB за PS5", "schlagzeile": "Изтичане: Наистина ли GTA 6 ще заеме цели 210 GB на PS5?", "kurz": "Според акаунта за данни PlayStation Game Size изтеглянето на GTA 6 за PS5 ще е около 210 GB, а Insider Gaming твърди, че може да го потвърди. Rockstar официално не е посочил размер, така че цифрата е непотвърдена. Сигурно е, че дигиталните предварителни поръчки могат да се изтеглят предварително от 12 ноември 2026 г., а играта излиза на 19 ноември 2026 г.", "zusammenfassung": "Специализираният в данни от магазина акаунт в X PlayStation Game Size (@PlaystationSize) посочи на 27 октомври 2026 г. размер за изтегляне от 210 GB за стандартното издание на Grand Theft Auto VI за PlayStation. Insider Gaming писа за това на 1 ноември 2026 г. и твърди, че може да потвърди информацията. Според Insider Gaming това би направило GTA 6 една от най-големите игри за всички времена. Нито Rockstar Games, нито Take-Two са потвърдили официално размера, затова цифрата се смята за непотвърдена. Insider Gaming също отбелязва, че размерът може да се промени до излизането и че пач за първия ден може да заеме допълнително място. Източникът не дава цифра за версията за Xbox. Датите обаче са официално потвърдени: според Rockstar дигиталните предварителни поръчки могат да се изтеглят предварително от 12 ноември 2026 г., а играта излиза на 19 ноември 2026 г. за PlayStation 5 и Xbox Series X|S. Според Rockstar версията в кутия съдържа само код за изтегляне и също ще се продава от 12 ноември 2026 г. Според Rockstar стандартното издание струва 79,99 долара, а Ultimate Edition – 99,99 долара. Който иска да играе от първия ден, трябва навреме да си освободи доста място на конзолата.", "zuverlaessigkeit_hinweis": "Идва от акаунта за данни @PlaystationSize (анализира данни от магазина); Insider Gaming твърди, че може да потвърди цифрата. Не е потвърдено официално от Rockstar или Take-Two; размерът може да се промени до излизането и с пач за първия ден.", "ursprungsquelle": "PlayStation Game Size (@PlaystationSize) в X, 27 октомври 2026 г.", "weitere_links": ["Take-Two/Rockstar: предварителни поръчки, предварително изтегляне от 12 ноември 2026 г., излизане на 19 ноември 2026 г. (официално)"], "_src": "386ea700"}, "2026-11-01-windows11-26h2-alle": {"titel": "Windows 11 26H2 вече е достъпен за всички съвместими компютри, включително директно от Windows 10", "schlagzeile": "Windows 11 26H2 вече е за всички – включително за компютри с Windows 10", "kurz": "Microsoft приключи поетапното разпространение на Windows 11 26H2: според Microsoft ъпдейтът е достъпен за всички съвместими устройства от 28 октомври 2026 г. Според Neowin вече се предлага и директно чрез Windows Update на съвместими компютри с Windows 10. Условието остава компютърът да отговаря на хардуерните изисквания на Windows 11.", "zusammenfassung": "Microsoft пусна Windows 11 26H2 за всички в края на септември 2026 г., но както обикновено го разпространяваше поетапно. Така сериозни проблеми не засягат изведнъж много устройства, което е важно най-вече за фирмите. Според Neowin разпространението първо достигна пълна наличност за устройства с Windows 11 25H2 и 24H2. Сега Microsoft пише, че към 28 октомври 2026 г. Windows 11 26H2 е достъпен за всички съвместими устройства. Според Neowin това важи и за съвместими компютри с Windows 10, на които ъпдейтът вече се предлага директно чрез Windows Update. Редакцията твърди, че го е видяла на един от собствените си компютри с Windows 10. Който вече ползва Windows 11 24H2 или 25H2 и още не е получил ъпдейта, може според Neowin да инсталира ръчно активиращия пакет eKB5121794. Това обаче не работи от Windows 10 или от по-стари версии на Windows 11. За чиста инсталация има актуални ISO файлове чрез Media Creation Tool на Microsoft. Според Neowin 26H2 използва по-малко RAM памет и работи по-пъргаво, но това е оценка на самата редакция. Остава едно условие: предложението получават само компютри, които отговарят на хардуерните изисквания на Windows 11.", "_src": "7b79cfea"}, "2026-11-01-rtx2080ti-22gb-pcgh": {"titel": "Употребявана RTX 2080 Ti с 22 GB: PCGH тества китайския мод на паметта", "schlagzeile": "22 GB в стара RTX 2080 Ti: колко добър е китайският мод всъщност?", "kurz": "PC Games Hardware тества RTX 2080 Ti, чиято видеопамет е удвоена в Китай от 11 на 22 GB. При 1440p разликата обикновено е малка, но при 4K и при AI задачи модифицираната карта ясно изпреварва оригинала. За такова преустройство няма гаранция.", "zusammenfassung": "PC Games Hardware тества модифицирана GeForce RTX 2080 Ti с удвоена видеопамет, която читател е купил през Alibaba. Вместо 11 GB платката носи единадесет чипа Samsung по 2 GB, т.е. 22 GB GDDR6 върху непроменения 352-битов интерфейс с 616 GB/s. Благодарение на променен конфигурационен резистор (strap) картата работи без модифициран BIOS и с нормални драйвери. При 1440p с DLSS Quality разликите спрямо версията с 11 GB обикновено са малки, но времената на кадрите са по-равномерни. В Microsoft Flight Simulator 2024 и Spider-Man 2 оригиналната карта според теста изостава с около 20 процента. При 4K с DLSS Performance и FSR Frame Generation картата с 11 GB накъсваше силно, а Indiana Jones дори се срина. В Spider-Man 2 е измерено използване на памет до 13,9 GB. В AI теста с ComfyUI картата с 22 GB се нуждаеше от около 315 секунди вместо около 540 – RTX 5070 Ti се справи със същото за около 85 секунди. За купувачите на употребяван хардуер това означава: модът може да си струва, но е намеса без гаранция от производителя, а качеството на такива преустройства е различно.", "weitere_links": ["Тест на PCGH (оригинал)"], "_src": "03eb821d"}, "2026-11-01-larrabee-fund": {"titel": "Пълна система за разработка на Intel Larrabee открита в склад под наем", "schlagzeile": "Находка в склад: неизлизал GPU на Intel се появи заедно с компютър за разработка", "kurz": "Потребител в Reddit откри в склад, купен на търг, пълна система за разработка за GPU-то Larrabee на Intel, което така и не излезе на пазара. Компютърът зарежда Windows 7 и според твърденията дори пуска Crysis, но стойностите на FPS не са проверени независимо. Оригиналният софтуер вече е в Internet Archive.", "zusammenfassung": "Потребител в Reddit намери при търга на склад под наем пълна система за разработка за никога неизлизалото GPU Larrabee на Intel. В компютъра има дънна платка Intel DX58SO с инженерна мостра в степинг C0, означена като „Intel Visual Adrenaline“. Към нея имаше две USB флашки с оригиналния софтуер, който откривателят вече качи в Internet Archive. Системата зарежда Windows 7 и поддържа Direct3D. Според собственика Crysis е вървял на 720p със средни детайли с около 17 FPS, а с друг драйвер уж с около 36 FPS – тези стойности не са проверени независимо. Intel спря Larrabee като видеокарта през 2010 г.; технологията по-късно продължи да живее в ускорителите Xeon Phi. За колекционерите на хардуер толкова пълна система със софтуер е истинска рядкост.", "_src": "e8e20545"}, "2026-10-31-nv-uefi-unlocker": {"titel": "Инструмент с отворен код отключва повече AI производителност при RTX 20, 30 и 40", "schlagzeile": "Безплатен инструмент вади до 75% повече AI мощ от RTX карти – с уловка", "kurz": "Инструментът с отворен код „nv-uefi-unlocker“ отключва ограничени изчислителни блокове за AI задачи при картите RTX 20, 30 и 40. В цитираните тестове производителността се е повишила с около 29 до 75 процента в зависимост от картата и задачата. Полза в игрите не е доказана, Secure Boot трябва да е изключен, а използването е на собствен риск.", "zusammenfassung": "Разработчикът physicsdolphin публикува „nv-uefi-unlocker“ – инструмент с отворен код, който трябва да отключва ограничени изчислителни блокове в картите GeForce за AI натоварвания. Инструментът стартира от USB флашка преди самия драйвер и след това работи и под Windows. Промяната не е постоянна и трябва да се прилага отново след всяко студено стартиране. Поддържат се RTX 20, 30 и 40, GTX 16 само експериментално, а RTX 50 изобщо не. Secure Boot трябва да е изключен, а картите Turing допълнително се нуждаят от GSP фърмуер. Цитирани резултати: RTX 2070 печели 67 до 75 процента във FP32 GEMM, а лаптопен GPU RTX 4060 се покачва във FP16 от 29,89 на 49,33 TFLOPS. Потребител с RTX 3080 LHR съобщава за около 29 процента по-висока скорост в ComfyUI със SDXL; при генерирането на текст с LLM обаче инструментът носи малко. Който го пробва, го прави на собствен риск – полза за производителността в игрите не е доказана.", "_src": "111abea6"}, "2026-10-31-amd-adrenalin-26-10-2": {"titel": "AMD Adrenalin 26.10.2: незадължителният драйвер за Radeon поправя десет грешки, няколко проблема остават", "schlagzeile": "Сривове при Radeon: новият драйвер на AMD поправя десет грешки – но не всички", "kurz": "AMD пусна незадължителния графичен драйвер Adrenalin 26.10.2, който поправя десет грешки, сред които таймаути на драйвера, сривове и изключвания на системата при Radeon RX 7000 и RX 9000. Той не добавя поддръжка за нови игри. Няколко известни проблема, например в Cyberpunk 2077 и Assassin's Creed Black Flag Resynced, остават нерешени.", "zusammenfassung": "AMD пусна на 30 октомври 2026 г. незадължителния графичен драйвер Adrenalin Edition 26.10.2 за Windows. Според официалните бележки към версията това е ъпдейт само с поправки – общо десет. Наред с другото той поправя сривове или таймаути на драйвера при отваряне или затваряне на други наслагвания като Xbox Game Bar, докато е активно наслагването за производителност на AMD. Клиентът на Steam също понякога се сриваше при стартиране на карти Radeon, което вече би трябвало да е поправено. При RX 7600 драйверът премахва изключванията на системата във Valor Mortis, а при останалите RX 7000 – таймаутите на драйвера в същата игра. За серията RX 9000 AMD поправя забиванията в Death Stranding 2 с включен FSR и сривовете при превключване между приложения с FSR Frame Generation. Добавени са и поправки при възпроизвеждане на видео под Windows 11 с хардуерно ускорено планиране на GPU (HAGS) и за грешка в AMD Install Manager. Не всичко е решено: в Assassin's Creed Black Flag Resynced при RX 7000 все още може да има сривове, а във War Thunder при RX 5000 – таймаути. За War Thunder AMD засега препоръчва по-стария драйвер 26.9.1. В Cyberpunk 2077 някои карти RX 9000 може да се сриват, когато са активни FSR upscaling, Anti-Lag и генериране на кадри, докато на втори екран върви видео; тогава AMD съветва да се изключи генерирането на кадри в играта. Според AMD освен това под Windows 10 след инсталацията Smart Access Memory може да се окаже изключен, затова при съмнение си струва да се провери в драйвера. Ако нямате нито един от поправените проблеми, не е нужно веднага да инсталирате незадължителния драйвер.", "weitere_links": ["AMD: бележки към версията Adrenalin Edition 26.10.2 (официално)"], "_src": "f1d0f566"}, "2026-10-31-altman-pc-ram": {"titel": "Сам Алтман: RAM в компютрите е „доста ужасно“ използване на оскъдния DRAM капацитет", "schlagzeile": "Сам Алтман: RAM паметта в компютъра ви е „доста ужасно“ използвана", "kurz": "В подкаста „Cheeky Pint“ главният изпълнителен директор на OpenAI Сам Алтман нарече „quite terrible“ това, че DRAM стои в компютри, които по негова груба оценка работят само около пет процента от времето. Фонът е недостигът на памет, тъй като производителите правят все повече памет за сървъри и AI. За сглобяващите компютри това означава, че RAM едва ли ще поевтинее скоро.", "zusammenfassung": "Главният изпълнителен директор на OpenAI Сам Алтман говори за сегашния недостиг на памет в подкаста „Cheeky Pint“ със съоснователя на Stripe Джон Колисън. Там той нарече „quite terrible“ (доста ужасно) това, че DRAM стои в компютри, които се използват само около пет процента от времето. Тези пет процента са негова собствена груба оценка, а не проверена цифра. Фонът е, че производителите на памет все повече пренасочват производството към памет за сървъри и AI, което вдига цените на RAM за потребителите. VideoCardz ясно не е съгласен с Алтман в коментара си. За сглобяващите компютри изказването е преди всичко знак, че цените на RAM едва ли скоро ще паднат отново.", "_src": "be0c42aa"}, "2026-10-30-linux-kernel-tcp-luecke": {"titel": "Ядро на Linux: сериозна пробойна в TCP кода позволява отдалечени root атаки срещу MPTCP сървъри", "schlagzeile": "Linux: пробойна в ядрото дава отдалечен root достъп – обновете сега", "kurz": "Пробойна тип use-after-free в IPv4 TCP кода на ядрото на Linux (CVE-2026-98432) засяга ядра чак до версия 4.4. Изследователи демонстрираха отдалечен root достъп на сървъри, които предлагат Multipath TCP (MPTCP). Debian вече има обновления, другите дистрибуции следват.", "zusammenfassung": "Според BleepingComputer IPv4 TCP кодът на ядрото на Linux съдържа пробойна тип use-after-free, причинена от състояние на надпревара (CVE-2026-98432). Засегнати са ядра чак до версия 4.4. Екипът за CVE на ядрото оценява пробойната с 9,8 от 10, а Red Hat – само с 5,9, защото експлоатацията е сложна и основният риск са сривовете. Изследователи от Anthropic демонстрираха отдалечен root достъп на сървъри с MPTCP listener; според публикацията експлойтът е създаден от неиздаден модел Claude за около 53 минути. Обикновеният TCP също е засегнат, но там изпълнение на код не е показано. Реални атаки не са потвърдени. Неприятното: програмите, компилирани с Go 1.24 или по-нова версия, включват MPTCP под Linux по подразбиране. Въпреки това екипът по сигурност на Go препоръчва обновяване на ядрото вместо изключване на MPTCP за всяка програма поотделно – а и според публикацията самото изключване на MPTCP не е достатъчно. Debian пусна поправени ядра за Bookworm и Trixie; за Ubuntu обновленията бяха в процес на подготовка на 30 октомври. Засегнати са RHEL 8 до 10; SUSE, Oracle и Amazon Linux към онзи момент имаха частично обновления. Пробойната е поправена, наред с други, във версиите на ядрото 6.1.190, 6.6.159, 6.12.113, 6.18.56 и 7.3. Който поддържа Linux сървъри, трябва бързо да обнови ядрото и да рестартира.", "weitere_links": ["oss-security: съобщение от екипа по сигурност на Go за MPTCP", "LWN.net: нови стабилни ядра"], "_src": "d946d2fe"}, "2026-10-30-windows-insider-suche": {"titel": "Insider компилации на Windows: ново търсене с плъзгачи и действия с телефона, Beta задава разрешения за всяко приложение", "schlagzeile": "Windows 11 тества ново търсене с плъзгачи и действия с телефона", "kurz": "В нови Insider компилации Microsoft тества преработено търсене в Windows. То показва плъзгачи, например за сила на звука и яркост, директно в резултатите и може да започва обаждания или SMS чрез Phone Link. Beta компилацията 26220.9836 позволява и разрешения за камера, микрофон и местоположение за всяко настолно приложение.", "zusammenfassung": "На 30 октомври Microsoft пусна нови Insider компилации на Windows 11, сред тях Beta 26220.9836 и Experimental 26340.9843. В каналите Experimental стартира ново търсене в Windows. То показва плъзгачи за сила на звука, яркост или размер на курсора на мишката директно в резултатите. Чрез Phone Link ще може да се управляват обаждания, SMS и режимът „Не безпокойте“ на телефона – първо с Android, а поддръжката на iPhone трябва да дойде в началото на следващата година. Добавят се и по-подробни резултати с преглед на файлове, отговори от мрежата, например за времето и борсата, и приложения от Store; това може да се изключи в Поверителност и защита > Търсене. Резултатите могат да се филтрират и оценяват с палец нагоре или надолу. Засега търсенето се отваря долу в средата; според Microsoft се работи по адаптирането му към позицията на лентата на задачите. Според Windows Report Beta компилацията носи и разрешения за камера, микрофон и местоположение за отделни настолни приложения, като досегашните решения се запазват. Както при всички Insider функции, не е ясно дали и кога ще стигнат до нормалната версия на Windows.", "weitere_links": ["Windows Report: Beta компилация 26220.9836 с разрешения за отделни приложения"], "_src": "bbfec2ce"}, "2026-10-30-nova-lake-28c-prognose": {"titel": "Nova Lake-S с 28 ядра: вътрешна прогноза говори за 16 до 33% повече производителност в игри", "schlagzeile": "Изтичане: следващият геймърски процесор на Intel ще е до 33% по-бърз", "kurz": "Според VideoCardz вътрешни прогнози на Intel обещават на Nova Lake-S, в зависимост от варианта, 16 до 33 процента повече производителност в игри от Core Ultra 9 285K. Част от преднината обаче идва от по-бързата памет DDR5-8000, използвана в сравнението. Това са непотвърдени целеви стойности, които може още да се променят до пускането.", "zusammenfassung": "Според VideoCardz вътрешни прогнози на Intel от август 2026 г. показват колко по-бърз трябва да е Nova Lake-S в игрите. Основа е собственият „Gaming Index“ на Intel, а сравнението е с Core Ultra 9 285K. 28-ядрен вариант с PL1 285 W трябва да е до 1,16 пъти по-бърз от 285K при 250 W. Вариант с два compute tile-а и 296 W трябва да е до 1,33 пъти по-бърз. Важно: Nova Lake е работил с DDR5-8000 чрез XMP, а Arrow Lake – само с DDR5-6400, така че част от преднината идва от по-бързата памет. Допълнителни данни от потребителя в X Haze, като +8 процента в една нишка без и +17 процента с голям кеш от последно ниво, според VideoCardz не са проверени. Такива ранни прогнози са целеви стойности и може още да се променят до пускането. Официално Intel досега е потвърдил само, че Nova Lake се базира на процеса 18A-P и че повече подробности ще има на CES през януари.", "zuverlaessigkeit_hinweis": "Предполагаеми вътрешни слайдове на Intel, разпространени от трети лица; не са проверени независимо, целите може да са се променили.", "ursprungsquelle": "Haze (@Haze2K1) / предполагаеми слайдове на Intel", "_src": "6e13f4ff"}, "2026-10-30-rtx5080-marketplace": {"titel": "RTX 5080 изчезна от американския магазин на NVIDIA – след RTX 5090", "schlagzeile": "Първо RTX 5090, сега RTX 5080: американският магазин на NVIDIA се изпразва", "kurz": "GeForce RTX 5080 изчезна от официалния marketplace на NVIDIA в САЩ, малко повече от две седмици след RTX 5090. При търговците в САЩ най-евтината RTX 5080 струва около два пъти повече от препоръчителната си цена от 999 долара. Това не доказва край на производството, но предлагането е видимо ограничено.", "zusammenfassung": "GeForce RTX 5080 изчезна от официалния marketplace на NVIDIA в САЩ; потребители в Reddit забелязаха това първо в списъка с филтри. RTX 5090 беше премахната още на 16 октомври, за кратко се появи отново за 5599 долара и пак изчезна – препоръчителната ѝ цена е 1999 долара. На 28 октомври най-евтината RTX 5080 струваше 1979,99 долара при търговците в САЩ и 1999,99 долара в Best Buy при препоръчителна цена 999 долара. NVIDIA преди това отрече, че RTX 5090 е спряна. Всички карти от серията RTX 50 в момента се продават доста над препоръчителната цена. Премахването на карта от магазина само по себе си не доказва край на производството – но показва колко ограничено е предлагането.", "_src": "99a9c410"}, "2026-10-30-witcher4-sprecher": {"titel": "The Witcher 4: изказвания на актьори от дублажа подхранват слуховете за познати герои", "schlagzeile": "Изтичане: завръщат ли се Лютичето и Йенефер в The Witcher 4?", "kurz": "Няколко актьори, които озвучават герои, коментираха The Witcher 4 и разпалиха спекулации за познати персонажи. Полският глас на Лютичето казва, че е записал няколко реплики, а гласът на Гералт, Дъг Кокъл, все още нищо. CD Projekt RED не коментира.", "zusammenfassung": "Според ixbt.games гласът на Гералт, Дъг Кокъл, е казал в края на октомври в подкаста Kinda Funny Games, че все още не е записал нищо за The Witcher 4 и не знае какъв ще е обемът на ролята на Гералт. По-скоро очаква поддържаща, отколкото главна роля. Според VGTimes Яцек Копчински, полският глас на Лютичето, е казал на PSX Extreme Party на 5 септември, че вече е записал няколко реплики за The Witcher 4 – „не много“. За също обявения проект „Songs of the Past“ обаче още не е записал нищо. Според Notebookcheck потребител в Reddit е разказал, че актрисата, озвучаваща Йенефер, Дениз Гоф, споделила на автограф сесия, че е записала нови диалози, свързани с Цири; не е ясно за кой проект. През 2025 г. Гоф беше казала пред Eurogamer, че участието ѝ в The Witcher 4 е несигурно. CD Projekt RED не коментира нито едно от тези изказвания. Официално потвърдено: Цири е главната героиня, а играта излиза за PC, PS5 и Xbox Series X|S. През август съизпълнителният директор Михал Новаковски посочи 2028 г. като целеви период за излизане. CD Projekt ще представи следващите си тримесечни резултати на 24 ноември.", "zuverlaessigkeit_hinweis": "Изказвания на актьори от дублажа, отчасти само от втора ръка (Reddit, репортажи от събития) и отчасти без яснота за кой проект са записвали; CD Projekt RED не е потвърдил нищо.", "ursprungsquelle": "Изказвания на актьорите (подкаст Kinda Funny Games, PSX Extreme Party 2026, автограф сесия според потребител в Reddit)", "weitere_links": ["VGTimes: гласът на Лютичето е записал реплики за The Witcher 4", "Notebookcheck: изтичане за Witcher 4 намеква за завръщане на популярен герой"], "_src": "9d06ea0f"}, "2026-10-30-amd-preiserhoehung": {"titel": "AMD отново ще вдигне цените на Radeon и GDDR6 през ноември", "schlagzeile": "Изтичане: картите Radeon може пак да поскъпнат още през ноември", "kurz": "Според китайския форум на търговци Board Channels AMD е вдигнала през октомври цените на едро на Radeon и може да ги вдигне отново през ноември. Отделно от това, според Hardware Unboxed цените на видеокартите са се повишили с около 35 процента за три месеца. AMD не е потвърдила планираното повишение.", "zusammenfassung": "Според информация от китайския форум на търговци Board Channels AMD е вдигнала на 1 октомври цените на едро на GPU-тата Radeon и може да ги вдигне отново през ноември. AMD уж преразглежда цените си всяко тримесечие. Паметта GDDR6 също е поскъпнала с около 8 до 10 процента през третото тримесечие. Отделно Hardware Unboxed е следил цените на видеокартите в десет държави: за три месеца те са се повишили с около 35 процента, само през октомври – с 10 процента. Според данните RX 9060 XT 16GB е поскъпнала със 17 процента, а RX 9070 и RX 9070 XT – с около 12 процента всяка. AMD не е потвърдила планираното повишение. Който има нужда от видеокарта, трябва да следи цените – пазарът на употребявани вероятно също ще бъде засегнат.", "zuverlaessigkeit_hinweis": "Форум на търговци Board Channels; ценовите данни на Hardware Unboxed са документирани, планираното повишение от AMD – не.", "ursprungsquelle": "Board Channels", "_src": "61551511"}, "2026-10-30-intel-q3-nova-lake-18a-p": {"titel": "Тримесечни резултати на Intel: Nova Lake на 18A-P изпреварва графика, подробности на CES", "schlagzeile": "Intel натиска газта: Nova Lake изпреварва графика", "kurz": "На конферентния разговор за третото тримесечие Intel потвърди, че Nova Lake ще е първият клиентски продукт на процеса 18A-P и че разработката изпреварва графика. Подробности ще има на CES през януари. Intel обаче вижда пазара на компютри в корекция заради високите цени на паметта.", "zusammenfassung": "На конферентния разговор за резултатите от третото тримесечие на 2026 г. (29 октомври, американско време) Intel потвърди, че Nova Lake ще е първият клиентски продукт на процеса 18A-P. Разработката изпреварва графика, а Intel очаква два пъти повече design wins, отколкото при Panther Lake. Повече подробности ще има на CES през януари. Според Intel добивът при 18A се подобрява с двуцифрени проценти, а 18A-P е в график до края на годината. При същата консумация 18A-P трябва да дава около 9 процента по-висока честота или при същата честота около 18 процента по-ниска консумация. За 14A през октомври излезе PDK 0.9, версия 1.0 следва през първото тримесечие на 2027 г., а производството е планирано за 2028 г. При сървърите Diamond Rapids идва през 2027 г. на 18A-P, а Coral Rapids – през 2028 г. на 14A. Intel обаче вижда пазара на компютри в корекция, докато цените на паметта не се нормализират – компанията очаква общият пазар да е с около 10 процента по-малък. Според Tom's Hardware Intel освен това изтегля капацитет от Panther Lake, за да произвежда повече сървърни процесори Granite Rapids.", "datum_hinweis": "Часът е приблизителен (публикувано сутринта на 30.10)", "weitere_links": ["Стенограма (The Motley Fool)", "Бележки на harukaze5719 в X"], "_src": "728b9684"}, "2026-10-30-rtx5080-24gb": {"titel": "RTX 5080 с 24 GB ще дойде до януари 2027 г. и ще замени версията с 16 GB", "schlagzeile": "Изтичане: RTX 5080 с 24 GB ще дойде още около Нова година", "kurz": "Според Board Channels NVIDIA планира GeForce RTX 5080 с 24 вместо 16 GB, която да излезе първо в Китай между декември 2026 и януари 2027 г. Там версията с 16 GB ще бъде изведена от продажба. Името, честотите и цената са неизвестни, а NVIDIA не е потвърдила нищо.", "zusammenfassung": "Според публикация на китайския форум на търговци Board Channels (ChannelGate) NVIDIA планира GeForce RTX 5080 с 24 GB памет. Тя трябва да излезе в Китай най-рано през декември 2026 г. и най-късно през януари 2027 г. Сегашната версия с 16 GB и RTX 5090 D V2 там ще бъдат изведени от продажба; оставащите наличности от GPU с 16 GB уж ще стигнат за още около два месеца. BenchLife вече на 12 октомври писа за пускане през първото тримесечие на 2027 г., но партньорите уж са получили само устни намеци. 50-те процента повече памет вероятно ще дойдат от 3 GB модули GDDR7 на същия интерфейс. Името, честотите и цената са неизвестни. В началото на октомври профилите в X hongxing2020 и MEGAsizeGPU също спекулираха съответно за края на варианта с 16 GB и за края на доставките на GB202 за RTX 5090. NVIDIA не е потвърдила нищо от това.", "zuverlaessigkeit_hinweis": "Форум на търговци Board Channels (Китай) плюс BenchLife; няколко източника, но без потвърждение от NVIDIA.", "ursprungsquelle": "Board Channels / BenchLife", "weitere_links": ["harukaze5719 в X", "hongxing2020 в X (10.10)", "MEGAsizeGPU в X (10.10)"], "_src": "60b93d53"}, "2026-10-29-windows11-kb5127936": {"titel": "Windows 11: незадължителната актуализация KB5127936 носи ново контекстно меню и преинсталиране от облака", "schlagzeile": "Windows 11: предварителна актуализация с ново контекстно меню и облачен ремонт", "kurz": "Microsoft пусна за Windows 11 25H2 и 26H2 незадължителната предварителна актуализация KB5127936 с 41 промени. Сред тях са по-бързо и персонализируемо контекстно меню във File Explorer и преинсталиране чрез Windows Update без USB флашка. Новостите трябва да стигнат до всички от Patch Tuesday на 10 ноември.", "zusammenfassung": "На 28 октомври Microsoft пусна незадължителната предварителна актуализация KB5127936 за Windows 11 25H2 и 26H2; тя не съдържа корекции за сигурност. Според BleepingComputer компилациите се повишават съответно до 26200.9818 и 26300.9818, с общо 41 промени и поправки. Контекстното меню във File Explorer трябва да се отваря по-бързо и да може да се персонализира. С „Cloud Rebuild“ Windows може да се преинсталира чрез Windows Update без USB флашка или ISO файл – дори ако системата вече не стартира. Режимът Xbox получава преработен изглед на задачите с лента за навигация, например за „Към работния плот“ и опциите за захранване. Страницата с настройки „Поверителност и защита“ групира камера, микрофон и местоположение, а средата за възстановяване WinRE може да използва запазени Wi-Fi профили. Хибернацията става адаптивна: над 80 процента батерия се включва по-рядко, под 10 процента – по-рано. Тъй като сертификатите на Secure Boot се обновяват, може да е нужно допълнително рестартиране. Актуализацията се инсталира през Настройки > Windows Update или от каталога на Microsoft Update. Microsoft пуска функциите постепенно, така че няма да се появят веднага на всеки компютър. Според Thurrott новостите трябва да стигнат до всички от Patch Tuesday на 10 ноември.", "weitere_links": ["Поддръжка на Microsoft: KB5127936 (компилации 26300.9818 и 26200.9818)", "Thurrott: предварителни актуализации от седмица D за Windows 11"], "_src": "b3b29ee6"}, "2026-10-29-gta6-edge-polizei": {"titel": "GTA 6: Rockstar показва полиция с K-9 отряд, автобуси по разписание и динамично време", "schlagzeile": "GTA 6: полиция с кучета следотърсачи, автобуси и влакове по разписание", "kurz": "В статия от корицата на британското списание Edge Rockstar разкри нови подробности за GTA 6. Полицията проследява играчите чрез камери, тракери в колите и сигнали от свидетели, а има и K-9 отряд. GTA 6 излиза на 19 ноември 2026 г. за PS5 и Xbox Series X|S.", "zusammenfassung": "Според Polygon Роб Нелсън, съръководител на студиото Rockstar North, е дал ексклузивно на британското списание Edge нови подробности за Grand Theft Auto VI. Полицията ще проследява играчите по последното им забелязване, камерите за наблюдение, тракери в колите и сигнали от минувачи. Новост е K-9 отряд: в показаното демо немска овчарка хваща Джейсън след катастрофа с мотор. Минувачите ще имат собствени черти на характера – едни бягат, други нападат. Автобусите и влаковете се движат по фиксирани маршрути по разписание; директорът по разработката Фил Хукър каза, че за него е най-важно винаги да пристигат навреме. Времето е динамично, като облаците се оформят от вятъра, влажността, мъглата, часа от денонощието и сезона. Самият Rockstar насочи вниманието в X към статията от корицата на брой 430 на Edge. Според Take-Two GTA 6 излиза на 19 ноември 2026 г. за PlayStation 5 и Xbox Series X|S. Standard Edition струва 79,99 долара в САЩ, а Ultimate Edition – 99,99 долара. Дигиталното предварително изтегляне и физическото издание са планирани от 12 ноември.", "weitere_links": ["Rockstar Games в X: насочване към статията от корицата на Edge (30.10.2026)", "Take-Two: предварителни поръчки, дата и цени на GTA VI"], "_src": "e7ef25df"}, "2026-10-28-galax-dementi": {"titel": "Слух опроверган: GALAX не напуска бизнеса с видеокарти", "schlagzeile": "Край на GALAX? Производителят казва ясно: не", "kurz": "Испански сайт съобщи „ексклузивно“, че GALAX напуска бизнеса с видеокарти. GALAX и партньорът Palit официално опровергаха това, а производството продължава нормално. За купувачите на карти KFA2, както се нарича GALAX в Европа, нищо не се променя.", "zusammenfassung": "Испанският сайт El Chapuzas Informático съобщи „ексклузивно“, че GALAX напуска пазара на GPU заради липса на чипове от NVIDIA и че Palit затваря съответната фабрика. GALAX опроверга това в официално изявление: нито един производствен обект не е затворен и работата продължава нормално. Palit, която дели фабрики с GALAX, също потвърди пред медиите, че производството продължава. Подобен слух се появи още през април във връзка с преструктуриране под централата на Palit в Тайван. Едва на 22 октомври GALAX представи RTX 5080 HOF Extreme. За купувачите на карти KFA2 – както се нарича GALAX в Европа – засега нищо не се променя по отношение на гаранцията или поддръжката. Случаят показва защо отбелязваме „ексклузивни“ единични съобщения без втори източник като непотвърдени.", "datum_hinweis": "Часът е приблизителен", "weitere_links": ["VideoCardz", "Tom's Hardware", "Първоначален слух (El Chapuzas Informático)"], "_src": "cf83f08b"}, "2026-10-25-ddr6-camm2": {"titel": "DDR6: 192-битови интерфейси на паметта и CAMM2 вместо класически DIMM модули", "schlagzeile": "DDR6 идва – и класическите RAM модули може да изчезнат", "kurz": "Според наличната информация DDR6 ще използва плоския формат CAMM2 вместо класическите DIMM модули, а настолните процесори ще получат 192-битов интерфейс на паметта. Споменават се скорости от 8800 до над 17 600 MT/s. Според пътна карта на SK Hynix обаче потребителите не бива да очакват DDR6 преди 2030 г.", "zusammenfassung": "3DCenter събра известното за предстоящия стандарт DDR6 и го допълни с актуализация на 25 октомври. DDR6 ще използва PAM4 сигнализация и ще работи с 24-битови чипове памет. Един модул ще се състои от четири 24-битови канала, а интерфейсите на паметта на процесорите растат на стъпки от 96 бита – при настолните компютри обикновено до 192 бита. Като формат е предвиден CAMM2 вместо днешните UDIMM и SO-DIMM модули. Споменават се скорости от 8800 до над 17 600 MT/s. Според пътна карта на SK Hynix DDR6 не се очаква преди 2029 г. в сървърите и преди 2030 г. за потребителите. Спецификацията на JEDEC още не е окончателна, обсъжда се и алтернативно предложение с 16-битови канали.", "datum_hinweis": "Дата на актуализацията; часът е приблизителен", "_src": "eef0b055"}, "2026-10-02-core-ultra-4000-lineup": {"titel": "Core Ultra 4000 „Nova Lake-S“: гамата начело с Core Ultra 9 4970K BFC", "schlagzeile": "Изтичане: 28-ядреният флагман на Intel с огромен кеш се цели в X3D на AMD", "kurz": "Изтекъл списък посочва седем настолни процесора от серията Core Ultra 4000, начело с Core Ultra 9 4970K с 28 ядра и голям кеш. Допълнителният кеш се смята за отговора на Intel на процесорите X3D на AMD. Intel не е потвърдил имена на модели, а подробностите може още да се променят.", "zusammenfassung": "В началото на октомври се появи списък със седем настолни процесора от предстоящата серия Core Ultra 4000. Начело трябва да е Core Ultra 9 4970K „BFC“ с 28 ядра, голям кеш от последно ниво (bLLC) и базова мощност 125 W, подреден дори над 4950K. bLLC се смята за отговора на Intel на процесорите X3D на AMD с 3D V-Cache. Известният източник на изтичания kopite7kimi коментира съобщението на 13 октомври: големият кеш трябва да спаси производителността на Nova Lake в игрите, защото обикновените модели без bLLC са в игрите приблизително толкова бързи, колкото Arrow Lake. Самият Intel досега не е посочил модели – официално са известни само процесът 18A-P и представяне на CES. Имената на моделите, броят ядра и стойностите на TDP може още да се променят до пускането.", "zuverlaessigkeit_hinweis": "Изтичане за гамата, коментирано от kopite7kimi (висока надеждност); не е потвърдено от Intel.", "weitere_links": ["kopite7kimi в X (13.10)"], "_src": "53d234c7"}, "2026-09-21-kopite-gr20x-2028": {"titel": "kopite7kimi: поколението GR20x на NVIDIA чак през 2028 г.", "schlagzeile": "Изтичане: следващите геймърски GPU на NVIDIA вероятно чак през 2028 г.", "kurz": "Известният източник на изтичания kopite7kimi пише, че чиповете GR20x на NVIDIA са продукт за 2028 г. – тоест следващото поколение се отлага. За 2027 г. тогава по-вероятни биха били обновени версии на серията RTX 50. NVIDIA не е потвърдила този график.", "zusammenfassung": "Известният източник на изтичания за NVIDIA kopite7kimi пише в X, че чиповете GR20x са продукт за 2028 г. – тоест NVIDIA отново е отложила. Според общоприетото тълкуване става дума за геймърското поколение след Blackwell, което вероятно ще носи името на архитектурата за центрове за данни на NVIDIA „Rubin“. Той освен това обяви, че ще публикува по-малко актуализации, докато няма сигурни новини, позовавайки се на „lessons learned“ (научени уроци) – очевидно реакция на променени планове при по-ранни изтичания. Нашата оценка: за 2027 г. тогава по-вероятни биха били обновени версии на серията RTX 50, например с повече памет като споменатата RTX 5080 24GB. Самата NVIDIA не е потвърдила нищо за този график. Дори при надеждни източници датите се местят по-често от техническите данни.", "zuverlaessigkeit_hinweis": "kopite7kimi има дълга история с изтичания за NVIDIA; данните за срокове обаче са по-несигурни от техническите подробности.", "ursprungsquelle": "kopite7kimi", "_src": "89b4f8c9"}};
